/// The path of every output `rigger docs` reports rendering in its `stdout`, in its order.
fn rendered_outputs(stdout: &str) -> Vec<String> {
    stdout
        .lines()
        .map(|line| {
            line.strip_prefix("rendered ./")
                .unwrap_or_else(|| panic!("`rigger docs` prints `rendered ./<path>`; got {line:?}"))
                .to_string()
        })
        .collect()
}

/// `rigger <args>` over a project whose docs `rigger docs` just rendered, once each output in
/// `edited` was hand-edited and each in `removed` deleted: it exits `code` and leaves every file's
/// bytes and modification time as they were. A check (exit 0 or 1) prints one line per output
/// still on disk, in render order - `drifted <path>` for an edited one and `fresh <path>` for the
/// rest; a refused argument (exit 2) prints nothing on stdout and names the `--check` form on
/// stderr.
fn assert_the_docs_verb(args: &[&str], edited: &[&str], removed: &[&str], code: i32) {
    let dir = temp_project();
    let root = dir.path();
    let outputs = rendered_outputs(&run_rigger_ok(root, &["docs"]));
    for rel in edited.iter().chain(removed) {
        assert!(
            outputs.iter().any(|output| output == rel),
            "{rel} must be one of the rendered outputs {outputs:?}"
        );
    }
    for rel in edited {
        append_line(&root.join(rel), "hand-edited line the render never emits");
    }
    for rel in removed {
        std::fs::remove_file(root.join(rel)).unwrap();
    }
    let before = tree_snapshot(root, &[]);

    let out = pipe_into_rigger(root, args, b"");
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert_eq!(
        out.status.code(),
        Some(code),
        "rigger {args:?} must exit {code}; stdout:\n{stdout}\nstderr:\n{stderr}"
    );
    let expected: String = if code == 2 {
        assert!(
            stderr.contains("rigger docs [--check]"),
            "a refused argument names the verb's one accepted form; stderr:\n{stderr}"
        );
        String::new()
    } else {
        outputs
            .iter()
            .filter(|rel| !removed.contains(&rel.as_str()))
            .map(|rel| {
                let verdict = if edited.contains(&rel.as_str()) {
                    "drifted"
                } else {
                    "fresh"
                };
                format!("{verdict} {rel}\n")
            })
            .collect()
    };
    assert_eq!(
        stdout, expected,
        "rigger {args:?} stdout; stderr:\n{stderr}"
    );
    assert!(
        tree_snapshot(root, &[]) == before,
        "rigger {args:?} must write nothing: every file keeps its bytes and modification time, \
         and no removed output comes back"
    );
}

rigger::test_cases! {
    /// `rigger docs --check` over a fresh render reports every output `fresh`, exits 0 and
    /// writes nothing - the check the docs pre-commit hook runs, so a commit never rewrites
    /// the working tree.
    docs_check_reports_every_output_fresh_and_writes_nothing:
        assert_the_docs_verb(&["docs", "--check"], &[], &[], 0);
    /// `rigger docs --check` reports a hand-edited output `drifted` - here a skill outside the
    /// `using-rigger` pair - and every other output `fresh`, exits 1, and leaves the edited
    /// file's bytes as they were.
    docs_check_reports_an_edited_output_drifted_and_leaves_its_bytes:
        assert_the_docs_verb(&["docs", "--check"], &["skills/spec-preflight/SKILL.md"], &[], 1);
    /// `rigger docs --check` skips an output absent from the tree, as the validate drift gate
    /// does, and never writes it.
    docs_check_skips_an_absent_output:
        assert_the_docs_verb(
            &["docs", "--check"],
            &[],
            &["docs/handbook/planning-field-guide.md"],
            0,
        );
    /// `rigger docs` given an argument other than `--check` refuses with exit 2 and renders
    /// nothing: the edited output keeps its edit and the removed one stays absent.
    docs_refuses_an_unknown_argument_and_renders_nothing:
        assert_the_docs_verb(
            &["docs", "--bogus"],
            &["skills/spec-preflight/SKILL.md"],
            &["docs/handbook/planning-field-guide.md"],
            2,
        );
    /// An unknown argument beside `--check` is refused the same way, never read as a check.
    docs_refuses_an_unknown_argument_beside_check:
        assert_the_docs_verb(
            &["docs", "--check", "--bogus"],
            &["skills/spec-preflight/SKILL.md"],
            &[],
            2,
        );
}

/// Spec 66, criterion 2 (the render pipeline covers the WHOLE handbook-page list, end to
/// end): `rigger docs` renders EVERY entry in the binary's handbook-page list - not only the
/// pre-existing `using-rigger.md` discipline chapter, but the second, generalized entry
/// `docs/handbook/planning-field-guide.md` too - carrying its real failure-catalog content.
/// This mirrors `docs_renders_every_registry_skill_including_planning_a_spec` (spec 68,
/// criterion 1) one layer over: THAT test proves the SKILL registry's generalization reaches
/// a second skill; this one proves the separate HANDBOOK-PAGE list's generalization reaches
/// a second handbook page. Driving the real binary proves the whole composition path
/// (docs_context -> the page's body -> write) actually produces the committed
/// file an author commits and the drift check re-renders against - the class of regression
/// an in-process test that only checks the returned path list (names/paths match, but the
/// loop silently re-renders entry 1 twice, or writes entry 2's bytes to entry 1's path)
/// cannot catch.
#[test]
fn docs_renders_the_planning_field_guide_second_handbook_page() {
    let proj = temp_project();
    let root = proj.path();

    let (stdout, stderr, ok) = run_rigger(root, &["docs"]);
    assert!(ok, "rigger docs must succeed; stderr: {stderr}");
    assert!(
        stdout.contains("using-rigger.md") && stdout.contains("planning-field-guide.md"),
        "rigger docs must report rendering BOTH handbook pages; got: {stdout}"
    );

    let handbook_path = root.join("docs/handbook/using-rigger.md");
    let guide_path = root.join("docs/handbook/planning-field-guide.md");
    assert!(
        handbook_path.exists(),
        "the pre-existing handbook chapter must still be rendered"
    );
    let handbook = std::fs::read_to_string(&handbook_path)
        .expect("the pre-existing handbook chapter must still be readable");
    let guide = std::fs::read_to_string(&guide_path)
        .expect("rigger docs must have written the second handbook page to disk");

    // The rendered file carries the field guide's real content, not a stub or the wrong
    // entry's bytes: its title, its full F1-F11 failure catalog (every class, not a subset),
    // the mid-run amendment protocol, and the measured-outcomes close.
    assert!(
        guide.starts_with("# Planning a loop run: the field guide"),
        "the guide must open with its own title; got: {}",
        &guide[..guide.len().min(60)]
    );
    for class in [
        "### F1 - Duplicated or ambiguously-owned units",
        "### F2 - Bundled criteria",
        "### F3 - The self-contradictory spec",
        "### F4 - Open dispositions",
        "### F5 - State that lives in the wrong place",
        "### F6 - Criteria that cannot survive verbatim copying",
        "### F7 - Unpinned environment",
        "### F8 - Infra noise misread as semantic failure",
        "### F9 - Unbounded claim surface",
        "### F10 - Landing-order circularity",
        "### F11 - Undecided removal",
    ] {
        assert!(
            guide.contains(class),
            "the rendered guide must carry catalog class {class:?}; got:\n{guide}"
        );
    }
    assert!(
        guide.contains("## Amending a spec mid-run")
            && guide.contains("## What good looks like, measured"),
        "the rendered guide must carry the amendment protocol and the measured-outcomes \
         close; got:\n{guide}"
    );

    // Byte-stable across runs (the drift check depends on it), and the untouched first entry
    // is undisturbed by rendering the second.
    let (_o2, _e2, ok2) = run_rigger(root, &["docs"]);
    assert!(ok2);
    assert_eq!(
        std::fs::read_to_string(&guide_path).unwrap(),
        guide,
        "a second render of the second handbook-page entry must be byte-identical"
    );
    assert_eq!(
        std::fs::read_to_string(&handbook_path).unwrap(),
        handbook,
        "the untouched first entry is byte-identical after rendering the second"
    );
}

/// Spec 20, unit 3 (setup install + project overlay, end to end): `rigger setup` installs
/// the rendered `using-rigger` skill, and a project overlay adds this repo's specifics (base branch, specs location) into the
/// installed skill WITHOUT editing the shared discipline source. Driving the real binary
/// proves the whole install path (overlay read -> merge onto docs_context -> render ->
/// write) lands a loadable skill carrying the repo's own facts.
#[test]
fn setup_installs_the_using_rigger_skill_with_project_overlay() {
    let proj = temp_project();
    let root = proj.path();

    // This repo declares its specifics in the overlay: a non-default base branch and a
    // non-default specs directory. `rigger docs` never sees this - it is the setup-time
    // project overlay, merged into the installed skill only.
    std::fs::create_dir_all(root.join(".rigger")).unwrap();
    std::fs::write(
        root.join(".rigger").join("docs-overlay.yml"),
        "base_ref: origin/trunk\nspecs_location: product-specs/\n",
    )
    .unwrap();

    let out = setup_ok(root, &[]);

    let skill_path = root.join(".claude/skills/using-rigger/SKILL.md");
    assert!(
        skill_path.exists(),
        "setup must install the using-rigger skill at .claude/skills/using-rigger/SKILL.md"
    );

    let skill = std::fs::read_to_string(&skill_path).expect("the skill was installed");
    assert!(
        skill.starts_with("---\nname: using-rigger\n"),
        "the installed skill is a loadable skill (frontmatter); got: {}",
        &skill[..skill.len().min(60)]
    );
    // The project overlay's repo specifics flow into the installed skill...
    assert!(
        skill.contains("origin/trunk"),
        "the overlay base branch must appear in the installed skill; got:\n{skill}"
    );
    assert!(
        skill.contains("product-specs/"),
        "the overlay specs location must appear in the installed skill; got:\n{skill}"
    );
    // ...and setup reports installing the skill.
    assert!(
        out.contains("using-rigger skill") && out.contains(".claude/skills/using-rigger/SKILL.md"),
        "setup must report installing the using-rigger skill; got:\n{out}"
    );

    // The shared discipline source is NOT edited by the overlay: `rigger docs` renders the
    // committed source with the DEFAULT base ref, not the overlay's.
    let (_o, _e, ok2) = run_rigger(root, &["docs"]);
    assert!(ok2, "rigger docs must succeed");
    let committed = std::fs::read_to_string(root.join("skills/using-rigger/SKILL.md")).unwrap();
    assert!(
        committed.contains("origin/main") && !committed.contains("origin/trunk"),
        "the committed shared source keeps the default base ref; the overlay only \
         customized the install"
    );
}

/// A project's docs overlay, relative to its root: this repository's own, and the one a fresh
/// project's `rigger setup` reads.
const DOCS_OVERLAY_REL: &str = ".rigger/docs-overlay.yml";

/// Run `rigger setup` in a fresh project whose [`DOCS_OVERLAY_REL`] reads `overlay`, then
/// `rigger docs` there: the installed `planning-a-spec` is this repository's committed skill with
/// `list` - the project's constraint block - set between step 6 and step 7, and the render
/// `rigger docs` writes is the committed skill byte for byte, so the overlay reaches the install
/// alone.
fn assert_setup_installs_the_planning_skill_carrying(overlay: &str, list: &str) {
    let proj = temp_project();
    let root = proj.path();
    common::cli::seed_rigger_dir(root);
    std::fs::write(root.join(DOCS_OVERLAY_REL), overlay).unwrap();
    setup_ok(root, &[]);

    let committed = repo_text("skills/planning-a-spec/SKILL.md");
    assert_eq!(
        std::fs::read_to_string(root.join(".claude/skills/planning-a-spec/SKILL.md")).unwrap(),
        committed.replacen("**7. ", &format!("{list}**7. "), 1),
        "rigger setup must install the committed planning-a-spec with the overlay's \
         constraints under step 6"
    );
    run_rigger_ok(root, &["docs"]);
    assert_eq!(
        std::fs::read_to_string(root.join("skills/planning-a-spec/SKILL.md")).unwrap(),
        committed,
        "rigger docs must render the committed planning-a-spec, without the overlay"
    );
}

rigger::test_cases! {
    /// Spec 121, criterion 13 (THE PLANNING SKILL CARRIES THE PROJECT'S CONSTRAINTS): given this
    /// repository's own overlay, when the operator runs `rigger setup`, the installed
    /// `planning-a-spec` carries its two Global constraints under step 6, in the overlay's order.
    setup_installs_this_repositorys_global_constraints_under_planning_step_6:
        assert_setup_installs_the_planning_skill_carrying(
            &repo_text(DOCS_OVERLAY_REL),
            common::fixtures::THIS_REPOSITORYS_PLANNING_CONSTRAINTS,
        );
    /// Spec 121, criterion 13: given an overlay that declares no `global_constraints`, when the
    /// operator runs `rigger setup`, the installed `planning-a-spec` is the committed skill, with
    /// no project list under step 6.
    setup_installs_no_project_list_from_an_overlay_without_global_constraints:
        assert_setup_installs_the_planning_skill_carrying("base_ref: origin/trunk\n", "");
}

/// Spec 68, criterion 1 (the INSTALL seam covers the WHOLE registry, end to end): `rigger
/// setup` installs EVERY entry in the registry into the consumer project, not only the
/// pre-existing `using-rigger` skill - `planning-a-spec` lands at its own installed path,
/// carrying the operator-binary prohibition, and setup REPORTS installing it. A no-op rerun
/// leaves the second entry untouched (no report line, no moved mtime), exactly like the
/// original one. Driving the real binary proves the install seam (`install_skills` looping
/// over `skill_registry()`) was actually generalized, not just the render/drift seams the
/// sibling tests above cover - install is a THIRD, independent consumer of the registry (its
/// own function, its own loop over `(name, InstallOutcome)` pairs), so a bug specific to that
/// loop (installing only the first entry, or reusing one `InstallOutcome` across every entry)
/// would pass every other test in this file and only show up here.
#[test]
fn setup_installs_every_registry_skill_into_the_consumer_project() {
    let proj = temp_project();
    let root = proj.path();

    let out = setup_ok(root, &[]);

    let using_rigger_installed = root.join(".claude/skills/using-rigger/SKILL.md");
    let planning_installed = root.join(".claude/skills/planning-a-spec/SKILL.md");
    assert!(
        using_rigger_installed.exists(),
        "setup must still install the original registry entry"
    );
    assert!(
        planning_installed.exists(),
        "setup must ALSO install the second, generalized registry entry at \
         .claude/skills/planning-a-spec/SKILL.md"
    );
    assert!(
        out.contains("planning-a-spec skill")
            && out.contains(".claude/skills/planning-a-spec/SKILL.md"),
        "setup must report installing the second registry entry too; got:\n{out}"
    );

    let installed = std::fs::read_to_string(&planning_installed)
        .expect("the second registry entry was installed");
    assert!(
        installed.starts_with("---\nname: planning-a-spec\n"),
        "the installed second entry is a loadable skill; got: {}",
        &installed[..installed.len().min(60)]
    );
    assert!(
        installed.contains("## Operator binary boundary"),
        "the installed second entry must carry the operator-binary prohibition too; \
         got:\n{installed}"
    );

    // Re-running setup on an up-to-date project is a true no-op for BOTH entries, not just the
    // original one - no file's mtime moves and no install/refresh line is printed for it.
    let before = std::fs::metadata(&planning_installed)
        .unwrap()
        .modified()
        .unwrap();
    std::thread::sleep(std::time::Duration::from_millis(20));
    let out2 = setup_ok(root, &[]);
    assert!(
        !out2.contains("installed the planning-a-spec skill")
            && !out2.contains("refreshed the drifted planning-a-spec skill"),
        "an already-current second entry must not be reported as installed/refreshed; \
         got:\n{out2}"
    );
    let after = std::fs::metadata(&planning_installed)
        .unwrap()
        .modified()
        .unwrap();
    assert_eq!(
        before, after,
        "an up-to-date second entry must not even move its mtime"
    );
}

/// Spec 121, criterion 14 (A PROJECT SKILL SHADOWS THE SHIPPED ONE), end to end. Given a project
/// holding its own `using-rigger` copy at `.rigger/skills/using-rigger/SKILL.md`, a near name
/// `.rigger/skills/using-riggers/SKILL.md` and an empty `.rigger/skills/planning-a-spec/`: when the
/// operator runs `rigger setup`, the copy installs verbatim in place of the shipped `using-rigger`
/// with no install line, every other registry skill installs its shipped render, and the report
/// lists both strays, by path, as shadowing no shipped skill; a rerun that changes nothing prints
/// the two stray lines and nothing else. When the operator then runs `rigger docs`, it renders the
/// same bytes as a project with no copy, and `rigger docs --check` and `rigger validate` (the drift
/// gate) pass.
#[test]
fn setup_installs_a_project_skill_copy_verbatim_and_lists_each_stray_while_docs_stay_shipped() {
    let proj = temp_project();
    let root = proj.path();
    let copy = "---\nname: using-rigger\ndescription: this project's own copy\n---\nOurs.\n";
    common::fixtures::write_files(
        root,
        &[
            (".rigger/skills/using-rigger/SKILL.md", copy),
            (".rigger/skills/using-riggers/SKILL.md", copy),
        ],
    );
    std::fs::create_dir_all(root.join(".rigger/skills/planning-a-spec")).unwrap();
    let names: Vec<&str> = rigger::docs::skill_registry()
        .iter()
        .map(|entry| entry.name)
        .collect();
    let stray_lines: Vec<String> = [
        ".rigger/skills/planning-a-spec",
        ".rigger/skills/using-riggers",
    ]
    .iter()
    .map(|stray| {
        format!(
            "{stray} shadows no shipped skill and installs nothing: a project copy is \
                 .rigger/skills/<name>/SKILL.md, <name> a shipped skill's exact name"
        )
    })
    .collect();

    let out = setup_ok(root, &[]);
    assert_eq!(
        out.lines()
            .filter(|line| line.contains(".rigger/skills/") || line.contains(".claude/skills/"))
            .map(str::to_string)
            .collect::<Vec<_>>(),
        stray_lines
            .iter()
            .cloned()
            .chain(
                names
                    .iter()
                    .filter(|&&name| name != "using-rigger")
                    .map(|name| format!(
                        "installed the {name} skill (.claude/skills/{name}/SKILL.md)"
                    ))
            )
            .collect::<Vec<_>>(),
        "setup lists each stray, then installs every unshadowed skill; got:\n{out}"
    );
    assert_eq!(
        std::fs::read_to_string(root.join(".claude/skills/using-rigger/SKILL.md")).unwrap(),
        copy,
        "the project copy installs verbatim"
    );
    let mut installed: Vec<String> = std::fs::read_dir(root.join(".claude/skills"))
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .collect();
    installed.sort();
    let mut expected: Vec<String> = names.iter().map(|name| name.to_string()).collect();
    expected.sort();
    assert_eq!(installed, expected, "a stray installs nothing");

    assert_eq!(
        setup_ok(root, &[]),
        stray_lines
            .iter()
            .map(|line| format!("{line}\n"))
            .collect::<String>(),
        "a rerun lists each stray again and reports nothing else"
    );

    let twin = temp_project();
    let outputs = rendered_outputs(&run_rigger_ok(root, &["docs"]));
    assert_eq!(
        outputs,
        rendered_outputs(&run_rigger_ok(twin.path(), &["docs"])),
        "rigger docs renders the same outputs beside a project copy"
    );
    for rel in &outputs {
        assert_eq!(
            std::fs::read(root.join(rel)).unwrap(),
            std::fs::read(twin.path().join(rel)).unwrap(),
            "rigger docs renders {rel}'s shipped text beside a project copy"
        );
    }
    assert_eq!(
        run_rigger_ok(root, &["docs", "--check"]),
        run_rigger_ok(twin.path(), &["docs", "--check"]),
        "the pre-commit check finds a project copy no drift"
    );
    let (_, err, ok) = run_rigger(root, &["validate"]);
    assert!(
        ok,
        "the drift gate passes beside a project copy; stderr:\n{err}"
    );
}

/// Where a project keeps its own copy of the `using-rigger` skill, relative to its root.
const USING_RIGGER_PROJECT_COPY_REL: &str = ".rigger/skills/using-rigger/SKILL.md";

/// The text of a project's own `using-rigger` copy in the shadow periphery tests below.
const USING_RIGGER_PROJECT_COPY: &str =
    "---\nname: using-rigger\ndescription: a project's own using-rigger\n---\nOur discipline.\n";

/// The text that copy holds once the project edits it.
const USING_RIGGER_EDITED_PROJECT_COPY: &str =
    "---\nname: using-rigger\ndescription: a project's own using-rigger\n---\nOur new discipline.\n";

/// Spec 121, criterion 14 (the shadow's setup report lines, end to end). Given a project `rigger
/// setup` already provisioned, when its own `using-rigger` copy lands under `.rigger/skills/` and
/// the operator reruns `rigger setup`, then the copy replaces the installed shipped render and
/// setup prints nothing, a shadow being a state rather than a change. When `edit` then writes its
/// text at its root-relative path, or deletes that directory for `None`, and the operator reruns
/// `rigger setup` again, then the installed `using-rigger` holds `installed` and setup prints
/// nothing; for `installed` `None` it holds the shipped render the first setup installed, and
/// setup prints its version line, the refresh of `using-rigger` and the orientation block the
/// first setup's report ended with, nothing else.
fn assert_setup_reruns_beside_a_shadow(edit: (&str, Option<&str>), installed: Option<&str>) {
    let proj = temp_project();
    let root = proj.path();
    let installed_path = root.join(".claude/skills/using-rigger/SKILL.md");
    let setup = || {
        (
            setup_ok(root, &[]),
            std::fs::read_to_string(&installed_path).unwrap(),
        )
    };
    let (first, shipped) = setup();
    let orientation = &first[first
        .find("to drive a run")
        .expect("a setup that reports a change ends with its orientation block")..];
    common::fixtures::write_files(
        root,
        &[(USING_RIGGER_PROJECT_COPY_REL, USING_RIGGER_PROJECT_COPY)],
    );
    assert_eq!(
        setup(),
        (String::new(), USING_RIGGER_PROJECT_COPY.to_string()),
        "a copy landing on a provisioned project replaces the shipped install and setup prints \
         nothing"
    );

    match edit {
        (rel, Some(text)) => common::fixtures::write_files(root, &[(rel, text)]),
        (rel, None) => std::fs::remove_dir_all(root.join(rel)).unwrap(),
    }
    let report = match installed {
        Some(_) => String::new(),
        None => format!(
            "{}refreshed the drifted using-rigger skill (.claude/skills/using-rigger/SKILL.md) to \
             match this rigger build\n{orientation}",
            run_rigger_ok(root, &["version"])
        ),
    };
    assert_eq!(
        setup(),
        (report, installed.map_or(shipped, str::to_string)),
        "the rerun's report and the installed using-rigger after {edit:?}"
    );
}

rigger::test_cases! {
    /// An operator's hand-edit of a shadowed skill's installed file is rewritten to the project
    /// copy, and setup reports nothing.
    setup_rewrites_a_hand_edited_shadowed_skill_to_its_project_copy_silently:
        assert_setup_reruns_beside_a_shadow(
            (".claude/skills/using-rigger/SKILL.md", Some("an operator's hand-edit\n")),
            Some(USING_RIGGER_PROJECT_COPY),
        );
    /// A project copy the project edited installs on the next setup, and setup reports nothing.
    setup_installs_an_edited_project_copy_silently:
        assert_setup_reruns_beside_a_shadow(
            (USING_RIGGER_PROJECT_COPY_REL, Some(USING_RIGGER_EDITED_PROJECT_COPY)),
            Some(USING_RIGGER_EDITED_PROJECT_COPY),
        );
    /// A project copy deleted (DROPPED): the next setup installs the shipped render again and
    /// reports it as a refresh.
    setup_refreshes_a_skill_whose_project_copy_was_deleted_to_the_shipped_render:
        assert_setup_reruns_beside_a_shadow((".rigger/skills/using-rigger", None), None);
}

/// Spec 121, criterion 14 (an unreadable project copy fails setup). Given `seeded`, a
/// root-relative path `rigger setup` reads for the project's skill copies, made a directory where
/// a file is read (`dir`) or a file where a directory is listed, when the operator runs `rigger
/// setup`, then it fails printing nothing on stdout and, on stderr, the one line naming that path
/// and the error reading it gives, and installs no skill.
fn assert_setup_refuses_an_unreadable_project_skill(seeded: &str, dir: bool) {
    let proj = temp_project();
    let root = proj.path();
    let path = root.join(seeded);
    let error = if dir {
        std::fs::create_dir_all(&path).unwrap();
        std::fs::read(&path).unwrap_err()
    } else {
        common::fixtures::write_files(root, &[(seeded, "not a directory\n")]);
        std::fs::read_dir(&path).unwrap_err()
    };
    assert_eq!(
        run_rigger_envs(root, &["setup"], &[]),
        (
            String::new(),
            format!(
                "rigger: setup: reading {}: {error}\n",
                Path::new(".").join(seeded).display()
            ),
            false,
        ),
        "setup's stdout, stderr and success"
    );
    assert!(
        !root.join(".claude/skills").exists(),
        "setup installs no skill beside a project copy it cannot read"
    );
}

rigger::test_cases! {
    /// A project copy `SKILL.md` that is a directory fails setup naming it.
    setup_fails_naming_a_project_copy_that_is_a_directory:
        assert_setup_refuses_an_unreadable_project_skill(USING_RIGGER_PROJECT_COPY_REL, true);
    /// A `.rigger/skills` that is a plain file fails setup naming it.
    setup_fails_naming_a_project_skill_home_that_is_a_file:
        assert_setup_refuses_an_unreadable_project_skill(".rigger/skills", false);
}

/// Spec 121, criterion 14 (the drift gate stays on the shipped text, from the drift side). Given a
/// project whose docs `rigger docs` rendered and whose own `using-rigger` copy sits under
/// `.rigger/skills/`, when the committed `skills/using-rigger/SKILL.md` holds that copy's text,
/// then `rigger docs --check` exits 1 reporting it, alone, drifted, and `rigger validate` fails
/// naming it alone; when the operator runs `rigger docs`, then the committed file holds the
/// shipped text it held before the copy, and both pass naming no output.
#[test]
fn the_drift_gate_reports_a_committed_project_copy_drifted_beside_its_shadow() {
    let dir = docs_rendered_project();
    let root = dir.path();
    let rel = "skills/using-rigger/SKILL.md";
    let outputs = rendered_outputs(&run_rigger_ok(root, &["docs"]));
    let shipped = std::fs::read(root.join(rel)).unwrap();
    common::fixtures::write_files(
        root,
        &[
            (USING_RIGGER_PROJECT_COPY_REL, USING_RIGGER_PROJECT_COPY),
            (rel, USING_RIGGER_PROJECT_COPY),
        ],
    );
    let gate = || {
        let check = pipe_into_rigger(root, &["docs", "--check"], b"");
        let (_, err, ok) = run_rigger(root, &["validate"]);
        (
            check.status.code(),
            String::from_utf8_lossy(&check.stdout)
                .lines()
                .filter_map(|line| line.strip_prefix("drifted "))
                .map(str::to_string)
                .collect::<Vec<_>>(),
            ok,
            outputs
                .iter()
                .filter(|output| err.contains(output.as_str()))
                .cloned()
                .collect::<Vec<_>>(),
        )
    };

    assert_eq!(
        gate(),
        (Some(1), vec![rel.to_string()], false, vec![rel.to_string()]),
        "docs --check (exit code, drifted outputs) and validate (success, outputs named) over a \
         committed project copy"
    );
    run_rigger_ok(root, &["docs"]);
    assert_eq!(
        std::fs::read(root.join(rel)).unwrap(),
        shipped,
        "rigger docs restores the shipped text beside the project copy"
    );
    assert_eq!(
        gate(),
        (Some(0), Vec::new(), true, Vec::new()),
        "docs --check and validate over the restored shipped text"
    );
}

/// The four per-operation skill names spec 68, criterion 2 adds to the registry (rigger-docs,
/// rigger-validate, and rigger-setup already loop over `skill_registry()` generically as of
/// spec 68, criterion 1 - shared by the three tests below).
const PER_OPERATION_SKILL_NAMES: [&str; 4] = [
    "rigger-reset-store",
    "rigger-build-graph",
    "rigger-resume-a-run",
    "rigger-handle-an-escalation",
];

/// Drive the COMPILED `rigger docs` over a fresh project and prove it renders each registry
/// skill in `names` to its own committed `skills/<name>/SKILL.md` - reported, opening with its
/// own loadable frontmatter, carrying its Procedure/Anti-move sections and the
/// structurally-stamped operator-binary prohibition, and byte-stable across a second render.
fn docs_rendered_skill_family(names: &[&str]) -> tempfile::TempDir {
    let proj = temp_project();
    let root = proj.path();

    let (stdout, stderr, ok) = run_rigger(root, &["docs"]);
    assert!(ok, "rigger docs must succeed; stderr: {stderr}");

    for &name in names {
        let rel = format!("skills/{name}/SKILL.md");
        assert!(
            stdout.contains(&rel),
            "rigger docs must report rendering {name} at {rel}; got: {stdout}"
        );

        let path = root.join(&rel);
        let rendered = common::fixtures::read_text(&path);
        assert!(
            rendered.starts_with(&format!("---\nname: {name}\n")),
            "{name}: must open with its own loadable frontmatter; got: {}",
            &rendered[..rendered.len().min(60)]
        );
        assert!(
            rendered.contains("## Procedure") && rendered.contains("## Anti-move"),
            "{name}: rendered skill must carry its Procedure and Anti-move sections; \
             got:\n{rendered}"
        );
        assert!(
            rendered.contains("## Operator binary boundary")
                && rendered.contains("never installs, replaces, or modifies the operator's"),
            "{name}: rendered skill must carry the structurally-stamped operator-binary \
             prohibition; got:\n{rendered}"
        );

        // Byte-stable across runs (the drift check the next test relies on depends on this).
        let (_o2, _e2, ok2) = run_rigger(root, &["docs"]);
        assert!(ok2, "a second `rigger docs` run must succeed");
        assert_eq!(
            std::fs::read_to_string(&path).unwrap(),
            rendered,
            "{name}: a second render must be byte-identical"
        );
    }
    proj
}

/// Spec 68, criterion 2 (the render pipeline reaches all FIVE new registry entries, end to
/// end): `rigger docs` renders every per-operation skill spec 68, criterion 2 adds - not just
/// the pre-existing `using-rigger`/`planning-a-spec` pair the sibling tests above drive - each
/// to its own committed `skills/<name>/SKILL.md` path, with its own loadable frontmatter and
/// the structurally-stamped operator-binary prohibition. The sibling
/// `docs_renders_every_registry_skill_including_planning_a_spec` test proved the render
/// pipeline reaches a SECOND entry; it never drove the five entries THIS unit adds, so a
/// path-wiring bug specific to one of them (skill_source_rel mapping a name to the wrong
/// directory, or a registry entry silently dropped from the loop) would satisfy every existing
/// binary-driving test and only show up here. The implementer's own in-process
/// `write_docs_writes_every_registry_skill_plus_the_handbook` and
/// `install_and_docs_each_cover_exactly_the_registry_no_more_no_less` tests (src/main.rs) call
/// `write_docs`/`install_skills` directly in-process; this drives the actual COMPILED binary
/// and reads back what it wrote to disk, which an in-process call cannot prove.
#[test]
fn docs_renders_every_per_operation_skill_through_the_compiled_binary() {
    docs_rendered_skill_family(&PER_OPERATION_SKILL_NAMES);
}

/// `rigger setup` installs every skill in `names` into the consumer project at its own
/// `.claude/skills/<name>/SKILL.md` path, loadable and carrying the operator-binary
/// prohibition, and reports installing it; a no-op rerun leaves every one of them untouched
/// (no install/refresh report line, not even a moved mtime). Returns the project for a caller
/// that goes on to act on it.
fn assert_setup_installs_each_skill(names: &[&str]) -> tempfile::TempDir {
    let proj = temp_project();
    let root = proj.path();

    let out = setup_ok(root, &[]);

    let mut installed_before = Vec::new();
    for &name in names {
        let installed_path = root.join(format!(".claude/skills/{name}/SKILL.md"));
        assert!(
            installed_path.exists(),
            "setup must install {name} at .claude/skills/{name}/SKILL.md"
        );
        assert!(
            out.contains(&format!("installed the {name} skill"))
                && out.contains(&format!(".claude/skills/{name}/SKILL.md")),
            "setup must report installing {name}; got:\n{out}"
        );

        let installed = common::fixtures::read_text(&installed_path);
        assert!(
            installed.starts_with(&format!("---\nname: {name}\n")),
            "the installed {name} skill must be loadable; got: {}",
            &installed[..installed.len().min(60)]
        );
        assert!(
            installed.contains("## Operator binary boundary"),
            "the installed {name} skill must carry the operator-binary prohibition too; \
             got:\n{installed}"
        );

        let mtime = std::fs::metadata(&installed_path)
            .unwrap()
            .modified()
            .unwrap();
        installed_before.push((name, installed_path, mtime));
    }

    // A no-op rerun leaves every one of them untouched: no install/refresh report line,
    // and not even a moved mtime.
    std::thread::sleep(std::time::Duration::from_millis(20));
    let out2 = setup_ok(root, &[]);
    for (name, installed_path, before) in installed_before {
        assert!(
            !out2.contains(&format!("installed the {name} skill"))
                && !out2.contains(&format!("refreshed the drifted {name} skill")),
            "an already-current {name} must not be reported as installed/refreshed; \
             got:\n{out2}"
        );
        let after = std::fs::metadata(&installed_path)
            .unwrap()
            .modified()
            .unwrap();
        assert_eq!(
            before, after,
            "an up-to-date {name} must not even move its mtime"
        );
    }
    proj
}

