/// The bytes spec 112 ships as the `spec-preflight` skill body, found literally: the text after
/// the opening fence line that follows its Notes sentence naming the shipped body, up to the next
/// line that is exactly three backticks - the body holds no such line.
fn spec_112_preflight_body() -> String {
    let spec = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("specs/112-the-spec-is-critiqued-before-the-run.md"),
    )
    .expect("spec 112 is committed");
    let (_, fenced) = spec
        .split_once(
            "The shipped `spec-preflight` body, byte for byte between the fence lines:\n\n```\n",
        )
        .expect("spec 112's Notes name the shipped body and open its fence on the next line");
    let (body, _) = fenced
        .split_once("\n```\n")
        .expect("a line of exactly three backticks closes the shipped body");
    format!("{body}\n")
}

/// The `spec-preflight` skill as `rigger setup` installs it and `rigger docs` renders it: spec
/// 112's shipped body plus the operator-binary section every registry skill carries.
fn shipped_spec_preflight_skill() -> String {
    format!(
        "{}{}",
        spec_112_preflight_body(),
        rigger::docs::OPERATOR_BINARY_PROHIBITION
    )
}

/// Every code span of `text` ([`rigger::spec::code_spans`], read line by line) that is a
/// relative path (opening `./` or `../`), in order, each asserted to name an existing file from
/// `dir`, the directory the skill file sits in - so a skill that names no absolute path still
/// names only files its reader can open.
fn relative_references_resolving_from(text: &str, dir: &Path) -> Vec<String> {
    let references: Vec<String> = text
        .lines()
        .flat_map(rigger::spec::code_spans)
        .filter(|span| span.starts_with("./") || span.starts_with("../"))
        .collect();
    for reference in &references {
        assert!(
            dir.join(reference).is_file(),
            "{reference:?} must name a file from {}",
            dir.display()
        );
    }
    references
}

/// No line of `text` holds an absolute or home path, so the file reads the same in every
/// checkout it is installed into: a `/` or `~` inside a whitespace token is relative only when
/// the character before it is an ASCII alphanumeric, `.`, `-`, `_` or `/` - one at the token
/// start, or after any other character (a quote, `=`, `:`, a bracket, a redirect, a comma, a
/// pipe, ...), opens a path and fails (`d112-op-home-path-allowlist`) - and no line names
/// `$HOME`, `${HOME}`, the project `root` or the operator's home directory (a home of `/` or
/// none is not looked for).
fn assert_no_absolute_or_home_path(text: &str, root: &Path) {
    let home = std::env::var("HOME").unwrap_or_default();
    let root = root.to_str().expect("a utf-8 project root");
    let names = ["$HOME", "${HOME}", root, home.as_str()];
    for (n, line) in text.lines().enumerate() {
        for token in line.split_whitespace() {
            for (at, _) in token.match_indices(['/', '~']) {
                let before = token[..at].chars().next_back();
                assert!(
                    before.is_some_and(|c| c.is_ascii_alphanumeric() || ".-_/".contains(c)),
                    "line {}: {token:?} holds an absolute or home path:\n{line}",
                    n + 1
                );
            }
        }
        for name in names.iter().filter(|name| name.len() > 1) {
            assert!(
                !line.contains(name),
                "line {} names {name:?}:\n{line}",
                n + 1
            );
        }
    }
}

/// Runs [`assert_no_absolute_or_home_path`] over one probe `text` against a project root no
/// probe names, so each probe fails on its own spelling alone.
fn probe_no_absolute_or_home_path(text: &str) {
    assert_no_absolute_or_home_path(text, Path::new("/a-project-root-no-probe-names"));
}

rigger::test_cases! {
    /// The no-absolute-or-home-path check fails on a token opening with `/`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_token_opening_with_a_slash:
        probe_no_absolute_or_home_path("Read /repo/specs/112.md first.\n");
    /// The check fails on a token opening with `~`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_token_opening_with_a_tilde:
        probe_no_absolute_or_home_path("Copy it to ~/.claude/skills/spec-preflight.\n");
    /// The check fails on `$HOME` anywhere in a line.
    #[should_panic(expected = "names \"$HOME\"")]
    home_path_check_fails_on_dollar_home:
        probe_no_absolute_or_home_path("Copy it to $HOME/.claude/skills/spec-preflight.\n");
    /// The check fails on `${HOME}` anywhere in a line, a `${HOME}` no slash follows
    /// included, which only the name rule catches (a slash after its `}` opens a path).
    #[should_panic(expected = "names \"${HOME}\"")]
    home_path_check_fails_on_braced_home:
        probe_no_absolute_or_home_path("Copy it into ${HOME} under .claude.\n");
    /// The check fails on a JSON value holding an absolute path: a `/` right after a `"`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_json_value_holding_an_absolute_path:
        probe_no_absolute_or_home_path(
            "rigger emit DecisionMade '{\"governs\":[\"/repo/specs/112.md\"]}'\n",
        );
    /// The check fails on a `/` right after a `'` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_single_quoted_absolute_path_inside_a_token:
        probe_no_absolute_or_home_path("rigger critique --spec='/repo/specs/112.md'\n");
    /// The check fails on a `/` right after a `=` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_flag_equals_an_absolute_path:
        probe_no_absolute_or_home_path("rigger critique --spec=/repo/specs/112.md\n");
    /// The check fails on a `~` right after a `=` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_flag_equals_a_home_path:
        probe_no_absolute_or_home_path("rigger setup --skills=~/.claude/skills\n");
    /// The check fails on a `/` right after a `:` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_colon_then_an_absolute_path:
        probe_no_absolute_or_home_path("PATH=bin:/repo/target/debug\n");
    /// The check fails on a `/` right after a `[` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_bracket_then_an_absolute_path:
        probe_no_absolute_or_home_path("governs=[/repo/specs/112.md]\n");
    /// The check fails on a `/` right after a `(` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_link_target_holding_an_absolute_path:
        probe_no_absolute_or_home_path("See [spec 112](/repo/specs/112.md).\n");
    /// The check fails on a `/` right after a `<` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_an_angle_bracket_then_an_absolute_path:
        probe_no_absolute_or_home_path("See spec<</repo/specs/112.md>.\n");
    /// The check fails on a `/` right after a backtick inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_backtick_then_an_absolute_path:
        probe_no_absolute_or_home_path("Read spec`/repo/specs/112.md` first.\n");
    /// The check fails on a `/` right after a `>` inside a token: a redirect to an absolute
    /// path (`d112-op-home-path-allowlist`).
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_stderr_redirect_to_an_absolute_path:
        probe_no_absolute_or_home_path("rigger critique spec.md 2>/dev/null\n");
    /// The check fails on a `/` right after a token-opening `>`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_redirect_opening_a_token:
        probe_no_absolute_or_home_path("rigger critique spec.md >/tmp/x\n");
    /// The check fails on a `/` right after a `,` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_comma_then_an_absolute_path:
        probe_no_absolute_or_home_path("rigger critique --paths=a.md,/srv/b.md\n");
    /// The check fails on a `/` right after a token-opening `|`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_pipe_then_an_absolute_path:
        probe_no_absolute_or_home_path("rigger critique spec.md |/usr/bin/tee\n");
    /// The check fails on a `/` right after a `;` inside a token.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_semicolon_then_an_absolute_path:
        probe_no_absolute_or_home_path("x;/srv/bin/run\n");
    /// The check fails on a `/` right after a token-opening `@`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_an_at_sign_then_an_absolute_path:
        probe_no_absolute_or_home_path("curl -d @/srv/p.json\n");
    /// The check fails on a `/` right after a token-opening `{`.
    #[should_panic(expected = "an absolute or home path")]
    home_path_check_fails_on_a_brace_then_an_absolute_path:
        probe_no_absolute_or_home_path("cp {/srv/b.md} .\n");
    /// The check fails on the project root named inside a token after a character that opens
    /// no path, which only the name rule catches.
    #[should_panic(expected = "line 1 names \"/a-project-root-no-probe-names\":\n")]
    home_path_check_fails_on_the_project_root_named_inside_a_token:
        probe_no_absolute_or_home_path("Read spec/a-project-root-no-probe-names/specs/112.md.\n");
}

/// The check fails on the operator's home directory named inside a token after a character
/// that opens no path, which only the name rule catches; the failure names that home and the
/// line holding it.
#[test]
fn home_path_check_fails_on_the_operator_home_named_inside_a_token() {
    let home = std::env::var("HOME").expect("the test process has a HOME");
    assert!(
        home.len() > 1,
        "a home of / or none is not looked for; got {home:?}"
    );
    let line = format!("Read spec{home}/specs/112.md.");
    let failure = std::panic::catch_unwind(|| probe_no_absolute_or_home_path(&format!("{line}\n")))
        .expect_err("a line naming the operator's home must fail the check");
    assert_eq!(
        failure.downcast_ref::<String>().map(String::as_str),
        Some(format!("line 1 names {home:?}:\n{line}").as_str()),
        "the failure names the operator's home and the line holding it"
    );
}

/// Spec 112, criterion 4 (SETUP SHIPS THE PREFLIGHT SKILL). Given a project with no skills
/// directory, when the operator runs `rigger setup`, then `spec-preflight` lands at
/// `.claude/skills/spec-preflight/SKILL.md` from the skill registry - reported, loadable, its
/// bytes exactly spec 112's shipped body plus the operator-binary section every registry skill
/// carries, naming no absolute or home path - and a rerun writes nothing. Given an installed copy
/// with a line deleted, when setup runs again, then it reports refreshing the drifted skill and
/// the file is the shipped bytes again, as for every registry skill. The `planning-a-spec` skill
/// the same setup installs carries the F10 and F11 rows of the churn table.
#[test]
fn setup_ships_the_spec_preflight_skill_and_refreshes_it_on_drift() {
    let proj = assert_setup_installs_each_skill(&["spec-preflight"]);
    let root = proj.path();
    let installed_path = root.join(".claude/skills/spec-preflight/SKILL.md");
    let shipped = shipped_spec_preflight_skill();
    let installed = std::fs::read_to_string(&installed_path).expect("setup installed it");
    assert_eq!(
        installed, shipped,
        "the installed spec-preflight skill must be spec 112's shipped body, byte for byte, \
         plus the operator-binary section"
    );
    assert_no_absolute_or_home_path(&installed, root);

    let dropped: String = installed
        .lines()
        .filter(|line| *line != "## Step 3: the adversary pass")
        .map(|line| format!("{line}\n"))
        .collect();
    assert_eq!(
        dropped.lines().count() + 1,
        installed.lines().count(),
        "the drifted copy is the installed one with exactly one line deleted"
    );
    std::fs::write(&installed_path, &dropped).unwrap();
    let out = setup_ok(root, &[]);
    assert!(
        out.contains(
            "refreshed the drifted spec-preflight skill (.claude/skills/spec-preflight/SKILL.md)"
        ),
        "setup must report refreshing the drifted spec-preflight skill; got:\n{out}"
    );
    assert_eq!(
        std::fs::read_to_string(&installed_path).unwrap(),
        shipped,
        "the refresh must restore the shipped bytes"
    );

    let planning = std::fs::read_to_string(root.join(".claude/skills/planning-a-spec/SKILL.md"))
        .expect("setup installed planning-a-spec");
    for class in [
        "| F10 landing-order circularity |",
        "| F11 undecided removal |",
    ] {
        assert!(
            planning.contains(class),
            "the installed planning-a-spec churn table must carry the {class:?} row; \
             got:\n{planning}"
        );
    }
}

/// Spec 112, criterion 4 (the RENDER seam reaches the preflight skill, through the compiled
/// binary): given a fresh project, when the operator runs `rigger docs`, then it reports writing
/// `skills/spec-preflight/SKILL.md`, that file is spec 112's shipped body plus the
/// operator-binary section byte for byte, the one relative reference it carries names the
/// `planning-a-spec` skill the same render wrote beside it, and a second render writes the
/// same bytes. `write_docs` walks the registry in its own loop,
/// apart from the install loop the setup tests drive, and its output is the committed copy the
/// docs-drift gate compares.
#[test]
fn docs_renders_the_spec_preflight_skill_through_the_compiled_binary() {
    let proj = temp_project();
    let root = proj.path();
    let rel = "skills/spec-preflight/SKILL.md";

    let (out, err, ok) = run_rigger(root, &["docs"]);
    assert!(ok, "rigger docs must succeed; stderr:\n{err}");
    assert!(
        out.contains(rel),
        "rigger docs must report rendering {rel}; got:\n{out}"
    );
    let path = root.join(rel);
    let rendered = std::fs::read_to_string(&path).expect("rigger docs wrote the skill");
    assert_eq!(
        rendered,
        shipped_spec_preflight_skill(),
        "the rendered spec-preflight skill must be spec 112's shipped body, byte for byte, plus \
         the operator-binary section"
    );
    assert_eq!(
        relative_references_resolving_from(&rendered, path.parent().unwrap()),
        ["../planning-a-spec/SKILL.md"],
        "the rendered skill names exactly one relative file, the planning-a-spec skill beside it"
    );

    let (_out, err, ok) = run_rigger(root, &["docs"]);
    assert!(ok, "a second rigger docs run must succeed; stderr:\n{err}");
    assert_eq!(
        std::fs::read_to_string(&path).unwrap(),
        rendered,
        "a second render must be byte-identical"
    );
}

/// The modification time of each skill installed under `skills_dir` but `except`, by name.
fn installed_skill_mtimes(
    skills_dir: &Path,
    except: &str,
) -> std::collections::BTreeMap<String, std::time::SystemTime> {
    std::fs::read_dir(skills_dir)
        .expect("setup made the skills directory")
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .filter(|name| name != except)
        .map(|name| {
            let mtime = std::fs::metadata(skills_dir.join(&name).join("SKILL.md"))
                .unwrap()
                .modified()
                .unwrap();
            (name, mtime)
        })
        .collect()
}

/// Spec 112, criterion 4 (existing data, the upgrade path): given a set-up project missing only
/// `spec-preflight` - `rigger setup` ran and that one skill's directory is gone, so every other
/// registry skill is installed and current - when the operator reruns `rigger setup`, then the
/// project gains that skill alone: the one skill line it prints installs `spec-preflight`, the
/// file holds the shipped bytes and its relative reference names the installed
/// `planning-a-spec` skill beside it, and setup rewrites none of the others, every other
/// registry skill keeping its mtime.
#[test]
fn setup_gives_a_set_up_project_missing_only_the_preflight_skill_that_skill_alone() {
    let proj = temp_project();
    let root = proj.path();
    setup_ok(root, &[]);
    let skills_dir = root.join(".claude/skills");
    std::fs::remove_dir_all(skills_dir.join("spec-preflight")).unwrap();
    let before = installed_skill_mtimes(&skills_dir, "spec-preflight");
    let mut others: Vec<&str> = rigger::docs::skill_registry()
        .iter()
        .map(|entry| entry.name)
        .filter(|name| *name != "spec-preflight")
        .collect();
    others.sort_unstable();
    assert_eq!(
        before.keys().map(String::as_str).collect::<Vec<_>>(),
        others,
        "the provisioned project holds every other registry skill and no spec-preflight"
    );

    std::thread::sleep(std::time::Duration::from_millis(20));
    let out = setup_ok(root, &[]);
    assert_eq!(
        out.lines()
            .filter(|line| line.contains(" skill (.claude/skills/"))
            .collect::<Vec<_>>(),
        ["installed the spec-preflight skill (.claude/skills/spec-preflight/SKILL.md)"],
        "the upgrade installs spec-preflight and reports no other skill; got:\n{out}"
    );
    let installed_path = skills_dir.join("spec-preflight/SKILL.md");
    let installed = std::fs::read_to_string(&installed_path).expect("setup installed it");
    assert_eq!(
        installed,
        shipped_spec_preflight_skill(),
        "the upgrade installs the shipped bytes"
    );
    assert_eq!(
        relative_references_resolving_from(&installed, installed_path.parent().unwrap()),
        ["../planning-a-spec/SKILL.md"],
        "the installed skill names exactly one relative file, the installed planning-a-spec \
         skill beside it"
    );
    assert_eq!(
        installed_skill_mtimes(&skills_dir, "spec-preflight"),
        before,
        "the upgrade rewrites no other registry skill"
    );
}

/// Spec 112, criterion 4 (the DROPPED corner, and the Notes rule that a copy outside the
/// project is the operator's): given a project under the operator's home holding a
/// hand-authored `.claude/skills/spec-preflight/SKILL.md`, and that home holding its own
/// `spec-preflight` skill at `.claude/skills/spec-preflight/SKILL.md`, when the operator runs
/// `rigger setup` in the project, then the project copy is reported as a refreshed drifted
/// skill and holds the shipped bytes, while the home copy keeps its bytes and its mtime and
/// the home's `.claude` gains nothing.
#[test]
fn setup_overwrites_a_hand_authored_project_preflight_copy_and_never_one_outside_the_project() {
    let home = tempfile::tempdir().expect("create a temp home");
    let root = home.path().join("project");
    std::fs::create_dir(&root).unwrap();
    git_ok(&root, &["init", "-q"]);
    let hand_authored =
        "---\nname: spec-preflight\ndescription: the operator's own preflight\n---\n\n# Mine\n";
    let copy_in = |dir: &Path| {
        let path = dir.join(".claude/skills/spec-preflight/SKILL.md");
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, hand_authored).unwrap();
        path
    };
    let home_copy = copy_in(home.path());
    let project_copy = copy_in(&root);
    let home_mtime = std::fs::metadata(&home_copy).unwrap().modified().unwrap();

    std::thread::sleep(std::time::Duration::from_millis(20));
    let out = setup_ok(
        &root,
        &[("HOME", home.path().to_str().expect("a utf-8 home"))],
    );
    assert!(
        out.contains(
            "refreshed the drifted spec-preflight skill (.claude/skills/spec-preflight/SKILL.md)"
        ) && !out.contains("installed the spec-preflight skill"),
        "a hand-authored project copy is drift, refreshed rather than installed; got:\n{out}"
    );
    assert_eq!(
        std::fs::read_to_string(&project_copy).unwrap(),
        shipped_spec_preflight_skill(),
        "the project copy must hold the shipped bytes"
    );
    assert_eq!(
        std::fs::read_to_string(&home_copy).unwrap(),
        hand_authored,
        "the copy outside the project must keep its bytes"
    );
    assert_eq!(
        std::fs::metadata(&home_copy).unwrap().modified().unwrap(),
        home_mtime,
        "the copy outside the project must not even move its mtime"
    );
    let listed = |dir: &Path| -> Vec<String> {
        let mut names: Vec<String> = std::fs::read_dir(dir)
            .unwrap()
            .map(|entry| entry.unwrap().file_name().into_string().unwrap())
            .collect();
        names.sort_unstable();
        names
    };
    assert_eq!(
        listed(&home.path().join(".claude")),
        ["skills"],
        "setup must write nothing under the home's .claude"
    );
    assert_eq!(
        listed(&home.path().join(".claude/skills")),
        ["spec-preflight"],
        "setup must install no skill under the home"
    );
}

/// Spec 69, criterion 1 (WATCH SKILLS RENDER TRUE, proven against the ACTUAL compiled
/// `rigger watch --once`, not merely trusted from the render function's own prose): whenever
/// the COMMITTED `rigger-restore-the-dash` skill claims (verbatim) that "`rigger watch
/// --once` ... verifies the recorded marker by actually probing its port, and prints a
/// `dash liveness` line naming the dead PID when nothing answers there", that claim must be TRUE
/// of the real binary, not merely asserted in prose - so this drives the real `rigger watch
/// --once` through the exact "dead marker" scenario the skill describes (a
/// `.rigger/dash.marker` naming a definitely-dead pid on a definitely-unbound loopback port,
/// the same file `cmd_watch` actually reads) and checks the output against the skill's own
/// literal promise. The check is GATED on the skill still making that specific claim (read
/// fresh from the compiled binary's own `rigger docs` output) rather than fixed here as a
/// hardcoded expectation: this test's job is proving the shipped PROSE never outruns the
/// shipped CODE, not prescribing which of the two a future round corrects to close the gap -
/// so a round that instead rewrites the claim to describe different real behavior leaves this
/// test nothing to check, and it passes cleanly, exactly as it should. This is the corrected
/// successor of an earlier version of this same test that pinned the identical promise
/// against `rigger status` instead: `cmd_status` (src/main.rs) has no liveness check at all
/// (that is sibling criterion u69c4's territory, not yet integrated here), so the skill text
/// was rewritten to point operators at the check that is ALREADY true today - `rigger watch
/// --once`, confirmed live above `cmd_watch`'s own marker-read-and-probe (src/main.rs, near
/// `dash::DashMarker::read`/`dash::dash_serving_on`) - and this test now pins THAT claim
/// instead of the one that no longer ships.
/// `docs_renders_every_watching_discipline_skill_through_the_compiled_binary` above only
/// proves the skill's rendered TEXT is stable and structurally complete; it cannot catch text
/// describing a command behavior the command does not actually have, which is a boundary bug
/// this criterion's own Done-when text ("command references accuracy-pinned") exists to catch
/// one level deeper than a bare subcommand name.
#[test]
fn watch_once_output_matches_what_restore_the_dash_promises_about_a_dead_marker() {
    use rigger::dash::DashMarker;

    let proj = temp_store_project();
    let root = proj.path();

    let (_o, err, ok) = run_rigger(root, &["docs"]);
    assert!(ok, "rigger docs must succeed; stderr:\n{err}");
    let restore_the_dash =
        std::fs::read_to_string(root.join("skills/rigger-restore-the-dash/SKILL.md"))
            .expect("rigger docs wrote rigger-restore-the-dash");
    let claims_watch_once_verifies_the_marker = restore_the_dash.contains(
        "verifies the recorded marker by actually probing its port, and prints a `dash \
         liveness` line naming the dead PID when nothing answers there",
    );
    if !claims_watch_once_verifies_the_marker {
        // The shipped skill no longer makes this specific claim - nothing left to enforce.
        return;
    }

    // A definitely-unbound loopback port (reserved-then-released, per this file's own
    // `free_loopback_port` convention) and an impossible pid (`u32::MAX`) - so nothing on this machine answers on the port and no
    // process holds the pid. `cmd_watch` reads ONLY `.rigger/dash.marker` for this signal
    // (no `.rigger/dash.url` breadcrumb involved), so seeding just the marker exactly
    // matches what the compiled binary actually consumes.
    let dead_port = free_loopback_port();
    let dead_pid = u32::MAX;
    DashMarker {
        port: dead_port,
        pid: dead_pid,
    }
    .write(&root.join(".rigger/dash.marker"))
    .expect("seed the dash marker");

    let (out, err, ok) = run_rigger(root, &["watch", "--once"]);
    assert!(
        ok,
        "rigger watch --once must exit 0 even with a dead dash marker; stderr:\n{err}"
    );

    // The skill's literal promise: a `dash liveness` line naming the dead pid.
    assert!(
        out.contains("dash liveness") && out.contains(&dead_pid.to_string()),
        "rigger-restore-the-dash promises `rigger watch --once` prints a `dash liveness` \
         line naming the dead pid {dead_pid} for a marker like this one - either the skill \
         overclaims what the compiled binary does, or `rigger watch`'s own dash-liveness \
         signal has regressed; got:\n{out}"
    );
}

/// A dash that holds its port but does not answer within the probe window (busy, not dead) is
/// reported by `rigger watch --once` as unresponsive, naming its port and pid - never as a dead
/// or not-serving dash, and never silently healthy. The listener accepts the probe's connection
/// into its backlog and never answers, exactly what a live dash busy on a long request looks like
/// from outside; a truly absent dash still reads as dead
/// (`watch_once_output_matches_what_restore_the_dash_promises_about_a_dead_marker`).
#[test]
fn watch_once_reports_a_dash_that_holds_its_port_but_does_not_answer_as_unresponsive_not_dead() {
    let dir = temp_store_project();
    let root = dir.path();
    let held = std::net::TcpListener::bind(("127.0.0.1", 0)).unwrap();
    let port = held.local_addr().unwrap().port();
    let pid = std::process::id();
    write_dash_breadcrumbs(root, &format!("http://127.0.0.1:{port}/"), port, pid);

    let (out, err, ok) = run_rigger(root, &["watch", "--once"]);
    drop(held);
    assert!(ok, "rigger watch --once must exit 0; stderr:\n{err}");
    assert!(
        !out.contains("not serving")
            && !out.contains("dead pid")
            && !out.contains("does not answer"),
        "a dash that holds its port but is slow to answer must never read as dead; stdout:\n{out}"
    );
    assert!(
        out.contains(&format!(
            "dash on port {port} (pid {pid}) did not answer within 750ms - busy, not dead"
        )),
        "watch must report the unanswered probe truthfully; stdout:\n{out}"
    );
}

/// A seeded store under a fresh project whose `.rigger/dash.url` holds `url` when given, and
/// whose `.rigger/dash.marker` names `marker` (port, pid) when given; each absent breadcrumb
/// is proven absent - the exact shape under test.
fn dash_breadcrumb_project(url: Option<&str>, marker: Option<(u16, u32)>) -> tempfile::TempDir {
    let proj = temp_store_project();
    let root = proj.path();

    let url_path = root.join(".rigger/dash.url");
    match url {
        Some(url) => std::fs::write(&url_path, url).expect("seed the dash.url breadcrumb"),
        None => assert!(
            !url_path.exists(),
            "this fixture must leave no dash.url behind - that is the exact shape under test"
        ),
    }
    let marker_path = root.join(".rigger/dash.marker");
    match marker {
        Some((port, pid)) => rigger::dash::DashMarker { port, pid }
            .write(&marker_path)
            .expect("seed the dash marker"),
        None => assert!(
            !marker_path.exists(),
            "this fixture must leave no marker behind - that is the exact shape under test"
        ),
    }
    proj
}

/// A marker carrying the [`rigger::dash::UNATTRIBUTED_PID`] sentinel on a dead port, beside
/// `url` (or no `dash.url` at all): the dead marker port is still reported, but the sentinel is
/// never printed as a fabricated dead process - it renders exactly like the no-matching-marker
/// case.
fn assert_watch_once_never_names_the_sentinel_pid(url: Option<&str>) {
    let dead_port = free_loopback_port();
    let proj = dash_breadcrumb_project(url, Some((dead_port, rigger::dash::UNATTRIBUTED_PID)));

    let out = run_rigger_ok(proj.path(), &["watch", "--once"]);
    assert!(
        out.contains("dash liveness") && out.contains(&dead_port.to_string()),
        "the dead marker port itself is a genuine anomaly and must still be reported, sentinel \
         pid or not; got:\n{out}"
    );
    assert!(
        !out.contains("marker names dead pid"),
        "the sentinel pid must never be printed as a fabricated dead process - it was never a \
         real, assigned pid; got:\n{out}"
    );
    assert!(
        out.contains("no matching marker, no pid"),
        "a sentinel-pid marker must render exactly like the no-matching-marker case; got:\n{out}"
    );
}

rigger::test_cases! {
    /// Round 5 (adj-u62c1r4-verdict-reject-sentinel-pid-leaks-to-status): the sibling above proves a
    /// REAL dead pid renders truthfully for the marker-only, no-`dash.url`-at-all arm (`watch_poll`'s
    /// `(None, Some(m))` match arm, src/main.rs) - the shape an earlier binary's drive path wrote.
    /// That arm reads `m.pid` straight from the marker with no `dash::pid_if_port_matches` call in
    /// between (there is no url port to compare against), so it was NOT one of the two sites the
    /// round-4 reject named by line range, but it is the same leak: a marker carrying
    /// [`dash::UNATTRIBUTED_PID`] (spec 62 round 4's documented sentinel) would still render "marker
    /// names dead pid 0" here, the identical fabricated-process lie the round-4 reject called
    /// blocking. Proves the sentinel is filtered at this construction site too.
    watch_once_never_names_the_unattributed_pid_sentinel_when_no_url_is_recorded:
        assert_watch_once_never_names_the_sentinel_pid(None);
    /// Round 5 (adj-u62c1r4-verdict-reject-sentinel-pid-leaks-to-status): the sibling above proves a
    /// REAL dead pid renders truthfully through the unparseable-`dash.url` fallback arm (`watch_poll`'s
    /// `(Some(url), Some(m))` arm's `None` sub-branch on `dash::url_port(&url)`, src/main.rs) - which,
    /// like the marker-only arm, reads `m.pid` straight from the marker with no
    /// `dash::pid_if_port_matches` call in between (there is no parseable url port to compare
    /// against). It was NOT one of the two sites the round-4 reject named by line range, but it is
    /// the same leak: a marker carrying [`dash::UNATTRIBUTED_PID`] (spec 62 round 4's documented
    /// sentinel) would still render "marker names dead pid 0" here. Proves the sentinel is filtered
    /// at this construction site too.
    watch_once_never_names_the_unattributed_pid_sentinel_when_the_url_is_unparseable:
        assert_watch_once_never_names_the_sentinel_pid(Some("not-a-url"));
}

/// A `dash.url` naming a definitely-unbound loopback port followed by `path`, with NO marker
/// recorded (what a run leaves once it reaps its dash): the port is correctly parsed out of the
/// url and reported dead, and no pid is named - with no marker there is none to read.
fn assert_watch_once_reports_a_dead_marker_less_url(path: &str) {
    let dead_port = free_loopback_port();
    let proj = dash_breadcrumb_project(Some(&format!("http://127.0.0.1:{dead_port}{path}")), None);

    let out = run_rigger_ok(proj.path(), &["watch", "--once"]);
    assert!(
        out.contains("dash liveness") && out.contains(&dead_port.to_string()),
        "a dash.url naming a dead port with NO marker must still be reported, its port parsed \
         past any colon in its path - either watch_poll's marker-absent fallback regressed, or \
         it was never reached; got:\n{out}"
    );
    assert!(
        !out.contains("marker names dead pid"),
        "with no marker recorded there is no pid to name - a marker-present phrasing here \
         means a pid was invented rather than genuinely read; got:\n{out}"
    );
}

rigger::test_cases! {
    /// Round-3 reject cause (adv-u69c1r3-watch-once-inherits-marker-absent-blindspot), closed:
    /// the sibling test above only seeds `.rigger/dash.marker`, a shape only an earlier
    /// binary's drive path wrote. `rigger run` (`spawn_run_dashboard`) removes its marker when it
    /// reaps its dash and leaves `.rigger/dash.url`. Before the round-4 fix, `watch_poll`
    /// mapped an absent marker straight to `DashProbe::NotRecorded`, which `detect()` never
    /// turns into an anomaly, so `rigger watch --once` printed NOTHING for this exact,
    /// empirically-reproduced shape (verified by the round-3 adversary against the real
    /// binary). This drives that identical shape - a `dash.url` naming a definitely-unbound
    /// loopback port, with NO `dash.marker` file at all - through the real compiled binary and
    /// proves it now reports the dead dash, not silence.
    ///
    /// Unlike its marker-present sibling, this is NOT gated on a specific skill-prose string:
    /// it pins the underlying MECHANISM (`watch_poll`'s marker-absent fallback to the recorded
    /// URL's own port) directly, the same way `watch_once_on_a_freshly_initialized_store_reports_nothing_and_exits_cleanly`
    /// pins the clean-store path unconditionally - a future prose rewrite has nothing to do
    /// with whether this specific driver shape is actually caught.
    watch_once_reports_a_dead_dash_when_only_the_url_breadcrumb_is_recorded_and_no_marker_exists:
        assert_watch_once_reports_a_dead_marker_less_url("/");
    /// Round-12 fix (arch-u69c1-duplicate-url-port-parser / arch-u69c1r11-pidmatch-and-
    /// urlparser-duplication-still-unfixed / adv-u69c1r11-elevate-pidmatch-remedy-now):
    /// `watch_poll`'s marker-absent arm (src/main.rs, the `(Some(url), None)` match arm) used to
    /// call its own private `port_from_dash_url`, which took the LAST colon in the WHOLE url -
    /// only agreeing with `dash::url_port`'s scheme-and-path-aware parse on the single documented
    /// no-path `http://127.0.0.1:<port>/` shape, and diverging (silently failing to parse at all)
    /// on any recorded url with a colon appearing somewhere after the port, e.g. inside a path
    /// segment. `port_from_dash_url` is gone; this arm now calls `dash::url_port` directly, the
    /// crate's one implementation (also used by `dash_status`). No existing fixture in this file
    /// ever wrote a `dash.url` whose path contains a colon (grepped: every seeded url is a bare
    /// `http://127.0.0.1:<port>/` or `.../api/state` shape), so this exact divergence class was
    /// never driven through the compiled binary. This seeds a `dash.url` naming a
    /// definitely-unbound loopback port followed by a path segment containing a colon, with NO
    /// marker recorded (what a run leaves once it reaps its dash), and proves the port is still
    /// correctly extracted and reported dead. Confirmed this reproduces the pre-round-12 defect:
    /// against the old `port_from_dash_url` (`url.rsplit_once(':')` over the whole string), the
    /// last colon in this fixture's url falls inside the path, so the parse yields a non-numeric
    /// tail and fails outright - the arm falls through to `DashProbe::NotRecorded` and `rigger
    /// watch --once` prints nothing at all for a genuinely dead, recorded dash.
    watch_once_parses_the_urls_port_past_a_colon_in_the_path_with_no_marker:
        assert_watch_once_reports_a_dead_marker_less_url("/run:abc");
}

/// A `dash.url` naming one definitely-unbound loopback port followed by `path`, beside a
/// marker naming a DIFFERENT one and an impossible pid: the report probes and names the url's
/// own (correctly-parsed) port - the canonical `dash_status` target - and never the
/// mismatched marker's port or pid.
fn assert_watch_once_names_the_urls_port_over_a_mismatched_marker(path: &str) {
    let url_port = free_loopback_port();
    let marker_port = loop {
        let p = free_loopback_port();
        if p != url_port {
            break p;
        }
    };
    let impossible_pid = u32::MAX;
    let proj = dash_breadcrumb_project(
        Some(&format!("http://127.0.0.1:{url_port}{path}")),
        Some((marker_port, impossible_pid)),
    );

    let out = run_rigger_ok(proj.path(), &["watch", "--once"]);
    assert!(
        out.contains("dash liveness") && out.contains(&format!("port {url_port}")),
        "the dash liveness report must probe and name the recorded dash.url's own port \
         ({url_port}), parsed past any colon in its path; got:\n{out}"
    );
    assert!(
        !out.contains(&impossible_pid.to_string()),
        "a mismatched marker's pid must never be named as this url's; got:\n{out}"
    );
    assert!(
        !out.contains(&format!("port {marker_port}")),
        "the mismatched marker's own port must not be reported as the dash's; got:\n{out}"
    );
}

rigger::test_cases! {
    /// The mismatched-marker case for `watch_poll`'s dash probe (the round-9 escalation
    /// remedy, adv-u69c1r9-watch-poll-dashprobe-diverges-from-dash-status-mismatch-handling):
    /// when BOTH breadcrumbs exist and the on-disk marker's port differs from the recorded
    /// dash.url's, the probe must follow `dash::dash_status`'s canonical handling - the URL's
    /// own port is what gets probed and reported, and the mismatched marker's pid is NEVER
    /// named as though it belonged to this url. Both ports are definitely-unbound loopback
    /// ports (the same reserve-then-release convention as the dead-marker test above), so the
    /// url's port is genuinely dead and must be the one the report names.
    watch_once_never_names_a_mismatched_markers_pid_for_the_recorded_urls_port:
        assert_watch_once_names_the_urls_port_over_a_mismatched_marker("/");
    /// The sibling of the test above for `watch_poll`'s OTHER changed call site: the
    /// `(Some(url), Some(m))` match arm (src/main.rs) also used to call `port_from_dash_url` and
    /// now calls `dash::url_port` directly, a textually separate line from the marker-absent
    /// arm's - a mutation or reversion could regress this call site alone and leave the sibling
    /// arm's test (and every existing well-formed-url fixture, none of which puts a colon in the
    /// path) blind to it, exactly the "one arm fixed, the duplicate elsewhere left behind" shape
    /// this unit's own history repeats (round 10 fixed the mtime symptom but left the pid-match
    /// classifier duplicated; the adversary named that pattern explicitly at
    /// arch-u69c1-r10-pid-match-duplication-is-the-recurring-drift-source). Deliberately a
    /// MISMATCHED marker (different port than the url), not a matching one: a matching marker's
    /// pid is named identically whichever code path decides it (the correct
    /// `dash::url_port`-then-`pid_if_port_matches` route, or the OLD parser's total parse
    /// failure falling back to probing the marker's own port directly - confirmed empirically,
    /// see below), so that shape cannot discriminate old from new behavior here. A genuine port
    /// mismatch can: this seeds a colon-bearing-path `dash.url` naming one definitely-unbound
    /// loopback port and a marker naming a DIFFERENT one, and proves the report names the URL's
    /// own (correctly-parsed) port and never the mismatched marker's port or pid - mirroring
    /// `watch_once_never_names_a_mismatched_markers_pid_for_the_recorded_urls_port` above, but
    /// through a url shape that only reaches the `Some(url_port)` sub-branch (and hence
    /// `pid_if_port_matches` at all) once `dash::url_port` correctly parses past the path colon.
    /// Confirmed this reproduces the pre-round-12 defect: reverted to the old
    /// `port_from_dash_url` (`main.rs` at `a6f8a18`, this unit's prior tip), the whole-string
    /// last-colon parse fails on this fixture's url (its tail is non-numeric), so the arm falls
    /// into the UNPARSEABLE-url branch and probes the MISMATCHED marker's OWN port directly
    /// instead - reporting the marker's port and its impossible pid, exactly the wrong dash, and
    /// never the url's own port at all.
    watch_once_never_names_a_mismatched_markers_pid_when_the_urls_path_contains_a_colon:
        assert_watch_once_names_the_urls_port_over_a_mismatched_marker("/run:abc");
}

/// The other half of the marker-absent fallback: a GENUINELY LIVE dash reached only
/// through the URL breadcrumb (still no marker) must read as `Serving`, not merely "not
/// verifiably dead". The sibling test above only proves the dead-port half; mutation
/// testing (round-4 mutation-efficacy accounting) found `dash::dash_serving_on(port)` in
/// `watch_poll`'s marker-absent branch hardcoded to `false` survived every test in the
/// suite - nothing drove a real, answering dash through this exact fallback path, so a
/// regression that always reported it as dead would have gone undetected. Spins up a real
/// `rigger dash`, records ONLY its URL (what a run leaves once it reaps its dash - no
/// marker), and asserts `rigger watch --once` reports no anomaly.
#[test]
fn watch_once_reports_nothing_when_a_real_dash_serves_the_url_only_recorded_port() {
    let proj = temp_store_project();
    let root = proj.path();

    let dash_port = free_loopback_port();
    let url = format!("http://127.0.0.1:{dash_port}/");
    let mut dash = serving_dash(root, dash_port);

    // Exactly the marker-absent shape: only `.rigger/dash.url` recorded, no
    // `.rigger/dash.marker` - the URL points at a port a REAL dash answers on.
    std::fs::write(root.join(".rigger/dash.url"), &url).expect("seed the dash.url breadcrumb");
    assert!(
        !root.join(".rigger/dash.marker").exists(),
        "this fixture must leave no marker behind - that is the exact shape under test"
    );

    let (out, err, ok) = run_rigger(root, &["watch", "--once"]);

    // Reap the dash BEFORE asserting so a failure never leaks a dashboard.
    let _ = dash.kill();
    let _ = dash.wait();

    assert!(
        ok,
        "rigger watch --once must exit 0 against a genuinely live, marker-less dash; stderr:\n{err}"
    );
    assert!(
        out.trim().is_empty(),
        "a dash genuinely serving the URL-only recorded port (no marker) must report NO dash \
         liveness anomaly - either the marker-absent fallback never probes for real, or it \
         misreads a live dash as dead; got:\n{out}"
    );
}

/// r1 done: one unit started and integrated, no failed deferred gate - exactly
/// `ledger::Run::done`'s own three conjuncts (non-empty, all-integrated, no deferred gate
/// failure).
const R1_DONE: &[(&str, &str)] = &[
    ("RunStarted", r#"{"run":"r1","criteria":["spec 69"]}"#),
    ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
    ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
];

/// r1 fresh and NOT done: started, one unit still in flight.
const R1_IN_FLIGHT: &[(&str, &str)] = &[
    ("RunStarted", r#"{"run":"r1","criteria":["spec 69"]}"#),
    ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
];

/// r2 fresh and NOT done, with zero dash-related activity of its own.
const R2_IN_FLIGHT: &[(&str, &str)] = &[
    ("RunStarted", r#"{"run":"r2","criteria":["spec 69"]}"#),
    ("UnitStarted", r#"{"id":"u2","agent":"worker"}"#),
];

/// The pid every dead dash marker below names: impossible, so no process holds it.
const DEAD_MARKER_PID: u32 = u32::MAX;

/// `rigger watch --once` over a seeded store whose `before` run events are recorded, then a
/// dead `.rigger/dash.marker` (a definitely-unbound loopback port and [`DEAD_MARKER_PID`]),
/// then the `after` run events, then - when given - a `.rigger/dash.attempt` naming `attempt`
/// (simulating what a real `ensure_run_dashboard` call would have written, WITHOUT calling it,
/// which would rewrite the marker with a fresh mtime and defeat the ordering under test). A
/// filesystem-mtime safety margin separates the marker from the events on either side, so the
/// marker's mtime and each `RunStarted.recorded_at` land in an unambiguous order rather than a
/// coin-flip tie on a coarse-grained filesystem clock. Returns the command's stdout.
fn watch_once_over_a_dead_marker(
    before: &[(&str, &str)],
    after: &[(&str, &str)],
    attempt: Option<&str>,
) -> String {
    let proj = temp_store_project();
    let root = proj.path();

    let margin = || std::thread::sleep(std::time::Duration::from_millis(50));
    if !before.is_empty() {
        seed_run_events(root, before);
        margin();
    }
    rigger::dash::DashMarker {
        port: free_loopback_port(),
        pid: DEAD_MARKER_PID,
    }
    .write(&root.join(".rigger/dash.marker"))
    .expect("seed the dash marker");
    if !after.is_empty() {
        margin();
        seed_run_events(root, after);
    }
    if let Some(attempt) = attempt {
        std::fs::write(root.join(".rigger/dash.attempt"), attempt)
            .expect("seed the dash attempt marker");
    }

    run_rigger_ok(root, &["watch", "--once"])
}

/// The dead marker is NOT the watched run's own breadcrumb - it belongs to a run that
/// finished (its dash exited on purpose, which is success), or predates the watched run's
/// `RunStarted` with no same-run `dash.attempt` to override that - so `rigger watch --once`
/// reports no dash liveness anomaly at all.
fn assert_watch_once_is_silent_about_a_dead_marker(
    before: &[(&str, &str)],
    after: &[(&str, &str)],
    attempt: Option<&str>,
) {
    let out = watch_once_over_a_dead_marker(before, after, attempt);
    assert!(
        out.trim().is_empty(),
        "a dead marker that is not the watched, unfinished run's own breadcrumb must report \
         NO dash liveness anomaly; got:\n{out}"
    );
}

/// The dead marker IS the watched, unfinished run's own - written after its `RunStarted`, or
/// explicitly claimed by a `dash.attempt` naming this exact run - so `rigger watch --once`
/// reports a `dash liveness` line naming the dead pid.
fn assert_watch_once_reports_the_dead_marker(
    before: &[(&str, &str)],
    after: &[(&str, &str)],
    attempt: Option<&str>,
) {
    let out = watch_once_over_a_dead_marker(before, after, attempt);
    assert!(
        out.contains("dash liveness") && out.contains(&DEAD_MARKER_PID.to_string()),
        "the watched, unfinished run's OWN dead dash marker must be reported with its dead \
         pid - either the mtime comparison misread it as inherited, or watch_poll's \
         dash.attempt file-read-and-match wiring regressed; got:\n{out}"
    );
}

rigger::test_cases! {
    /// Round-4 reject (adv-u69c1r4-dash-anomaly-permanent-false-positive), round-5 fix: `.rigger/
    /// dash.marker` and `.rigger/dash.url` are project-level singleton files never removed once
    /// their dash exits, so a project's FIRST run leaves a dead marker behind forever - and
    /// before the round-5 fix, every LATER `rigger watch --once` in that same project reported a
    /// permanent false "dash liveness" anomaly, even after a run finished successfully with no
    /// dash-launching process left to be dead. `watch::detect`'s own unit test
    /// (`a_done_run_never_reports_a_dead_dash_either`, src/watch.rs) proves the pure function
    /// gates Signal 3 on `!run.done()`, mirroring Signal 2's existing gate two lines above it -
    /// but that test builds `WatchInputs` directly in-process and never proves `watch_poll`
    /// (the real I/O seam: `require_store_dir`, the marker file read, the dash probe) and
    /// `cmd_watch`'s dedup/print loop actually wire a real DONE run's events through to that
    /// gate. This drives the identical marker-present dead-dash shape
    /// `watch_once_output_matches_what_restore_the_dash_promises_about_a_dead_marker` above
    /// pins for an UNFINISHED run, but through a DONE run's real store, and proves the compiled
    /// binary reports nothing - the boundary the round-4 adversary finding demanded. Confirmed
    /// this reproduces the round-4 defect: reverted to `ec4c316` (round-4 HEAD, before the
    /// `!run.done()` gate existed) this test fails, printing a "dash liveness" line naming the
    /// dead pid for a run whose every unit already integrated.
    watch_once_reports_no_dash_anomaly_for_a_done_run_even_with_a_dead_marker:
        assert_watch_once_is_silent_about_a_dead_marker(R1_DONE, &[], None);
    /// Round-5 reject cause (adv2-u69c1-r5-uphold-sdet-second-run-stale-marker), round-6 fix: the
    /// round-5 `!run.done()` gate above only scopes the CURRENTLY WATCHED run's own done-ness -
    /// `.rigger/dash.marker` is a project-level singleton NEVER removed once its dash exits (same
    /// fact the sibling test above relies on), so a FRESH, NOT-DONE run that never itself touched
    /// the dash still inherited an EARLIER, already-done run's stale dead marker as a false
    /// anomaly. This is the exact shape sdet-u69c1-r5-second-run-stale-marker-false-positive and
    /// adv2-u69c1-r5-uphold-sdet-second-run-stale-marker independently reproduced against the real
    /// binary: seed a done run r1 with a dead marker, THEN a fresh not-done run r2 with zero
    /// dash-related activity of its own, and prove `rigger watch --once` reports nothing for r2 -
    /// the marker predates r2's own `RunStarted`, so it cannot be r2's own breadcrumb. Per
    /// adv2-u69c1-r5-root-cause-marker-lacks-run-identity, the fix does not reshape
    /// `DashMarker` (spec 39's idempotent-start-on-step contract needs the marker to persist
    /// ACROSS runs by design); it compares the breadcrumb file's own mtime against this run's own
    /// `RunStarted` moment instead - a separate per-run fact, not a mutation of the shared marker.
    watch_once_reports_no_dash_anomaly_for_a_fresh_run_that_inherits_an_earlier_runs_dead_marker:
        assert_watch_once_is_silent_about_a_dead_marker(R1_DONE, R2_IN_FLIGHT, None);
    /// SDET periphery gap (round-6 accounting): every existing binary-level dash-liveness test
    /// exercises either the SUPPRESS side of the round-6 mtime comparison (the sibling above:
    /// breadcrumb strictly OLDER than `run_started_at`) or the UNKNOWN side (no `RunStarted`
    /// seeded at all, so `run_started_at` is `None` and the burden-of-proof-toward-reporting
    /// default fires regardless of the comparison). None drove the third, most ordinary case
    /// through the real compiled binary: a fresh, NOT-DONE run whose OWN dash breadcrumb is
    /// written AFTER its own `RunStarted` and then genuinely dies.
    ///
    /// This IS the real call order: `rigger run` mints a brand-new run's `RunStarted` through
    /// `fresh_run_if_requested` before it calls `start_run_dashboard`, so on a project's first
    /// run `RunStarted.recorded_at` lands measurably before the dash breadcrumb's own mtime, not
    /// after.
    ///
    /// `watch::detect`'s own unit test
    /// (`a_dead_dash_url_with_no_marker_is_reported_without_inventing_a_pid`, src/watch.rs)
    /// pins this at the pure-function level by constructing `WatchInputs` directly in-process,
    /// but that is structurally blind to `watch_poll`'s real wiring (src/main.rs): the
    /// `run_events.first().map(|e| e.recorded_at)` read and the `mtime_of` filesystem read that
    /// feed `run_started_at`/`dash_breadcrumb_written_at`. An inverted comparison there (`<`
    /// flipped to `<=`/`>`, or `mtime_of` reading the wrong file) would silently swallow every
    /// LIVE run's own genuinely dead dash - the single most common real anomaly this signal
    /// exists to catch - while every other test in this file kept passing, since none of them
    /// pin the "both known, breadcrumb newer" direction against the real binary. This closes
    /// that gap: seeds a fresh, not-done run's `RunStarted`, waits past the sleep margin the
    /// sibling tests use, THEN writes the dead marker (so its mtime unambiguously postdates
    /// `run_started_at`), and proves `rigger watch --once` still reports it. Since round 8, this
    /// exercises the fallback path specifically (`dash_attempted_this_run` is `false` here - this
    /// test never calls the real dash-ensure code path that would set it - so the report comes
    /// entirely from the pre-existing `dash_breadcrumb_written_at`/`run_started_at` comparison,
    /// unchanged by the round-8 fix).
    watch_once_reports_this_runs_own_dead_marker_when_written_after_its_run_started:
        assert_watch_once_reports_the_dead_marker(R1_IN_FLIGHT, &[], None);
    /// Round-8 fix, `watch_poll`'s own wiring (src/main.rs) for `dash_attempted_this_run`: the
    /// sibling `watch_once_reports_a_real_steps_own_dash_after_the_step_process_has_long_since_exited`
    /// test above drives the REAL `ensure_run_dashboard` write site end to end, but in every real
    /// production shape the timestamp FALLBACK (`dash_breadcrumb_written_at`/`run_started_at`)
    /// independently reaches the same "report it" answer too (this file's own investigation proved
    /// the marker always postdates RunStarted for a real run's own attempt) - so that test cannot,
    /// by itself, prove `watch_poll`'s `.rigger/dash.attempt` READ and run-id MATCH
    /// (`main.rs::watch_poll`, the `std::fs::read_to_string(loc.file(DASH_ATTEMPT_FILE))...
    /// attempted_run == run_id` expression) is actually load-bearing: a mutant that broke JUST that
    /// expression (e.g. inverting the `==`, deleting the `!attempted_run.is_empty()` guard, or an
    /// `&&`/`||` flip) would still pass it via the independently-correct fallback. This test closes
    /// that gap by constructing the ONE shape where the two signals DISAGREE - synthetically, since
    /// no real production sequence can produce it (this file's own investigation again): a marker
    /// whose mtime PROVABLY PREDATES `RunStarted` (the fallback alone would suppress, exactly the
    /// shape `watch_once_reports_no_dash_anomaly_for_a_fresh_run_that_inherits_an_earlier_runs_dead_
    /// marker` above proves suppresses), but with `.rigger/dash.attempt` naming this EXACT run,
    /// written directly (not through a real `ensure_run_dashboard` call, which never produces this
    /// ordering) - proving the report fires ONLY because `dash_attempted_this_run` genuinely
    /// overrode the fallback, not coincidentally.
    watch_once_reports_a_dead_marker_predating_run_started_when_dash_attempt_names_this_run:
        assert_watch_once_reports_the_dead_marker(&[], R1_IN_FLIGHT, Some("r1"));
    /// SDET periphery gap, round-8 accounting (sdet-u69c1-r8-mutation-accounting-correction):
    /// EMPIRICALLY VERIFIED, not theoretical - the round-8 mutation-accounting decision
    /// (`u69c1r8-mutation-accounting`) claims `src/main.rs:6347` col 64 (`replace && with ||` in
    /// the `dash_attempted_this_run` expression, `!attempted_run.is_empty() && attempted_run ==
    /// run_id`) is CAUGHT. It is not: hand-applying exactly that mutation, rebuilding the release
    /// binary, and rerunning the full dash-liveness suite leaves every existing test green,
    /// including its own sibling `watch_once_reports_a_dead_marker_predating_run_started_when_
    /// dash_attempt_names_this_run` above and the real end-to-end
    /// `watch_once_reports_a_real_steps_own_dash_after_the_step_process_has_long_since_exited`
    /// below. The reason: every existing test that writes `.rigger/dash.attempt` at all writes a
    /// run id that MATCHES the run being watched, so `!attempted_run.is_empty()` (true for ANY
    /// nonempty content, matching or not) already forces the same `true` the real `==` comparison
    /// would - the `||` mutant is indistinguishable from correct code on every shape any current
    /// test drives. The one shape that DOES discriminate them - a nonempty `.rigger/dash.attempt`
    /// naming a DIFFERENT run than the one currently watched - was untested.
    ///
    /// This closes it: the identical "predates this run" marker/timestamp shape the sibling test
    /// above uses (so the timestamp fallback alone would suppress), but `.rigger/dash.attempt`
    /// names a run this test never seeds ("some-other-run") instead of the watched run "r1" -
    /// modeling a real production shape (an EARLIER or unrelated run's own step attempted a dash,
    /// stamping the breadcrumb, before this fresh run ever touched it). `rigger watch --once`
    /// must report NOTHING: a foreign, non-matching `dash_attempted_this_run` fact must never
    /// override the fallback, only a genuine same-run match may. Under the `&&`-with-`||` mutant
    /// above, `!is_empty()` alone would force `dash_attempted_this_run = true` here regardless of
    /// the mismatch, wrongly reporting an anomaly - proving this test kills the mutant the
    /// existing suite could not.
    watch_once_suppresses_a_predating_marker_when_dash_attempt_names_a_different_run:
        assert_watch_once_is_silent_about_a_dead_marker(&[], R1_IN_FLIGHT, Some("some-other-run"));
}

/// Spec 46, criterion 2 (the pre-run graph-hygiene guidance ships to CONSUMERS through the
/// INSTALL seam): a consumer never edits rigger's own repo copies - they run `rigger setup`,
/// which renders and INSTALLS the `using-rigger` skill into THEIR project at
/// `.claude/skills/using-rigger/SKILL.md`. That install path (`render_installed_skill`:
/// docs_context -> overlay merge -> render -> write) is DISTINCT from the `rigger docs`
/// repo-copy path the sibling `docs_ships_graph_hygiene_guidance_to_consumers` test drives,
/// so a regression in the install/overlay composition could ship a consumer skill missing
/// the guidance while the repo copies stay fine. This periphery test drives the real
/// `rigger setup` binary and reads the INSTALLED skill to prove the graph-hygiene section
/// reaches the consumer's project with its truthful WHY: graph.db is a PERSISTENT
/// incremental projection (a step never re-folds the whole history), so across runs it
/// accumulates dead-run rows no live query reads, which `rigger reset --runs` prunes to
/// reclaim the disk they held - and NOT the discredited fold-speed framing.
#[test]
fn setup_installs_graph_hygiene_guidance_into_consumer_skill() {
    let proj = temp_project();
    let root = proj.path();

    let out = setup_ok(root, &[]);
    assert!(
        out.contains(".claude/skills/using-rigger/SKILL.md"),
        "setup must report installing the using-rigger skill into the consumer project; got:\n{out}"
    );

    let installed = std::fs::read_to_string(root.join(".claude/skills/using-rigger/SKILL.md"))
        .expect("setup installed the consumer skill");

    // The INSTALLED consumer skill carries the graph-hygiene section, names the pre-run
    // command, and frames the truthful WHY (a persistent incremental projection whose
    // dead-run accumulation `rigger reset --runs` prunes to reclaim the disk it held) - the
    // guidance ships all the way into the consumer's own project, not just rigger's repo.
    assert!(
        installed.contains("## Graph hygiene"),
        "the installed consumer skill must carry the graph-hygiene section; got:\n{installed}"
    );
    assert!(
        installed.contains("rigger reset --runs"),
        "the installed consumer skill must name `rigger reset --runs` as the pre-run hygiene step"
    );
    assert!(
        installed.contains("persistent projection"),
        "the installed consumer skill must frame graph.db as a persistent incremental \
         projection (the corrected WHY, not a per-step whole-stream re-fold)"
    );
    assert!(
        installed.contains("reclaims the disk"),
        "the installed consumer skill must explain reset --runs reclaims the disk the dead-run \
         rows held (bounded growth, not a fold-speed claim)"
    );

    // NEGATIVE regression guard (spec 46 c2): the DISCREDITED fold-speed framing that
    // rejected this unit's first attempt (graph.db re-folded whole-history each step, the
    // fold slow in proportion to graph size, a prune speeding it up) must never reach the
    // consumer's installed skill. graph.db is a PERSISTENT incremental projection; a prune
    // reclaims DISK, it speeds no fold. Pin those phrases OUT (case-insensitively) so a
    // future edit resurrecting the false mechanism fails LOUDLY here instead of installing
    // it into consumer projects.
    let lower = installed.to_lowercase();
    for banned in [
        "re-folded each step",
        "fold stays slow",
        "proportional to graph size",
        "faster fold",
    ] {
        assert!(
            !lower.contains(banned),
            "the installed consumer skill must NOT resurrect the discredited fold-speed framing \
             (found {banned:?}); a prune reclaims disk, it does not speed a fold"
        );
    }
}

/// Write `content` to `code.txt` under `root`, stage it, and [`commit_staged`] it.
fn commit_a_code_change(root: &Path, path: &str, content: &str, message: &str) -> (bool, String) {
    std::fs::write(root.join("code.txt"), content).unwrap();
    git_ok(root, &["add", "code.txt"]);
    commit_staged(root, path, message)
}

/// `git commit` what is staged under `root` with `PATH` set to `path` (so the pre-commit hook
/// finds whichever `rigger` that `PATH` stages) and no inherited `CARGO_TARGET_DIR`. Returns
/// whether the commit succeeded and its stderr.
fn commit_staged(root: &Path, path: &str, message: &str) -> (bool, String) {
    let out = Command::new("git")
        .args(["commit", "-q", "-m", message])
        .current_dir(root)
        .env("PATH", path)
        .env_remove("CARGO_TARGET_DIR")
        .output()
        .expect("git must be runnable");
    (
        out.status.success(),
        String::from_utf8_lossy(&out.stderr).into_owned(),
    )
}

/// The `using-rigger` skill as committed at `root`'s HEAD (empty when absent).
fn committed_skill(root: &Path) -> String {
    git_answer(root, &["show", "HEAD:skills/using-rigger/SKILL.md"]).unwrap_or_default()
}

/// [`committed_skill`], proven to be a real fresh render, not a stub.
fn fresh_committed_skill(root: &Path) -> String {
    let skill = committed_skill(root);
    assert!(
        skill.contains("name: using-rigger"),
        "the seed must be a real fresh render, not a stub; got:\n{skill}"
    );
    skill
}

/// Mark `path` executable (0o755) on unix.
fn make_executable(path: &Path) {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755)).unwrap();
    }
    #[cfg(not(unix))]
    let _ = path;
}

/// Write `script` as an executable `rigger` in a `shim-bin/` under `root` and return a `PATH`
/// value with that dir prepended, so anything run with it finds this `rigger` BY NAME.
fn rigger_shim_on_path(root: &Path, script: impl AsRef<[u8]>) -> String {
    let bindir = root.join("shim-bin");
    std::fs::create_dir_all(&bindir).unwrap();
    let shim = bindir.join("rigger");
    std::fs::write(&shim, script).unwrap();
    make_executable(&shim);
    let orig_path = std::env::var("PATH").unwrap_or_default();
    format!("{}:{}", bindir.display(), orig_path)
}

/// Place an executable copy of the REAL compiled `rigger` binary (the one this very test suite
/// runs) at `dir/rigger`.
fn copy_the_built_binary_into(dir: &Path) {
    std::fs::create_dir_all(dir).unwrap();
    let dest = dir.join("rigger");
    std::fs::copy(rigger_bin(), &dest)
        .unwrap_or_else(|e| panic!("copy the tree-built binary to {}: {e}", dest.display()));
    make_executable(&dest);
}

/// Stage a `rigger` shim (a tiny sh script that execs the freshly built binary) in a
/// `shim-bin/` under `root` and return a `PATH` value with that dir prepended, so a `git
/// commit` run with this `PATH` finds `rigger` BY NAME - the pre-commit hook invokes `rigger`
/// unqualified (spec 24), and pinning it to the built binary keeps the test off whatever old
/// `rigger` happens to be installed in the ambient `PATH`.
fn stage_rigger_shim(root: &Path) -> String {
    rigger_exec_shim_on_path(root, "")
}

/// [`rigger_shim_on_path`] with a sh script that runs `prelude` and then execs the freshly
/// built binary with every argument.
fn rigger_exec_shim_on_path(root: &Path, prelude: &str) -> String {
    rigger_shim_on_path(
        root,
        format!(
            "#!/bin/sh\n{prelude}exec \"{}\" \"$@\"\n",
            rigger_bin().display()
        ),
    )
}

/// Commit genuinely STALE tracked copies of each rendered output in `rels` under `root`, with
/// `--no-verify` so a just-installed hook does NOT fire on the seed itself. Shared by the
/// fixtures below that need real, tracked drift for the hook to detect.
fn commit_stale_outputs(root: &Path, rels: &[&str]) {
    const STALE: &str = "STALE DOC - not a real render\n";
    for rel in rels {
        let p = root.join(rel);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(&p, STALE).unwrap();
    }
    git_ok(root, &[&["add", "--"][..], rels].concat());
    git_ok(
        root,
        &["commit", "-q", "--no-verify", "-m", "seed stale docs"],
    );
    // Guard against a vacuous pass in every caller: HEAD must carry the STALE bytes right after
    // the seed, so a later "the hook detected drift" assertion can only hold for real.
    for rel in rels {
        let seeded = git_answer(root, &["show", &format!("HEAD:{rel}")]).unwrap_or_default();
        assert!(
            seeded.contains("STALE DOC"),
            "the --no-verify seed must commit a STALE {rel} unchanged so the discrimination is \
             real, not vacuous; got:\n{seeded}"
        );
    }
}

/// [`commit_stale_outputs`] over the `using-rigger` skill and handbook chapter.
fn seed_stale_tracked_docs(root: &Path) {
    commit_stale_outputs(
        root,
        &[
            "skills/using-rigger/SKILL.md",
            "docs/handbook/using-rigger.md",
        ],
    );
}

/// Turn `root` into a rigger SELF-HOSTING repo that tracks EVERY rendered output as the TRUE
/// fresh render: `rigger setup` (npm stubbed) installs the hook, then a real `rigger docs` run
/// seeds every output, all committed with `--no-verify` so the just-installed hook does not
/// fire on its own seed. Because the seed comes from the SAME compiled binary the hook later
/// runs (via `stage_rigger_shim`), the hook's check at commit time finds every output fresh -
/// the "matching render" fixture.
fn setup_selfhosting_repo_with_fresh_docs(root: &Path) {
    let out = setup_ok(root, &[]);
    assert!(
        out.contains("pre-commit hook"),
        "setup must install the pre-commit hook; got:\n{out}"
    );
    let outputs = rendered_outputs(&run_rigger_ok(root, &["docs"]));
    let add: Vec<&str> = ["add", "--"]
        .into_iter()
        .chain(outputs.iter().map(String::as_str))
        .collect();
    git_ok(root, &add);
    git_ok(
        root,
        &["commit", "-q", "--no-verify", "-m", "seed fresh docs"],
    );
}

/// Spec 70, crit 1 (THE HOOK REFUSES INSTEAD OF REWRITING, end to end): OWNS the hook behavior.
/// In a self-hosting repo whose tracked docs have drifted from a fresh render, the managed
/// pre-commit hook must REFUSE the commit - naming the drifted files, the checking binary's
/// path AND its build provenance, and the two remedies - rather than staging or writing a
/// render over them. A binary older than the tree that re-renders committed docs to the OLD
/// text and stages them strips a branch's rendered changes from every later commit. Drives the
/// REAL `rigger` binary (via a `rigger` shim on PATH, spec 24) and REAL git.
#[test]
fn setup_precommit_hook_refuses_when_the_staged_render_has_drifted() {
    use std::os::unix::fs::PermissionsExt;
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    let out = setup_ok(root, &[]);
    assert!(
        out.contains("pre-commit hook"),
        "setup must report installing the pre-commit hook; got:\n{out}"
    );
    let hook_path = root.join(".git/hooks/pre-commit");
    assert!(
        hook_path.exists(),
        "setup must install .git/hooks/pre-commit"
    );
    #[cfg(unix)]
    {
        let mode = std::fs::metadata(&hook_path).unwrap().permissions().mode();
        assert!(
            mode & 0o111 != 0,
            "the hook must be executable so git runs it; mode {mode:o}"
        );
    }

    // Make this a rigger SELF-HOSTING repo with genuinely STALE tracked docs.
    seed_stale_tracked_docs(root);

    // A `rigger` shim on PATH at commit time - the hook invokes `rigger` BY NAME.
    let commit_path = stage_rigger_shim(root);

    // Make an UNRELATED tracked change and attempt to commit it.
    let (ok, stderr) = commit_a_code_change(
        root,
        &commit_path,
        "a documented code fact changed\n",
        "change a documented fact",
    );

    assert!(
        !ok,
        "a drifted render must REFUSE the commit, not silently let it through; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("skills/using-rigger/SKILL.md")
            && stderr.contains("docs/handbook/using-rigger.md"),
        "the refusal must name BOTH drifted files; stderr:\n{stderr}"
    );
    let shim_rigger = root.join("shim-bin").join("rigger");
    assert!(
        stderr.contains(shim_rigger.to_str().unwrap()),
        "the refusal must name the rendering binary's PATH; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("build "),
        "the refusal must name the rendering binary's BUILD PROVENANCE (`rigger version`); \
         stderr:\n{stderr}"
    );
    assert!(
        stderr.to_lowercase().contains("reinstall") && stderr.contains("tree-built"),
        "the refusal must name the two remedies - re-render with the tree-built binary, or \
         reinstall; stderr:\n{stderr}"
    );

    // Nothing landed: HEAD still carries the STALE seed, not a silently-substituted re-render.
    let committed = committed_skill(root);
    assert!(
        committed.contains("STALE DOC"),
        "a refused commit must not land - HEAD must still carry the stale seed; got:\n{committed}"
    );
    // And nothing was staged or written: the hook only checks, so the working tree still
    // carries the stale seed exactly as the index does.
    let staged = git_answer(root, &["diff", "--cached", "--name-only"]).unwrap_or_default();
    assert!(
        !staged.contains("SKILL.md") && !staged.contains("using-rigger.md"),
        "the hook must never stage a render; staged files:\n{staged}"
    );
    let working_tree_skill =
        std::fs::read_to_string(root.join("skills/using-rigger/SKILL.md")).unwrap();
    assert!(
        working_tree_skill.contains("STALE DOC"),
        "the hook must never write a render into the working tree; got:\n{working_tree_skill}"
    );
}

/// Over a self-hosting repo whose committed docs are a fresh render, `stage` the `rigger`
/// binaries the hook can reach (returning the commit's `PATH`) and commit `content` with
/// `message`: the hook's check finds every output fresh, so the commit passes without a
/// refusal, the change rides it, the already-fresh doc lands byte-identical, and every
/// working-tree file keeps its bytes and modification time - the hook must not touch them.
fn assert_the_hook_passes_a_matching_render_untouched(
    stage: fn(&Path) -> String,
    content: &str,
    message: &str,
) {
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    setup_selfhosting_repo_with_fresh_docs(root);
    let fresh_skill_before = fresh_committed_skill(root);

    let commit_path = stage(root);
    std::fs::write(root.join("code.txt"), content).unwrap();
    git_ok(root, &["add", "code.txt"]);
    let working_tree_before = tree_snapshot(root, &[".git"]);
    let (ok, stderr) = commit_staged(root, &commit_path, message);
    assert!(
        tree_snapshot(root, &[".git"]) == working_tree_before,
        "the hook must write nothing into the working tree; stderr:\n{stderr}"
    );
    assert!(
        ok,
        "a matching render must pass the commit through, even when PATH is stale; \
         stderr:\n{stderr}"
    );
    assert!(
        !stderr.contains("refusing"),
        "a matching render must never print a refusal; stderr:\n{stderr}"
    );

    let tree = git_answer(root, &["ls-tree", "-r", "--name-only", "HEAD"]).unwrap_or_default();
    assert!(
        tree.contains("code.txt"),
        "the change must ride the commit; tree:\n{tree}"
    );
    assert_eq!(
        committed_skill(root),
        fresh_skill_before,
        "the already-fresh doc must land byte-identical - the hook must not touch it"
    );
}

rigger::test_cases! {
    /// Spec 70, crit 1 (a MATCHING render passes silently, end to end): the flip side of refusing
    /// instead of rewriting. When the committed docs are ALREADY the fresh render, the hook must
    /// change nothing and let the commit through exactly as before this fix - no warning, no
    /// refusal, no touched doc content. Drives the REAL `rigger` binary and REAL git.
    setup_precommit_hook_passes_untouched_when_the_render_matches:
        assert_the_hook_passes_a_matching_render_untouched(
            stage_rigger_shim,
            "an unrelated change\n",
            "unrelated change",
        );
    /// Spec 75, crit 2 (a MATCHING render passes via the tree-built binary, end to end): OWNS the
    /// end-to-end hook behavior (crit 1 owns the candidate order and its rendering in the
    /// template - `precommit_block_resolves_a_tree_built_binary_before_path` proves that
    /// textually). A commit in a worktree whose code adds a rendered fact - here, the tree's own
    /// local target build - PASSES when that build is present and its render matches the staged
    /// docs, even though `PATH` carries only a STALE `rigger` whose check reports a MISMATCH. A
    /// pass can only happen by the hook genuinely PREFERRING the tree-built candidate over PATH:
    /// if it fell back to PATH instead, the stale shim's check would report the staged fresh
    /// docs drifted and this same commit would be refused (proven by the sibling refusal test
    /// below).
    setup_precommit_hook_prefers_the_trees_own_built_binary_over_a_stale_path_rigger:
        assert_the_hook_passes_a_matching_render_untouched(
            |root| {
                stage_tree_built_binary(root);
                stage_stale_rigger_shim(root)
            },
            "a rendered fact this worktree's code added\n",
            "add a rendered fact",
        );
    /// Within one target dir the hook checks with the MORE RECENTLY MODIFIED of its two builds,
    /// not the first in candidate order: a newer debug build beside an older, stale release
    /// build passes the commit, though the release build is tried first and would report the
    /// fresh docs drifted.
    setup_precommit_hook_checks_with_a_newer_debug_build_over_an_older_release_build:
        assert_the_hook_passes_a_matching_render_untouched(
            |root| stage_the_tree_build_beside_a_stale_build(root, "target/debug", "target/release", false),
            "a rendered fact this worktree's debug build added\n",
            "add a rendered fact",
        );
    /// The mirror: a newer release build beside an older, stale debug build passes the commit,
    /// so the choice follows modification time, not the last candidate that exists.
    setup_precommit_hook_checks_with_a_newer_release_build_over_an_older_debug_build:
        assert_the_hook_passes_a_matching_render_untouched(
            |root| stage_the_tree_build_beside_a_stale_build(root, "target/release", "target/debug", false),
            "a rendered fact this worktree's release build added\n",
            "add a rendered fact",
        );
    /// Across target dirs the authority order stands: the worktree's own older build passes the
    /// commit over a newer, stale build in the run's shared build cache, which may have been
    /// built from another worktree's tree.
    setup_precommit_hook_checks_with_the_worktrees_older_build_over_a_newer_shared_cache_build:
        assert_the_hook_passes_a_matching_render_untouched(
            |root| stage_the_tree_build_beside_a_stale_build(root, "target/debug", ".rigger/tmp/cargo-target/debug", true),
            "a rendered fact this worktree's own build added\n",
            "add a rendered fact",
        );
}

/// Over a self-hosting repo that tracks every rendered output as a fresh render, `prepare` the
/// index and working tree, then commit an unrelated change through the hook with the tree's own
/// binary on `PATH`: the hook refuses, its stderr carries every phrase in `named` and none in
/// `unnamed`, HEAD does not move, and every working-tree file keeps the bytes and modification
/// time `prepare` left it with - the hook checks, it never writes.
fn assert_the_hook_refuses(prepare: fn(&Path), named: &[&str], unnamed: &[&str]) {
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    setup_selfhosting_repo_with_fresh_docs(root);
    prepare(root);
    let head_before = git_answer(root, &["rev-parse", "HEAD"]);

    let commit_path = stage_rigger_shim(root);
    std::fs::write(root.join("code.txt"), "an unrelated change\n").unwrap();
    git_ok(root, &["add", "code.txt"]);
    let working_tree_before = tree_snapshot(root, &[".git"]);
    let (ok, stderr) = commit_staged(root, &commit_path, "unrelated change");

    assert!(!ok, "the hook must refuse the commit; stderr:\n{stderr}");
    for phrase in named {
        assert!(
            stderr.contains(phrase),
            "the refusal must name {phrase:?}; stderr:\n{stderr}"
        );
    }
    for phrase in unnamed {
        assert!(
            !stderr.contains(phrase),
            "the refusal must not name {phrase:?}; stderr:\n{stderr}"
        );
    }
    assert_eq!(
        git_answer(root, &["rev-parse", "HEAD"]),
        head_before,
        "a refused commit must not land"
    );
    assert!(
        tree_snapshot(root, &[".git"]) == working_tree_before,
        "the hook must write nothing into the working tree; stderr:\n{stderr}"
    );
}

/// The committed `spec-preflight` skill made stale, a rendered output outside the
/// `using-rigger` pair.
fn commit_a_stale_spec_preflight_skill(root: &Path) {
    commit_stale_outputs(root, &["skills/spec-preflight/SKILL.md"]);
}

rigger::test_cases! {
    /// A stale tracked output that is NOT one of the `using-rigger` pair - the
    /// `spec-preflight` skill - refuses the commit, and the refusal names it alone as differing
    /// from a fresh render: the hook checks every rendered output, not two.
    setup_precommit_hook_refuses_and_names_a_stale_output_outside_the_using_rigger_pair:
        assert_the_hook_refuses(
            commit_a_stale_spec_preflight_skill,
            &["skills/spec-preflight/SKILL.md", "differ from a fresh render"],
            &[
                "skills/using-rigger/SKILL.md",
                "docs/handbook/using-rigger.md",
                "unstaged",
            ],
        );
    /// Spec 70, crit 1 (a refusal names ONLY the file that actually drifted, end to end): with
    /// only the handbook chapter stale, the refusal names the handbook and not the still-fresh
    /// `using-rigger` skill.
    setup_precommit_hook_refusal_names_only_the_drifted_file:
        assert_the_hook_refuses(
            |root| commit_stale_outputs(root, &["docs/handbook/using-rigger.md"]),
            &["docs/handbook/using-rigger.md", "differ from a fresh render"],
            &["skills/using-rigger/SKILL.md"],
        );
    /// A fresh render left UNSTAGED - the index carries a stale `spec-preflight` skill while
    /// the working tree carries its fresh render - refuses the commit as unstaged and tells the
    /// operator to stage it: the commit would carry content the check never saw.
    setup_precommit_hook_refuses_a_fresh_render_left_unstaged:
        assert_the_hook_refuses(
            |root| {
                commit_a_stale_spec_preflight_skill(root);
                run_rigger_ok(root, &["docs"]);
            },
            &["skills/spec-preflight/SKILL.md", "unstaged", "git add"],
            &["differ from a fresh render", "skills/using-rigger/SKILL.md"],
        );
}

/// A rendered output the repo does NOT track is outside the hook's check: an untracked,
/// hand-edited `planning-a-spec` skill - an operator mid-edit on a skill - neither blocks the
/// commit nor rides it, and the hook leaves its bytes exactly as the operator left them.
#[test]
fn setup_precommit_hook_ignores_an_untracked_output_and_leaves_its_bytes() {
    const PLANNING_REL: &str = "skills/planning-a-spec/SKILL.md";
    const WIP: &str = "WIP hand-edit, not a render\n";
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    setup_selfhosting_repo_with_fresh_docs(root);
    git_ok(root, &["rm", "-q", "--cached", "--", PLANNING_REL]);
    git_ok(
        root,
        &[
            "commit",
            "-q",
            "--no-verify",
            "-m",
            "untrack planning-a-spec",
        ],
    );
    std::fs::write(root.join(PLANNING_REL), WIP).unwrap();
    let status_before =
        git_answer(root, &["status", "--porcelain", PLANNING_REL]).unwrap_or_default();
    assert!(
        status_before.starts_with("??"),
        "the planning-a-spec skill must start UNTRACKED; got:\n{status_before}"
    );

    let commit_path = stage_rigger_shim(root);
    let (ok, stderr) = commit_a_code_change(
        root,
        &commit_path,
        "an unrelated change\n",
        "unrelated change",
    );

    assert!(
        ok,
        "an untracked output must never block the commit; stderr:\n{stderr}"
    );
    let tree = git_answer(root, &["ls-tree", "-r", "--name-only", "HEAD"]).unwrap_or_default();
    assert!(
        tree.contains("code.txt") && !tree.contains(PLANNING_REL),
        "the change rides the commit and the untracked output does not; tree:\n{tree}"
    );
    assert_eq!(
        std::fs::read_to_string(root.join(PLANNING_REL)).unwrap(),
        WIP,
        "the hook must leave the untracked output's hand-edit exactly as it was"
    );
}

/// A `rigger` shim script for [`rigger_shim_on_path`] that predates `docs --check`: its `help`
/// lists `rigger docs` with no `--check`, and like such a build its `docs` ignores the flag
/// and renders, creating the two `using-rigger` outputs with fixed OLD text and printing a
/// `rendered ./<path>` line for each, so a hook that ever gives it `docs` leaves files behind.
/// Its `version` names it.
const PRE_CHECK_RIGGER_SHIM: &str = "#!/bin/sh\n\
case \"$1\" in\n\
  help)\n\
echo 'usage:' 1>&2\n\
echo '  rigger docs                 render the code-derived docs' 1>&2\n\
exit 0\n\
;;\n\
  docs)\n\
mkdir -p skills/using-rigger docs/handbook\n\
printf 'STALE DOC - not a real render\\n' > skills/using-rigger/SKILL.md\n\
echo 'rendered ./skills/using-rigger/SKILL.md'\n\
printf 'STALE DOC - not a real render\\n' > docs/handbook/using-rigger.md\n\
echo 'rendered ./docs/handbook/using-rigger.md'\n\
exit 0\n\
;;\n\
  version)\n\
echo 'rigger 0.0.0-pre-check-test-shim'\n\
exit 0\n\
;;\n\
esac\n\
exit 1\n";

/// A `rigger` shim script for [`rigger_shim_on_path`] older still, with no `help` verb: like
/// such a build it answers `help` as an unknown command, printing the usage text (which lists
/// `rigger docs` with no `--check`) and exiting 2. Its `docs` writes the `using-rigger` skill
/// with fixed OLD text, so a hook that ever gives it `docs` leaves a changed file behind. Its
/// `version` names it.
const PRE_HELP_RIGGER_SHIM: &str = "#!/bin/sh\n\
case \"$1\" in\n\
  docs)\n\
mkdir -p skills/using-rigger\n\
printf 'STALE DOC - not a real render\\n' > skills/using-rigger/SKILL.md\n\
exit 0\n\
;;\n\
  version)\n\
echo 'rigger 0.0.0-pre-check-test-shim'\n\
exit 0\n\
;;\n\
esac\n\
echo \"rigger: unknown command $1\" 1>&2\n\
echo 'usage:' 1>&2\n\
echo '  rigger docs                 render the code-derived docs' 1>&2\n\
exit 2\n";

/// Over a project `prepare` sets up with the hook installed, commit an unrelated change with
/// only `shim`, a `rigger` that predates `docs --check`, on `PATH`: the hook refuses, naming
/// that binary, its `version` and the remedy, HEAD does not move, and the index and every
/// working-tree file are exactly as they were - the binary is never given `docs`, so no output
/// is created or rewritten.
fn assert_the_hook_refuses_a_binary_too_old_to_check(prepare: fn(&Path), shim: &str) {
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    prepare(root);
    let commit_path = rigger_shim_on_path(root, shim);
    std::fs::write(root.join("code.txt"), "an unrelated change\n").unwrap();
    git_ok(root, &["add", "code.txt"]);
    let head_before = git_answer(root, &["rev-parse", "HEAD"]);
    let status_before = git_answer(root, &["status", "--porcelain"]);
    let working_tree_before = tree_snapshot(root, &[".git"]);

    let (ok, stderr) = commit_staged(root, &commit_path, "unrelated change");

    assert!(
        !ok,
        "a binary too old to check must refuse the commit; stderr:\n{stderr}"
    );
    let shim = root.join("shim-bin").join("rigger");
    for phrase in [
        "too old to check",
        shim.to_str().unwrap(),
        "rigger 0.0.0-pre-check-test-shim",
        "Rebuild rigger from this tree or reinstall it",
    ] {
        assert!(
            stderr.contains(phrase),
            "the refusal must name {phrase:?}; stderr:\n{stderr}"
        );
    }
    assert_eq!(
        git_answer(root, &["rev-parse", "HEAD"]),
        head_before,
        "a refused commit must not land"
    );
    assert_eq!(
        git_answer(root, &["status", "--porcelain"]),
        status_before,
        "the hook must leave the index and the working tree's status as it found them"
    );
    assert!(
        tree_snapshot(root, &[".git"]) == working_tree_before,
        "a binary too old to check is never given `docs`, so no output is created or \
         rewritten; stderr:\n{stderr}"
    );
}

/// An operator project: `rigger setup` (npm stubbed) installs the hook, and the repo tracks
/// none of the rendered outputs.
fn setup_operator_repo_with_the_hook(root: &Path) {
    setup_ok(root, &[]);
    assert!(
        root.join(".git/hooks/pre-commit").exists(),
        "setup must install the pre-commit hook in an operator repo too"
    );
}

rigger::test_cases! {
    /// In a self-hosting repo that tracks every rendered output, a binary too old to check is
    /// refused by name and never rewrites a tracked output.
    setup_precommit_hook_refuses_a_binary_too_old_to_check_in_a_tracking_repo:
        assert_the_hook_refuses_a_binary_too_old_to_check(
            setup_selfhosting_repo_with_fresh_docs,
            PRE_CHECK_RIGGER_SHIM,
        );
    /// In an operator project that tracks none of the rendered outputs, a binary too old to
    /// check is refused the same way and creates no output the operator did not ask for.
    setup_precommit_hook_refuses_a_binary_too_old_to_check_in_an_operator_repo:
        assert_the_hook_refuses_a_binary_too_old_to_check(
            setup_operator_repo_with_the_hook,
            PRE_CHECK_RIGGER_SHIM,
        );
    /// A binary whose `help` fails - one older than the `help` verb answers it as an unknown
    /// command - is refused the same way: a failed `help` never lets the commit proceed
    /// unchecked, and the binary is never given `docs`.
    setup_precommit_hook_refuses_a_binary_too_old_to_check_whose_help_fails:
        assert_the_hook_refuses_a_binary_too_old_to_check(
            setup_selfhosting_repo_with_fresh_docs,
            PRE_HELP_RIGGER_SHIM,
        );
}

/// Spec 24, crit 1 (operator repo is NOT polluted, end to end): the docs pre-commit hook is
/// installed the SAME way everywhere, but it checks ONLY the rendered outputs the repo already
/// TRACKS. In an OPERATOR project - one driving the operator's own code that tracks none of
/// these committed docs (spec 20's drift check treats their absence as "nothing to drift") -
/// the hook stays INERT even with `rigger` on PATH: an ordinary operator
/// commit carries none of rigger's internal discipline docs and the operator's worktree is not
/// polluted with them. Guards the operator-scoping (adj-u24-1 / d24-10) against regression.
#[test]
fn setup_precommit_hook_stays_inert_in_an_operator_repo() {
    // An OPERATOR repo: it drives the operator's OWN code and never tracks rigger's committed
    // `using-rigger` docs.
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    std::fs::write(root.join("README.md"), "operator project\n").unwrap();
    std::fs::create_dir_all(root.join("src")).unwrap();
    std::fs::write(root.join("src/app.rs"), "fn main() {}\n").unwrap();
    git_ok(root, &["add", "README.md", "src/app.rs"]);
    git_ok(
        root,
        &["commit", "-q", "--no-verify", "-m", "operator code"],
    );

    // `rigger setup` installs the SAME hook here (it cannot know at install time whether the
    // repo tracks the docs).
    setup_ok(root, &[]);
    assert!(
        root.join(".git/hooks/pre-commit").exists(),
        "the hook is installed in an operator repo too"
    );

    // `rigger` IS on PATH at commit time, so the hook DOES run - the ONLY thing keeping it
    // inert is that this repo does not track the docs.
    let commit_path = stage_rigger_shim(root);

    // An ordinary operator commit of the operator's OWN code.
    std::fs::write(root.join("src/app.rs"), "fn main() { let _ = 1; }\n").unwrap();
    git_ok(root, &["add", "src/app.rs"]);
    let (commit_ok, _) = commit_staged(root, &commit_path, "operator changes their own code");
    assert!(
        commit_ok,
        "the commit must succeed - the hook must never block it"
    );

    // The hook stayed INERT: the operator's commit carries their OWN change but NONE of
    // rigger's internal docs.
    let tree = git_answer(root, &["ls-tree", "-r", "--name-only", "HEAD"]).unwrap_or_default();
    assert!(
        tree.contains("src/app.rs"),
        "the operator's own change is committed; tree:\n{tree}"
    );
    assert!(
        !tree.contains("skills/using-rigger/SKILL.md")
            && !tree.contains("docs/handbook/using-rigger.md"),
        "an operator commit must NOT be forced to carry rigger's internal discipline docs; \
         tree:\n{tree}"
    );

    // And the worktree is not polluted with them either: the hook's check writes nothing, so
    // it created no files the operator did not ask for.
    assert!(
        !root.join("skills/using-rigger/SKILL.md").exists()
            && !root.join("docs/handbook/using-rigger.md").exists(),
        "the hook must not create rigger's committed docs in an operator worktree"
    );
}

/// Turn `root` into a rigger SELF-HOSTING repo for the pre-commit-hook SAFETY fixtures (spec 24,
/// crit 2): run `rigger setup` (npm stubbed) so the hook is installed, then TRACK stale committed
/// copies of both rendered docs, committed with `--no-verify` so the just-installed hook does NOT
/// fire and the seed stays genuinely STALE. After this the installed hook has real, tracked work
/// to do on the next ordinary commit, so any later "not STALE" / "still STALE" assertion actually
/// discriminates whether that commit's hook regenerated the docs.
fn setup_selfhosting_repo_with_stale_docs(root: &Path) {
    let out = setup_ok(root, &[]);
    assert!(
        out.contains("pre-commit hook"),
        "setup must install the pre-commit hook; got:\n{out}"
    );
    seed_stale_tracked_docs(root);
}

/// Stage a `rigger` shim on `PATH` that is PRESENT (so `command -v rigger` succeeds) but makes
/// `rigger docs` FAIL (exit 1), delegating every other subcommand to the real built binary. Drives
/// the graceful-degrade "rigger docs errors" path: the hook must WARN and let the commit proceed.
/// Returns a `PATH` with the shim dir prepended.
fn stage_failing_docs_rigger_shim(root: &Path) -> String {
    rigger_exec_shim_on_path(
        root,
        "if [ \"$1\" = docs ]; then\n  echo 'boom: rigger docs failed' 1>&2\n  exit 1\nfi\n",
    )
}

/// Place a copy of the REAL compiled `rigger` binary (the one this very test suite runs) at
/// `root`'s own local target dir (`./target/debug/rigger`) - spec 75's "this working tree's
/// own local target" candidate, the highest-priority tree-built candidate that needs no env
/// var. Simulates a worktree that has `cargo build`'d ITS OWN current code, so the hook has a
/// tree-built binary to prefer over whatever sits on PATH.
fn stage_tree_built_binary(root: &Path) {
    let dir = root.join("target").join("debug");
    copy_the_built_binary_into(&dir);
}

/// Stage a `rigger` on `PATH` that is a STALE binary standing in for an old build from before
/// this worktree's own code changed a rendered fact: `command -v rigger` succeeds, its `help`
/// lists `rigger docs --check` as a build that has the check does, but its `docs --check`
/// reports both `using-rigger` outputs `drifted` (a render older than the tree differs from
/// it), exits 1 and writes nothing, and its `version` subcommand names itself as a stale build -
/// never delegating to the real compiled binary, so it genuinely cannot match the tree's current
/// render no matter what invokes it. Pairs with [`stage_tree_built_binary`] to prove candidate
/// PREFERENCE (spec 75): present alongside a tree-built candidate it must lose to; present ALONE
/// it is the only binary reachable at all, so a reported drift is unavoidable. Returns a `PATH`
/// with the shim dir prepended.
fn stage_stale_rigger_shim(root: &Path) -> String {
    rigger_shim_on_path(root, STALE_RIGGER_SCRIPT)
}

/// The stale `rigger` [`stage_stale_rigger_shim`] puts on `PATH`: its `help` lists `rigger docs
/// --check`, its `docs --check` reports both `using-rigger` outputs `drifted` and exits 1, and
/// its `version` names itself as a stale build.
const STALE_RIGGER_SCRIPT: &str = "#!/bin/sh\n\
case \"$1 $2\" in\n\
  'help ')\n\
echo '  rigger docs --check         check every rendered output against a fresh render,' 1>&2\n\
exit 0\n\
;;\n\
  'docs --check')\n\
echo 'drifted skills/using-rigger/SKILL.md'\n\
echo 'drifted docs/handbook/using-rigger.md'\n\
exit 1\n\
;;\n\
  'version ')\n\
echo 'rigger 0.0.0-stale-test-shim'\n\
exit 0\n\
;;\n\
esac\n\
exit 1\n";

/// Stage the tree's own build at `current/rigger` under `root` beside a stale build at
/// `stale/rigger` - [`STALE_RIGGER_SCRIPT`], last modified an hour before the tree's build, or an
/// hour after it when `stale_is_newer` - and return a `PATH` whose `rigger` is that same stale
/// script. The commit passes only when the hook checks with the tree's build.
fn stage_the_tree_build_beside_a_stale_build(
    root: &Path,
    current: &str,
    stale: &str,
    stale_is_newer: bool,
) -> String {
    let current_dir = root.join(current);
    copy_the_built_binary_into(&current_dir);
    let stale_dir = root.join(stale);
    std::fs::create_dir_all(&stale_dir).unwrap();
    let stale_build = stale_dir.join("rigger");
    std::fs::write(&stale_build, STALE_RIGGER_SCRIPT).unwrap();
    make_executable(&stale_build);
    let current_built = std::fs::metadata(current_dir.join("rigger"))
        .and_then(|m| m.modified())
        .expect("the tree build's modification time");
    let hour = std::time::Duration::from_secs(3600);
    let stale_built = if stale_is_newer {
        current_built + hour
    } else {
        current_built - hour
    };
    std::fs::File::options()
        .write(true)
        .open(&stale_build)
        .and_then(|f| f.set_modified(stale_built))
        .expect("set the stale build an hour from the tree build");
    stage_stale_rigger_shim(root)
}

/// Spec 75, crit 2 (the SAME commit shape REFUSES with only a stale PATH rigger, end to end):
/// the flip side of the preference test above, proving the safe-closed direction. With no
/// tree-built candidate anywhere (no local target build this time) and PATH carrying only the
/// same stale shim, the hook has nothing to invoke but a binary that cannot reproduce the
/// tree's current render - so its check reports the fresh docs already committed as drifted
/// against ITS render, and the commit is refused exactly as an ordinary drift would be, never
/// silently let through for lack of a better binary.
#[test]
fn setup_precommit_hook_refuses_the_same_commit_shape_with_only_a_stale_path_rigger() {
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    setup_selfhosting_repo_with_fresh_docs(root);
    let fresh_skill_before = fresh_committed_skill(root);

    // No tree-built candidate staged anywhere this time - only the stale PATH rigger.
    let commit_path = stage_stale_rigger_shim(root);
    let (ok, stderr) = commit_a_code_change(
        root,
        &commit_path,
        "a rendered fact this worktree's code added\n",
        "add a rendered fact",
    );
    assert!(
        !ok,
        "with only a stale PATH rigger the same commit shape must still be REFUSED; \
         stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("skills/using-rigger/SKILL.md")
            && stderr.contains("docs/handbook/using-rigger.md"),
        "the refusal must name both docs the stale render drifted from; stderr:\n{stderr}"
    );

    let committed = committed_skill(root);
    assert_eq!(
        committed, fresh_skill_before,
        "a refused commit must not land - HEAD must still carry the fresh seed, not the stale \
         render"
    );
    let staged = git_answer(root, &["diff", "--cached", "--name-only"]).unwrap_or_default();
    assert!(
        !staged.contains("SKILL.md") && !staged.contains("using-rigger.md"),
        "the hook must never stage its own stale re-render; staged files:\n{staged}"
    );
}

/// Place a copy of the REAL compiled `rigger` binary at the UNIT-DERIVED candidate path
/// (spec 75's `<git-common-dir>/../.rigger/tmp/cargo-target-<unit>/debug/rigger`), keyed off
/// `main_repo_root` (the MAIN checkout's own root, never the linked worktree itself - the
/// candidate is resolved relative to `git-common-dir`, which for a linked worktree points
/// back at the main repo's `.git`, not a directory inside the worktree).
fn stage_unit_derived_binary(main_repo_root: &Path, unit: &str) {
    let dir = main_repo_root
        .join(".rigger")
        .join("tmp")
        .join(format!("cargo-target-{unit}"))
        .join("debug");
    copy_the_built_binary_into(&dir);
}

/// Spec 75, crit 2, closing a gap this unit's own periphery accounting left open
/// (sdet-u75c2-unit-derived-candidate-never-executed): the two tests above exercise only the
/// "own local target" tier (`stage_tree_built_binary`, `./target/debug/rigger`) - a plain,
/// non-worktree temp git project can never even reach the UNIT-DERIVED tier, because
/// `basename $(git rev-parse --show-toplevel)` never matches `rigger-wt-*` there. Every real
/// unit gate in this loop runs inside exactly such a worktree - this very test suite is
/// compiled from one - so the unit-derived tier is the candidate spec 75 was written to serve
/// FIRST, not an edge case, yet nothing before this test ever drove it through a real `git
/// worktree add` and real `/bin/sh` execution. Uses a genuinely linked worktree named
/// `rigger-wt-probeunit`, whose `git-common-dir` resolves back to the MAIN checkout's `.git`
/// (verified: that is exactly how this very spawn's own worktree resolves), and proves
/// discrimination twice over in the SAME worktree: first REFUSED with nothing but the stale
/// PATH shim (proving the hook genuinely fires inside a linked worktree at all - without this
/// half, a hook that silently never ran there would make the pass below vacuous), then the
/// identical staged commit PASSES once the unit-derived binary is staged at the path the hook
/// computes relative to `git-common-dir`.
#[test]
fn setup_precommit_hook_prefers_a_unit_derived_binary_in_a_real_linked_worktree_over_a_stale_path_rigger(
) {
    let main = temp_git_project_with_commit();
    let main_root = main.path();
    setup_selfhosting_repo_with_fresh_docs(main_root);
    let fresh_skill_before = fresh_committed_skill(main_root);

    let wt_parent = tempfile::tempdir().expect("create a parent dir for the linked worktree");
    let wt_path = wt_parent.path().join("rigger-wt-probeunit");
    git_ok(
        main_root,
        &[
            "worktree",
            "add",
            wt_path.to_str().expect("utf8 worktree path"),
            "-b",
            "probeunit-branch",
        ],
    );

    let commit_path = stage_stale_rigger_shim(&wt_path);

    // Round 1: no unit-derived candidate staged anywhere yet, and this worktree has no local
    // target build either - only the stale PATH shim is reachable, so this must REFUSE exactly
    // like the plain (non-worktree) fixture above, proving the hook genuinely runs here.
    let (committed1, stderr1) = commit_a_code_change(
        &wt_path,
        &commit_path,
        "a rendered fact this worktree's code added\n",
        "add a rendered fact",
    );
    assert!(
        !committed1,
        "with no unit-derived candidate staged, a linked worktree with only a stale PATH \
         rigger must still be REFUSED, same as the plain-project fixture; stderr:\n{stderr1}"
    );
    assert!(
        stderr1.contains("skills/using-rigger/SKILL.md")
            && stderr1.contains("docs/handbook/using-rigger.md"),
        "the round-1 refusal must name both drifted docs; stderr:\n{stderr1}"
    );
    let staged1 = git_answer(&wt_path, &["diff", "--cached", "--name-only"]).unwrap_or_default();
    assert!(
        staged1.contains("code.txt"),
        "the refused round-1 commit must leave code.txt staged, unreverted; staged:\n{staged1}"
    );

    // Round 2: same staged snapshot, now WITH the unit-derived candidate staged at the path
    // relative to `main_root`'s own `.git` (never inside the worktree) - the only thing that
    // changed between rounds is this candidate's presence.
    stage_unit_derived_binary(main_root, "probeunit");
    let (committed2, stderr2) = commit_staged(&wt_path, &commit_path, "add a rendered fact");
    assert!(
        committed2,
        "the unit-derived candidate must be found and PREFERRED over the stale PATH rigger \
         once staged; stderr:\n{stderr2}"
    );
    assert!(
        !stderr2.contains("refusing"),
        "a matching unit-derived render must never refuse; stderr:\n{stderr2}"
    );

    let tree = git_answer(&wt_path, &["ls-tree", "-r", "--name-only", "HEAD"]).unwrap_or_default();
    assert!(
        tree.contains("code.txt"),
        "the worktree's own change must ride the commit; tree:\n{tree}"
    );
    assert_eq!(
        committed_skill(&wt_path),
        fresh_skill_before,
        "the already-fresh doc must land byte-identical - the unit-derived binary's render \
         matched what was staged"
    );

    git_ok(
        main_root,
        &[
            "worktree",
            "remove",
            "--force",
            wt_path.to_str().expect("utf8 worktree path"),
        ],
    );
}

/// Spec 24, crit 2 (idempotency, end to end): the hook is SAFE to live in everyone's
/// `.git/hooks` - re-running `rigger setup` does NOT duplicate it. The installed hook is
/// byte-identical after a second setup, still carries exactly one managed block, and the rerun
/// does not re-report installing the hook (it is a true no-op).
#[test]
fn setup_precommit_hook_is_idempotent_no_duplicate_block_on_rerun() {
    const BEGIN: &str = "# >>> BEGIN rigger docs pre-commit (managed - do not edit) >>>";
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    setup_ok(root, &[]);
    let hook_path = root.join(".git/hooks/pre-commit");
    let first = std::fs::read_to_string(&hook_path).unwrap();
    assert_eq!(
        first.matches(BEGIN).count(),
        1,
        "one managed block after the first setup; got:\n{first}"
    );

    let out2 = setup_ok(root, &[]);
    let second = std::fs::read_to_string(&hook_path).unwrap();
    assert_eq!(
        first, second,
        "re-running setup does not rewrite the hook (a true no-op)"
    );
    assert_eq!(
        second.matches(BEGIN).count(),
        1,
        "no duplicate managed block on a rerun; got:\n{second}"
    );
    assert!(
        !out2.contains("pre-commit hook"),
        "an up-to-date rerun must not re-report installing the hook; got:\n{out2}"
    );
}

/// The upgrade path, end to end: `rigger setup` over an installed hook whose managed block an
/// older build wrote - one that rendered into the working tree and compared only the
/// `using-rigger` pair - replaces that block in place with the current one, which runs
/// `docs --check`, keeps the hook's own lines on both sides of the block, and leaves exactly
/// one managed block.
#[test]
fn setup_precommit_hook_replaces_an_older_builds_block_in_place() {
    const BEGIN: &str = "# >>> BEGIN rigger docs pre-commit (managed - do not edit) >>>";
    const END: &str = "# <<< END rigger docs pre-commit (managed) <<<";
    const OLD_LOOP: &str =
        "for doc in \"skills/using-rigger/SKILL.md\" \"docs/handbook/using-rigger.md\"; do";
    const OLD_RENDER: &str = "\"$rigger_bin\" docs >/dev/null 2>&1";
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    let hooks = root.join(".git/hooks");
    std::fs::create_dir_all(&hooks).unwrap();
    let hook_path = hooks.join("pre-commit");
    std::fs::write(
        &hook_path,
        format!(
            "#!/bin/sh\necho before-block\n{BEGIN}\n{OLD_LOOP}\n    :\ndone\n{OLD_RENDER}\n\
             {END}\necho after-block\n"
        ),
    )
    .unwrap();
    make_executable(&hook_path);

    let out = setup_ok(root, &[]);
    let hook = std::fs::read_to_string(&hook_path).unwrap();
    assert!(
        out.contains("refreshed the docs pre-commit hook"),
        "setup must report refreshing the older block; got:\n{out}"
    );
    assert!(
        hook.contains("\"$rigger_bin\" docs --check")
            && !hook.contains(OLD_LOOP)
            && !hook.contains(OLD_RENDER),
        "the older block's two-path loop and render are gone and the check is in; got:\n{hook}"
    );
    assert!(
        hook.contains("echo before-block\n") && hook.ends_with("echo after-block\n"),
        "the hook's own lines on both sides of the block are kept; got:\n{hook}"
    );
    assert_eq!(
        (hook.matches(BEGIN).count(), hook.matches(END).count()),
        (1, 1),
        "exactly one managed block; got:\n{hook}"
    );
}

/// Spec 24, crit 2 (non-clobbering chaining defeats a TERMINAL existing hook, end to end): the
/// modal hand-written / sample pre-commit hook ends in a terminal `exit 0`. rigger chains its
/// block onto it WITHOUT clobbering it, and - crucially - rigger's block still RUNS: it is
/// inserted BEFORE the existing hook body (which ends in `exit 0`), so a `git commit` runs BOTH
/// the pre-existing hook AND rigger's docs check. Regression-guards
/// adv-u24-1r-chained-terminal-hook-shadows-rigger-block-silently (d24-11): appending rigger's
/// block after such a hook would let the `exit 0` silently shadow it. Uses the MATCHING-render
/// fixture (spec 70, crit 1) rather than a stale one, since a REFUSED commit never reaches the
/// chained hook at all by design - this test isolates the chaining/ordering property alone.
#[test]
fn setup_precommit_hook_chains_after_a_terminal_exit_hook_and_still_runs() {
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    // A pre-existing pre-commit hook that does work and ends in a TERMINAL `exit 0`.
    let hooks = root.join(".git/hooks");
    std::fs::create_dir_all(&hooks).unwrap();
    let user_hook = hooks.join("pre-commit");
    std::fs::write(&user_hook, "#!/bin/sh\ntouch USER_HOOK_RAN\nexit 0\n").unwrap();
    make_executable(&user_hook);

    // `rigger setup` chains its block onto the pre-existing hook; then make it self-hosting with
    // ALREADY-FRESH tracked docs so the final commit's hook finds no drift and falls through.
    setup_selfhosting_repo_with_fresh_docs(root);
    let fresh_skill_before = committed_skill(root);

    // The chained hook carries BOTH the user hook's command and rigger's block.
    let hook = std::fs::read_to_string(&user_hook).unwrap();
    assert!(
        hook.contains("touch USER_HOOK_RAN") && hook.contains("rigger docs"),
        "the chained hook must preserve the user hook AND carry rigger's block; got:\n{hook}"
    );

    let commit_path = stage_rigger_shim(root);
    let (commit_ok, _) = commit_a_code_change(
        root,
        &commit_path,
        "a documented fact changed\n",
        "change a documented fact",
    );
    assert!(
        commit_ok,
        "a matching render must let the commit through - the hook must never block it"
    );

    // The PRE-EXISTING hook still ran (its side effect is present)...
    assert!(
        root.join("USER_HOOK_RAN").exists(),
        "the pre-existing hook must still run when chained"
    );
    // ...AND rigger's block ALSO ran despite the existing hook's terminal `exit 0`: it checked
    // the docs (no drift found) and fell through, landing the SAME fresh bytes unchanged. A
    // terminal-shadow bug (append-after) would have skipped rigger's block entirely, which this
    // cannot distinguish from "ran and found nothing to do" - the reachability is proven by the
    // block-position assertion above; this proves it did not somehow corrupt what it read.
    let committed = committed_skill(root);
    assert_eq!(
        committed, fresh_skill_before,
        "rigger's block must leave an already-fresh doc byte-identical; got:\n{committed}"
    );
}

/// Spec 70, crit 1 (comparison scope, end to end): the hook checks ONLY the tracked rendered
/// outputs and writes nothing; it never touches any other working-tree file. Since the hook
/// stages nothing at all (it only ever refuses or falls through), an UNTRACKED junk file and an
/// UNSTAGED edit to an unrelated tracked file both stay exactly as the operator left them across
/// a commit whose docs are already the fresh render.
#[test]
fn setup_precommit_hook_never_touches_unrelated_files() {
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    // A tracked file whose later UNSTAGED modification must NOT ride the commit.
    std::fs::write(root.join("other.txt"), "original\n").unwrap();
    git_ok(root, &["add", "other.txt"]);
    git_ok(
        root,
        &["commit", "-q", "--no-verify", "-m", "add other.txt"],
    );

    setup_selfhosting_repo_with_fresh_docs(root);
    let commit_path = stage_rigger_shim(root);

    // Working-tree noise the hook must NOT touch: an UNTRACKED junk file and an UNSTAGED edit to
    // a tracked file.
    std::fs::write(root.join("junk.txt"), "not for the commit\n").unwrap();
    std::fs::write(root.join("other.txt"), "MODIFIED but not staged\n").unwrap();

    // Stage ONE unrelated change and commit; the docs are already fresh so nothing else happens.
    std::fs::write(root.join("trigger.txt"), "trigger\n").unwrap();
    git_ok(root, &["add", "trigger.txt"]);
    let (commit_ok, _) = commit_staged(root, &commit_path, "trigger");
    assert!(commit_ok, "a matching render must let the commit through");

    let tree = git_answer(root, &["ls-tree", "-r", "--name-only", "HEAD"]).unwrap_or_default();
    assert!(
        tree.contains("trigger.txt"),
        "the staged change must ride the commit; tree:\n{tree}"
    );
    assert!(
        !tree.contains("junk.txt"),
        "the hook must never stage an unrelated untracked file; tree:\n{tree}"
    );
    let committed_other = git_answer(root, &["show", "HEAD:other.txt"]).unwrap_or_default();
    assert_eq!(
        committed_other, "original",
        "the hook must never stage an unrelated tracked file's unstaged modification; got:\n{committed_other}"
    );
    // The worktree noise is left untouched.
    assert!(
        root.join("junk.txt").exists(),
        "the untracked file is left in the worktree, not deleted or staged"
    );
    assert_eq!(
        std::fs::read_to_string(root.join("other.txt")).unwrap(),
        "MODIFIED but not staged\n",
        "the tracked file's unstaged modification is left in the worktree"
    );
}

/// Over a self-hosting repo whose committed docs are STALE, commit a change with `PATH` set
/// to `path(root)`, a `rigger` the hook cannot check with: the hook never blocks the commit,
/// prints `warning`, and regenerates nothing.
fn assert_the_hook_warns_and_proceeds(path: fn(&Path) -> String, message: &str, warning: &str) {
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    setup_selfhosting_repo_with_stale_docs(root);

    let path = path(root);
    let (ok, stderr) = commit_a_code_change(root, &path, "changed\n", message);
    assert!(
        ok,
        "the commit must succeed - the hook must never block it; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains(warning),
        "the hook must WARN {warning:?}; stderr:\n{stderr}"
    );
    let committed = committed_skill(root);
    assert!(
        committed.contains("STALE DOC"),
        "a hook that cannot render regenerates nothing; got:\n{committed}"
    );
}

rigger::test_cases! {
    /// Spec 24, crit 2 (graceful degrade when rigger is UNAVAILABLE, end to end): with `rigger`
    /// removed from `PATH`, the hook WARNS and lets the commit PROCEED - it never blocks a commit.
    /// The docs are not regenerated (the spec-20 drift check is the backstop, not the hook), so HEAD
    /// keeps the stale seed.
    ///
    /// The warning names that every tree-built candidate AND `PATH` were checked (spec 75).
    setup_precommit_hook_warns_and_proceeds_when_rigger_is_unavailable:
        assert_the_hook_warns_and_proceeds(
            |_| path_without("rigger"),
            "change with rigger off PATH",
            "no rigger binary found",
        );
    /// Spec 24, crit 2 (graceful degrade when `rigger docs --check` ERRORS, end to end): `rigger`
    /// is on `PATH` (so `command -v rigger` succeeds) but its docs check fails without reporting
    /// any output. The hook WARNS and lets the commit PROCEED - a transient generator failure
    /// degrades to "caught later" by the drift check, never "cannot commit". HEAD keeps the stale
    /// seed.
    setup_precommit_hook_warns_and_proceeds_when_rigger_docs_errors:
        assert_the_hook_warns_and_proceeds(
            stage_failing_docs_rigger_shim,
            "change while rigger docs errors",
            "rigger docs --check failed",
        );
}

/// Spec 24, crit 2 (a PARTLY tracked repo, end to end): a repo that tracks ONE rendered
/// output, a stale `using-rigger` skill, but not the handbook chapter has the tracked one
/// checked: the hook refuses naming the skill, and since its check writes nothing it creates
/// no stray handbook file the operator did not ask for.
#[test]
fn setup_precommit_hook_checks_the_one_tracked_output_of_a_partly_tracked_repo() {
    const SKILL_REL: &str = "skills/using-rigger/SKILL.md";
    const HANDBOOK_REL: &str = "docs/handbook/using-rigger.md";
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    // Install the hook the SAME way everywhere (it cannot know at install time what the repo
    // will track), then track ONLY a stale copy of the skill.
    setup_ok(root, &[]);
    commit_stale_outputs(root, &[SKILL_REL]);

    let commit_path = stage_rigger_shim(root);
    let (commit_ok, stderr) = commit_a_code_change(
        root,
        &commit_path,
        "a documented fact changed\n",
        "change with only the skill tracked",
    );
    assert!(
        !commit_ok,
        "the one tracked output is checked and its drift refuses the commit; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains(SKILL_REL) && !stderr.contains(HANDBOOK_REL),
        "the refusal names the tracked skill and not the untracked handbook; stderr:\n{stderr}"
    );
    let committed = git_answer(root, &["show", &format!("HEAD:{SKILL_REL}")]).unwrap_or_default();
    assert!(
        committed.contains("STALE DOC"),
        "a refused commit must not land; got:\n{committed}"
    );
    assert!(
        !root.join(HANDBOOK_REL).exists(),
        "the hook must not create the untracked handbook as a stray file in the worktree"
    );
}

/// Spec 70, crit 1 (a REFUSAL aborts the WHOLE hook, including anything chained after it, end
/// to end): rigger's block is inserted BEFORE a pre-existing hook's body (spec 24 chaining), and
/// its `exit 1` on a detected drift is deliberately NOT cooperative - `precommit_block`'s own doc
/// comment states it "must abort the whole hook (including anything chained after it), because a
/// commit that is about to be refused should not go on to run further gates." No existing test
/// drives this: the chaining test
/// (`setup_precommit_hook_chains_after_a_terminal_exit_hook_and_still_runs`) deliberately swaps
/// to a MATCHING-render fixture specifically to stay off the refusal path, so this exact safety
/// claim has zero coverage until this test. Drives the refusal path with a pre-existing chained
/// hook present and proves its body never runs.
#[test]
fn setup_precommit_hook_refusal_aborts_a_chained_hook_body() {
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    // A pre-existing pre-commit hook that leaves a detectable side effect if it runs.
    let hooks = root.join(".git/hooks");
    std::fs::create_dir_all(&hooks).unwrap();
    let user_hook = hooks.join("pre-commit");
    std::fs::write(&user_hook, "#!/bin/sh\ntouch USER_HOOK_RAN\nexit 0\n").unwrap();
    make_executable(&user_hook);

    // `rigger setup` chains its block BEFORE the existing hook body (spec 24); seed genuinely
    // STALE tracked docs so the final commit's hook has real drift to refuse.
    let setup_out = setup_ok(root, &[]);
    assert!(
        setup_out.contains("pre-commit hook"),
        "setup must install the pre-commit hook; got:\n{setup_out}"
    );
    seed_stale_tracked_docs(root);

    let hook = std::fs::read_to_string(&user_hook).unwrap();
    assert!(
        hook.contains("touch USER_HOOK_RAN") && hook.contains("rigger docs"),
        "the chained hook must preserve the user hook AND carry rigger's block; got:\n{hook}"
    );

    let commit_path = stage_rigger_shim(root);
    let (committed, _) = commit_a_code_change(
        root,
        &commit_path,
        "a documented fact changed\n",
        "change a documented fact",
    );

    assert!(
        !committed,
        "a drifted render must refuse the commit even with a chained hook present"
    );
    assert!(
        !root.join("USER_HOOK_RAN").exists(),
        "a refusal must abort the WHOLE hook script before reaching the chained body that \
         follows rigger's block - the pre-existing hook's side effect must never appear"
    );
}

// ---------------------------------------------------------------------------
// Spec 38, criterion 3 - the ready-to-release handoff, PROVEN THROUGH THE BINARY.
//
// The inside-out unit tests (`ledger::release_ready_surfaces_only_a_done_run`,
// `main::release_ready_lines_surface_only_on_a_done_run`, `dash::release_ready_is_surfaced_
// on_the_dash_only_for_a_done_run`) call the pure projection and render seams IN-PROCESS.
// They never drive the compiled `rigger` binary against a REAL namespaced event store, so
// they cannot prove that `cmd_status` / `cmd_dash` actually WIRE the handoff onto the
// operator-facing surfaces, that the run-branch/base resolution (`resolve_run_base`, the
// `RIGGER_BASE` override, the `origin/` -> branch strip) reaches the printed PR command
// end-to-end, or that an unfinished / deferred-gate-failed run surfaces NOTHING through the
// same seam. These periphery tests drive the binary against a seeded store to guard exactly
// that boundary.
// ---------------------------------------------------------------------------

/// The handoff (`ReleaseReady::lines`) surfaces on `rigger status` for a DONE run: the run
/// branch, the release-target base, the integrated-unit count, and the EXACT `gh pr create`
/// command, resolved through the whole store -> project -> release_ready -> render path the
/// binary walks. The `RIGGER_BASE` override then proves the resolved base (with the
/// `origin/` remote prefix stripped) reaches the surfaced PR command, which no in-process
/// unit test exercises (they call `release_ready` with a fixed base directly).
#[test]
fn release_ready_handoff_surfaces_on_status_for_a_done_run() {
    let dir = temp_store_project();
    let root = dir.path();
    // A done run: one unit started and integrated, no failed deferred gate.
    seed_run_events(
        root,
        &[
            ("RunStarted", r#"{"run":"r1","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
        ],
    );

    // Default base (`origin/main` -> `main`): `rigger status` names all four facts.
    let (out, err, ok) = run_rigger(root, &["status"]);
    assert!(
        ok,
        "rigger status must succeed on a done run; stderr:\n{err}"
    );
    assert!(
        out.contains("release-ready:"),
        "a done run surfaces the release-ready handoff on status; got:\n{out}"
    );
    assert!(
        out.contains("rigger-run"),
        "the handoff names the run branch (the PR head); got:\n{out}"
    );
    assert!(
        out.contains("1 unit integrated"),
        "the handoff names the integrated-unit count; got:\n{out}"
    );
    // Spec 82, criterion 1: the PR command is the two-command unique-head flow - the seeded
    // run's id ("r1", no spec) degrades the head to the run-short-id alone, `pr/r1` - never
    // the literal run branch as `--head`.
    assert!(
        out.contains("git push origin rigger-run:pr/r1"),
        "the handoff names the push half of the unique-head flow; got:\n{out}"
    );
    assert!(
        out.contains("gh pr create --base main --head pr/r1"),
        "the handoff names the exact PR command, with `origin/main` stripped to `main` and \
         the head a per-run-unique branch, never the run branch itself; got:\n{out}"
    );
    assert!(
        !out.contains("--head rigger-run"),
        "the literal `--head <run_branch>` form must never appear; got:\n{out}"
    );

    // The `RIGGER_BASE` override flows through `resolve_run_base` into the surfaced PR
    // command, and its `origin/` remote prefix is stripped to the release-target branch -
    // proven end-to-end through the binary, not just the in-process projection.
    let (out, err, ok) =
        run_rigger_envs(root, &["status"], &[("RIGGER_BASE", "origin/release-2.0")]);
    assert!(ok, "rigger status honors RIGGER_BASE; stderr:\n{err}");
    assert!(
        out.contains("gh pr create --base release-2.0 --head pr/r1"),
        "the RIGGER_BASE override reaches the PR command with `origin/` stripped; got:\n{out}"
    );
}

/// Spec 82, criterion 1's own done-when test (THE STATUS HANDOFF IS UNIQUE): on a fully-done
/// run, `rigger status` emits the two-command flow pushing `<run_branch>` to
/// `pr/<spec-stem>-<run-short-id>` and creating the PR from that head, with the head derived
/// from the run's spec stem AND its short run id (git-ref-safe) - and the literal
/// `--head <run_branch>` form NOWHERE in the output. Unlike the other tests in this file
/// (which seed no spec and so only exercise the degraded run-id-only head), this seeds a REAL
/// spec path so the full `<spec-stem>-<run-short-id>` derivation is proven end-to-end through
/// the compiled binary, and proves two runs of the SAME spec never collide on one PR head.
#[test]
fn release_ready_hands_off_a_unique_per_run_pr_head_naming_the_spec_stem_and_run_id() {
    let dir = temp_store_project();
    let root = dir.path();
    seed_run_events(
        root,
        &[
            (
                "RunStarted",
                r#"{"run":"7ad52031-01f1-4d37-aa19-ad48090f84a5","criteria":["spec 82"],"spec":"specs/82-unique-pr-heads.md"}"#,
            ),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
        ],
    );
    let (out, err, ok) = run_rigger(root, &["status"]);
    assert!(
        ok,
        "rigger status must succeed on a done run; stderr:\n{err}"
    );
    let head = "pr/82-unique-pr-heads-7ad52031-01f";
    assert!(
        out.contains(&format!("git push origin rigger-run:{head}")),
        "status names the push half of the unique-head flow; got:\n{out}"
    );
    assert!(
        out.contains(&format!("gh pr create --base main --head {head}")),
        "status names the create half, with the head naming the spec stem AND the 12-char \
         run-short-id; got:\n{out}"
    );
    assert!(
        !out.contains("--head rigger-run"),
        "the literal `--head <run_branch>` form is nowhere in the output; got:\n{out}"
    );

    // Two runs of the SAME spec differ only in run id, so their heads never collide.
    let dir2 = temp_project();
    let root2 = dir2.path();
    seed_store(root2);
    seed_run_events(
        root2,
        &[
            (
                "RunStarted",
                r#"{"run":"a1a1a1a1a1a1a1a1a1a1","criteria":["spec 82"],"spec":"specs/82-unique-pr-heads.md"}"#,
            ),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
        ],
    );
    let (out2, err2, ok2) = run_rigger(root2, &["status"]);
    assert!(ok2, "rigger status must succeed; stderr:\n{err2}");
    let pr_line = |s: &str| {
        s.lines()
            .find(|l| l.trim_start().starts_with("gh pr create"))
            .map(str::to_string)
    };
    assert_ne!(
        pr_line(&out),
        pr_line(&out2),
        "two runs of the SAME spec must never share one PR head; got:\n{out}\n---\n{out2}"
    );
}

/// Spec 82, criterion 1's CROSS-MODULE seam (diff-grounded): `rigger run` threads its real
/// spec argument into the persisted `RunStarted` body as the run's `spec` - the everyday path
/// every spec-driven run takes on its first launch. Every other test proving criterion 1 seeds
/// the `RunStarted` body directly via `seed_run_events`, bypassing this wiring entirely, and
/// the run module's own unit test calls `start_fresh` as a plain Rust function with an explicit
/// `spec_path`, bypassing the CLI argument parsing. Neither would catch a regression that
/// dropped the spec argument on this path. This test drives the REAL spec argument through
/// `rigger run` across a real process boundary, reads the persisted `RunStarted` body straight
/// off disk to prove the exact spec path landed untouched, then proves it reaches `rigger
/// status`'s rendered PR head through a SECOND real process - never a single in-process call
/// standing in for both halves.
#[test]
fn the_real_spec_argument_persists_on_a_real_run_and_reaches_the_status_pr_head() {
    let dir = temp_git_project_with_commit();
    let root = dir.path();
    let rigger = root.join(".rigger");
    std::fs::create_dir_all(rigger.join("agents")).unwrap();
    std::fs::write(
        rigger.join("agents").join("worker.md"),
        "---\nid: worker\nmodel: sonnet\ntools: [Read, Edit]\nisolation: none\n---\nDo the unit.\n",
    )
    .unwrap();
    std::fs::write(
        rigger.join("workflow.yml"),
        r#"defaults:
  grounder: nop
  budget: 60
gates:
  human: { run: "true", kind: core }
stages:
  implement:
    agent: worker
    strategy: fan-out
    gates: [human]
    on_pass: none
"#,
    )
    .unwrap();
    std::fs::create_dir_all(root.join("specs")).unwrap();
    let spec_rel = "specs/u82c1-wiring-check.md";
    std::fs::write(
        root.join(spec_rel),
        "# Spec\n\n## Done when\n\n- [ ] widget\n",
    )
    .unwrap();

    // A REAL `rigger run <path>` - the everyday first launch of a spec-driven run - mints
    // RunStarted and synthesizes the sole baseline unit.
    let (out, err, ok) = run_reporting(root, &["run", spec_rel]);
    assert!(
        ok,
        "the real spec-driven run must succeed; stderr:\n{err}\nstdout:\n{out}"
    );

    // Read the RunStarted (and the synthesized baseline unit's id) straight off the real
    // on-disk store - a SEPARATE read from the run that minted them - and confirm the exact
    // spec argument landed in the body untouched: proves the run threads its spec argument,
    // not a dropped or hand-typed value.
    let (run_id, persisted_spec, unit_id) = {
        let events = read_run_events(root);
        let started = events
            .iter()
            .find(|e| e.type_ == rigger::run::TYPE_RUN_STARTED)
            .expect("the real run must mint a RunStarted");
        let body: serde_json::Value = serde_json::from_slice(&started.data).unwrap();
        let unit_started = events
            .iter()
            .find(|e| e.type_ == rigger::ledger::TYPE_UNIT_STARTED)
            .expect("the real run must synthesize the sole baseline unit");
        let unit_body: serde_json::Value = serde_json::from_slice(&unit_started.data).unwrap();
        (
            body["run"].as_str().unwrap().to_string(),
            body["spec"].as_str().unwrap_or("").to_string(),
            unit_body["id"].as_str().unwrap().to_string(),
        )
    };
    assert_eq!(
        persisted_spec, spec_rel,
        "the real spec argument must reach the persisted RunStarted body unchanged"
    );

    // Settle the baseline unit as integrated (this test's only job is proving the spec-path
    // wire, not re-running the full gate flow) so the run is release-ready.
    seed_run_events(
        root,
        &[(
            "UnitIntegrated",
            &format!(r#"{{"id":"{unit_id}","commit":"abc"}}"#),
        )],
    );

    // A SECOND real process (`rigger status`) re-reads the SAME on-disk store and derives the
    // PR head from the RunStarted this test never hand-seeded - proving the wiring survives a
    // genuine process boundary, using this run's OWN randomly-minted id, not a fixture one.
    let (out, err, ok) = run_rigger(root, &["status"]);
    assert!(
        ok,
        "rigger status must succeed on a done run; stderr:\n{err}"
    );
    let short = &run_id[..run_id.len().min(12)];
    let head = format!("pr/u82c1-wiring-check-{short}");
    assert!(
        out.contains(&format!("git push origin rigger-run:{head}")),
        "the real spec argument's stem (u82c1-wiring-check) and this run's OWN minted id \
         must both reach the printed PR head; got:\n{out}"
    );
    assert!(
        out.contains(&format!("gh pr create --base main --head {head}")),
        "got:\n{out}"
    );
    assert!(
        !out.contains("--head rigger-run"),
        "the literal `--head <run_branch>` form must never appear; got:\n{out}"
    );
}

/// The handoff is SILENT through `rigger status` for any run that is not done: a
/// still-un-integrated unit, and (the load-bearing guard) a run whose every unit integrated
/// but whose deferred phase-boundary gate FAILED - which must never be advertised as a
/// finished, releasable run. No in-process test proves the CLI seam honors either negative.
#[test]
fn release_ready_is_silent_on_status_for_an_unfinished_run() {
    // A run with a still-un-integrated unit surfaces no release-ready signal.
    let dir = temp_store_project();
    let root = dir.path();
    seed_run_events(
        root,
        &[
            ("RunStarted", r#"{"run":"r1","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
            ("UnitStarted", r#"{"id":"u2","agent":"worker"}"#),
        ],
    );
    let (out, err, ok) = run_rigger(root, &["status"]);
    assert!(ok, "rigger status must succeed; stderr:\n{err}");
    assert!(
        !out.contains("release-ready:") && !out.contains("gh pr create"),
        "an unfinished run surfaces NO release-ready handoff on status; got:\n{out}"
    );

    // Every unit integrated, but a deferred phase-boundary gate FAILED: not done, so the
    // handoff must stay silent - the run is not releasable.
    let dir2 = temp_project();
    let root2 = dir2.path();
    seed_store(root2);
    seed_run_events(
        root2,
        &[
            ("RunStarted", r#"{"run":"r2","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
            ("DeferredGateFailed", r#"{"gate":"itest"}"#),
        ],
    );
    let (out, err, ok) = run_rigger(root2, &["status"]);
    assert!(ok, "rigger status must succeed; stderr:\n{err}");
    assert!(
        !out.contains("release-ready:") && !out.contains("gh pr create"),
        "a failed deferred phase-boundary gate is never advertised as releasable; got:\n{out}"
    );
}

/// `rigger dash --export` threads the run branch and the resolved release base into
/// `render_export`, so the exported static snapshot carries the SAME handoff on a done run -
/// and omits it for an unfinished run. This is the ONLY periphery coverage of the `cmd_dash`
/// export seam (no in-process test drives `cmd_dash`), and it proves the exported artifact -
/// the file an operator opens - carries the exact PR command.
#[test]
fn release_ready_handoff_reaches_the_dash_export_snapshot() {
    // A done run: the exported HTML carries the exact PR command.
    let dir = temp_store_project();
    let root = dir.path();
    seed_run_events(
        root,
        &[
            ("RunStarted", r#"{"run":"r1","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
        ],
    );
    let (out, err, ok) = run_rigger(root, &common::cli::DASH_SNAPSHOT_ARGS);
    assert!(ok, "rigger dash --export must succeed; stderr:\n{err}");
    assert!(
        out.contains("wrote dash snapshot"),
        "the export confirms it wrote the snapshot; got:\n{out}"
    );
    let html = std::fs::read_to_string(root.join("snapshot.html"))
        .expect("the export writes the snapshot file");
    // Spec 82, criterion 1: the unique-head flow (head = `pr/r1`, this run's own id - no
    // spec was seeded, so it degrades to the run-short-id alone).
    assert!(
        html.contains("gh pr create --base main --head pr/r1"),
        "the exported snapshot carries the handoff's exact PR command: {html}"
    );
    assert!(
        !html.contains("--head rigger-run"),
        "the exported snapshot never carries the literal run-branch-as-head form"
    );

    // An unfinished run: the exported snapshot carries NO release-ready handoff.
    let dir2 = temp_project();
    let root2 = dir2.path();
    seed_store(root2);
    seed_run_events(
        root2,
        &[
            ("RunStarted", r#"{"run":"r2","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
            ("UnitStarted", r#"{"id":"u2","agent":"worker"}"#),
        ],
    );
    let (_out, err, ok) = run_rigger(root2, &common::cli::DASH_SNAPSHOT_ARGS);
    assert!(ok, "rigger dash --export must succeed; stderr:\n{err}");
    let html = std::fs::read_to_string(root2.join("snapshot.html"))
        .expect("the export writes the snapshot file");
    assert!(
        !html.contains("gh pr create"),
        "an unfinished run's exported snapshot carries no release-ready handoff"
    );
}

/// The handoff PLURALIZES the integrated-unit count on `rigger status` for a run that
/// integrated MORE THAN ONE unit. Every other release-ready test seeds exactly ONE
/// integrated unit, so `integrated_units` is only ever asserted `== 1` and only the
/// singular branch of `ReleaseReady::lines` runs; the count-of-two and the plural
/// (`unit` -> `units`) arm ship unexercised, so a miscount or a wrong pluralization would
/// stay green. This drives the binary against a two-integrated-unit done run and asserts
/// the plural render reaches the operator's terminal.
#[test]
fn release_ready_pluralizes_the_unit_count_on_status_for_a_multi_unit_run() {
    let dir = temp_store_project();
    let root = dir.path();
    // A done run with TWO integrated units (no failed deferred gate, no spec defect).
    seed_run_events(
        root,
        &[
            ("RunStarted", r#"{"run":"r1","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
            ("UnitStarted", r#"{"id":"u2","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u2","commit":"def"}"#),
        ],
    );
    let (out, err, ok) = run_rigger(root, &["status"]);
    assert!(
        ok,
        "rigger status must succeed on a done run; stderr:\n{err}"
    );
    assert!(
        out.contains("release-ready:"),
        "a done multi-unit run surfaces the release-ready handoff on status; got:\n{out}"
    );
    assert!(
        out.contains("2 units integrated"),
        "the handoff pluralizes the count for more than one integrated unit (the plural \
         arm of ReleaseReady::lines), naming BOTH the count 2 and the plural noun; got:\n{out}"
    );
    assert!(
        !out.contains("1 unit integrated"),
        "a two-integrated-unit run must not render the singular count; got:\n{out}"
    );
}

/// `rigger status` names the run's PERSISTED base (spec 38, criterion 3): the base is read
/// from the run's `RunStarted` `META_BASE` metadata via `runscope::current_run_base`, so the
/// surfaced PR command targets the branch the run ACTUALLY anchored on - even though status
/// runs without the run's `--base` flag on its argv. This is the outside-in guard for the
/// base-asymmetry boundary: the persisted base must WIN over the live env re-resolution, so
/// the test seeds `META_BASE = origin/release-9.9` AND passes a DECOY `RIGGER_BASE` the
/// re-resolution would otherwise pick; a status that re-resolved (the pre-fix behavior) would
/// name the decoy. `current_run_base` / `META_BASE` are new public API exercised end-to-end
/// through the compiled binary here, which no in-process unit test does.
#[test]
fn release_ready_names_the_runs_persisted_base_on_status_over_a_re_resolution() {
    let dir = temp_store_project();
    let root = dir.path();
    // A done run whose RunStarted persists its resolved run-branch base in META_BASE, the way
    // `runscope::start_fresh` stamps the resolved `--base` at mint.
    seed_done_run_with_persisted_base(root, "origin/release-9.9");

    // No `--base` on the status argv, and a DECOY `RIGGER_BASE` the fallback re-resolution
    // would pick: the persisted base must win, so the PR command names `release-9.9` (with the
    // `origin/` remote prefix stripped), never the decoy `main-decoy`.
    let (out, err, ok) =
        run_rigger_envs(root, &["status"], &[("RIGGER_BASE", "origin/main-decoy")]);
    assert!(ok, "rigger status must succeed; stderr:\n{err}");
    assert!(
        out.contains("gh pr create --base release-9.9 --head pr/r1"),
        "status names the run's PERSISTED base (origin/release-9.9 -> release-9.9), read from \
         META_BASE, not a re-resolution off the decoy RIGGER_BASE; got:\n{out}"
    );
    assert!(
        !out.contains("main-decoy"),
        "the decoy RIGGER_BASE must never reach the PR command once a base is persisted; \
         got:\n{out}"
    );
}

/// The handoff is SILENT through `rigger status` for a run that HALTED on a coverage gap - a
/// flagged `SpecDefect` - even though the one unit it did plan integrated (so `done()` alone
/// is true). Release-ready gates on the full-done predicate (`!done() || spec_defect`): a
/// spec-defective run has NOT finished the job, so it must advertise no release PR. This
/// drives the exact boundary a prior review found gate-invisible (no seeded spec-defect run),
/// proving the spec-defect conjunct of the release_ready gate holds through the binary.
#[test]
fn release_ready_is_silent_on_status_for_a_spec_defective_run() {
    let dir = temp_store_project();
    let root = dir.path();
    // Every planned unit integrated, but the coverage gate flagged a SpecDefect: done() is
    // true, yet the run halted on an uncovered criterion, so it is not releasable.
    seed_run_events(
        root,
        &[
            ("RunStarted", r#"{"run":"r1","criteria":["spec 38"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
            ("UnitIntegrated", r#"{"id":"u1","commit":"abc"}"#),
            ("SpecDefect", r#"{"criterion":"c2"}"#),
        ],
    );
    let (out, err, ok) = run_rigger(root, &["status"]);
    assert!(ok, "rigger status must succeed; stderr:\n{err}");
    assert!(
        !out.contains("release-ready:") && !out.contains("gh pr create"),
        "a run halted on a coverage gap (SpecDefect) is never advertised as releasable; \
         got:\n{out}"
    );
}

/// Seed a done run whose `RunStarted` carries a PERSISTED release base in `META_BASE`
/// metadata (spec 38, criterion 3), the way `runscope::start_fresh` stamps the resolved
/// `--base` at mint - so a later `rigger status`, which runs without the run's `--base` on
/// its argv, reads the run's ACTUAL base from the log via `runscope::current_run_base`
/// instead of re-resolving it from the environment. One unit is started and integrated so the
/// run is done and the handoff surfaces.
fn seed_done_run_with_persisted_base(root: &Path, base: &str) {
    use rigger::eventstore::{Event, ExpectedRevision};

    let rigger_dir = root.join(".rigger");
    std::fs::create_dir_all(&rigger_dir).unwrap();
    let events = [
        Event::new(
            rigger::run::TYPE_RUN_STARTED,
            br#"{"run":"r1","criteria":["spec 38"]}"#.to_vec(),
        )
        .with_meta(rigger::run::META_BASE, base),
        Event::new(
            rigger::ledger::TYPE_UNIT_STARTED,
            br#"{"id":"u1","agent":"worker"}"#.to_vec(),
        ),
        Event::new(
            rigger::ledger::TYPE_UNIT_INTEGRATED,
            br#"{"id":"u1","commit":"abc"}"#.to_vec(),
        ),
    ];
    common::cli::with_run_store(root, |store| {
        store
            .append(rigger::conductor::STREAM, ExpectedRevision::Any, &events)
            .unwrap();
    });
}

/// Spec 50, criterion 4 (opt-out) - the CONTRACT and BACK-COMPAT of the config opt-out at the
/// PUBLIC config-load boundary. The run's opt-out reads `Workflow::dash_enabled()` off the
/// workflow the binary loads through the public `rigger::config::load`; this drives that REAL load
/// path - parse AND validate a FULL, valid `workflow.yml` on disk (agents + stages + defaults), the
/// exact fixture `rigger run` loads - rather than a bare `serde_yaml::from_str` of a one-key
/// document. It therefore guards the whole outside-in surface an in-crate unit test cannot reach.
/// First, the new `dash` key is PUBLIC and honored end-to-end through `config::load`. Second,
/// BACK-COMPAT: a pre-existing `workflow.yml` that says nothing about the dash still loads and keeps
/// the always-on promise (`dash_enabled()` true), so old configs are never broken. Third, the
/// `dash` field composes inside a complete, VALIDATED workflow, not a one-key document. The
/// documented bare `dash: off` / `dash: on` and the quoted `false`/`no`/`true`/`OFF`/` off `
/// synonyms (case- and whitespace-insensitive) resolve as the opt-out spec names. This is the
/// config-side contract that the CLI test `rigger_run_honors_each_dash_opt_out_and_starts_its_dash_without_one` then proves
/// end-to-end at the binary; this side is pure `config::load`, binds no port, and spawns no process.
#[test]
fn config_load_dash_enabled_is_the_public_opt_out_contract_and_back_compat() {
    // The SAME full, valid project the real loader accepts that `rigger run` drives: an agents dir
    // plus a two-stage `workflow.yml`, so this exercises the exact production `config::load` path.
    let proj = temp_git_project_with_commit();
    let root = proj.path();
    let dir = root.to_str().expect("utf-8 project path");
    let wf_path = root.join(".rigger").join("workflow.yml");

    // BACK-COMPAT: the fixture's `workflow.yml` says NOTHING about the dash - exactly as every
    // config authored before this key did. It still loads AND keeps the always-on promise.
    write_workflow_fixture(root, &TWO_STAGE_WORKFLOW);
    let cfg = rigger::config_store::load(dir).expect("a workflow that omits `dash` still loads");
    assert!(
        cfg.workflow.dash_enabled(),
        "an omitted `dash` key keeps the always-on dash ON (back-compat)"
    );

    // Every opt-out value resolves the dash OFF through the real load path. Each case rewrites the
    // fixture fresh (never appending a SECOND `dash:` onto a prior one), so the result is
    // order-insensitive and no duplicate-key parse error can mask a regression. `dash: off` is the
    // BARE documented form; the rest are quoted to pin the case- and whitespace-insensitive match.
    let off_forms: &[&str] = &[
        "dash: off",
        r#"dash: "OFF""#,
        r#"dash: " off ""#,
        r#"dash: "Off""#,
        r#"dash: "false""#,
        r#"dash: "no""#,
    ];
    for form in off_forms {
        write_workflow_fixture(root, &TWO_STAGE_WORKFLOW);
        append_line(&wf_path, form);
        let cfg = rigger::config_store::load(dir).expect("a workflow with `dash` set still loads");
        assert!(
            !cfg.workflow.dash_enabled(),
            "`{form}` must resolve the opt-out OFF through config::load"
        );
    }

    // A truthy / empty value keeps the always-on dash ON through the same path. `dash: on` is the
    // BARE documented truthy counterpart to `dash: off`; `true` and the empty string are quoted.
    let on_forms: &[&str] = &["dash: on", r#"dash: "true""#, r#"dash: """#];
    for form in on_forms {
        write_workflow_fixture(root, &TWO_STAGE_WORKFLOW);
        append_line(&wf_path, form);
        let cfg = rigger::config_store::load(dir).expect("a workflow with `dash` set still loads");
        assert!(
            cfg.workflow.dash_enabled(),
            "`{form}` keeps the always-on dash ON through config::load"
        );
    }
}

// --- Spec 39, criterion 2: the step-started dash is DETACHED - it persists across the run's
// many short-lived `step` processes. Criterion 1 (above) owns start-once idempotency; THIS
// criterion owns PERSISTENCE: the dash a `step` starts is still serving after that step process
// has exited, and stays the same live process across a LATER step process, because it is NOT
// bound to a `ReapedChild` in any step process (a guard-bound dash would be reaped the instant
// the step's `main` returned, and nothing would be alive or serving afterwards).

// --- Spec 50, criterion 5: the machine-level SINGLETON dash SELF-REAPS only when NOTHING is
// registered-and-alive for the idle window. This RETARGETS spec 39's per-run liveness trigger ("my
// run went idle") at the singleton: the dash serves every registered instance and outlives any
// single run, so its reap is driven by the machine-global INSTANCE REGISTRY, not one project's
// `agent-live` heartbeat. The dash.rs unit test proves the pure decision (`should_reap_singleton`);
// only driving the real `rigger dash --reap-on-idle` binary against a live registry proves the
// watcher WIRING - that a genuinely-serving detached singleton keeps serving while any instance
// heartbeats and exits ITSELF once the registry empties, with no other process killing it.

/// Write one registry instance for `project` at `root` (a local store) into `regdir`, its
/// heartbeat stamped `heartbeat_ms`.
fn write_instance(regdir: &std::path::Path, project: &str, root: &str, heartbeat_ms: u64) {
    use rigger::registry::{Instance, StoreIdentity};
    let inst = Instance {
        project: project.to_string(),
        root: root.to_string(),
        store: StoreIdentity::Local {
            path: format!("{root}/.rigger/events.db"),
        },
        heartbeat_ms,
        writer: rigger::registry::Writer::Driver,
    };
    rigger::registry::write(regdir, &inst).expect("write a registry instance");
}

/// Write (or refresh) one live instance into the registry `regdir` with a heartbeat stamped NOW.
/// Stands in for a run driver's `register_run_instance` heartbeat without spawning a real run - the
/// registry is the singleton watcher's ONLY liveness signal, so the test controls it directly. A
/// distinct `project`+`root` pair produces a distinct entry (the registry's id keys on them), so
/// two calls with different projects register two independent live instances.
fn write_live_instance(regdir: &std::path::Path, project: &str, root: &str) {
    write_instance(regdir, project, root, rigger::registry::now_ms());
}

/// Write a registry instance for `project` at `root` with a heartbeat already at the unix epoch -
/// hopelessly stale from the moment it is written, unlike [`write_live_instance`]'s fresh
/// `now_ms()` heartbeat. Used to prove a property a fresh-then-ages-out entry cannot: a registered
/// project whose registry entry was NEVER live during the watcher's own lifetime.
fn write_stale_instance(regdir: &std::path::Path, project: &str, root: &str) {
    write_instance(regdir, project, root, 0);
}

/// A background thread running `beat` every 150 ms until [`Heartbeat::stop`]ped - a live run's
/// registry heartbeat or a live agent's liveness-marker touch, simulated without a real run.
struct Heartbeat {
    stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
    handle: std::thread::JoinHandle<()>,
}

impl Heartbeat {
    fn start(beat: impl Fn() + Send + 'static) -> Self {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::Arc;

        let stop = Arc::new(AtomicBool::new(false));
        let thread_stop = stop.clone();
        let handle = std::thread::spawn(move || {
            while !thread_stop.load(Ordering::Relaxed) {
                beat();
                std::thread::sleep(std::time::Duration::from_millis(150));
            }
        });
        Heartbeat { stop, handle }
    }

    /// A liveness marker at `path`, touched fresh now and kept fresh until stopped.
    fn of_marker(path: std::path::PathBuf) -> Self {
        touch_marker(&path);
        Heartbeat::start(move || touch_marker(&path))
    }

    fn stop(self) -> std::thread::Result<()> {
        self.stop.store(true, std::sync::atomic::Ordering::Relaxed);
        self.handle.join()
    }
}

/// A `rigger dash --port <free port> <args>` with its stdout piped and watched: the dash logs to
/// stderr, so stdout stays empty-and-open until the process exits, and a 0-byte read (EOF)
/// means it exited. Dropping it - on success or on any panicking assertion - stops its
/// [`Heartbeat`] (if any) and reaps the process, so nothing leaks.
struct WatchedDash {
    child: std::process::Child,
    port: u16,
    exited: std::sync::mpsc::Receiver<usize>,
    heartbeat: Option<Heartbeat>,
}

impl WatchedDash {
    fn launch(
        args: &[&str],
        heartbeat: Option<Heartbeat>,
        configure: impl FnOnce(&mut Command) -> &mut Command,
    ) -> Self {
        use std::io::Read;
        use std::process::Stdio;

        let port = free_loopback_port();
        let mut cmd = common::rigger_courier();
        cmd.args(["dash", "--port", &port.to_string()])
            .args(args)
            .env_remove("RIGGER_NO_DASH");
        let mut child = configure(&mut cmd)
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .expect("failed to spawn `rigger dash`");
        let mut out = child.stdout.take().expect("dash stdout is piped");

        let (tx, exited) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let mut buf = [0u8; 1];
            let n = out.read(&mut buf).unwrap_or(0);
            let _ = tx.send(n);
        });
        WatchedDash {
            child,
            port,
            exited,
            heartbeat,
        }
    }

    /// The dash is genuinely SERVING its read-only page (not merely a blocked-but-dead pipe).
    fn serving(&self) -> bool {
        matches!(
            http_get(&format!("http://127.0.0.1:{}/", self.port)),
            Some(body) if body.contains("rigger dash")
        )
    }

    /// The dash must not exit within `ms` - a read arriving here is a premature self-reap.
    fn assert_stays_up_for(&self, ms: u64, why: &str) {
        if self
            .exited
            .recv_timeout(std::time::Duration::from_millis(ms))
            .is_ok()
        {
            panic!("{why}");
        }
    }

    /// Stop the heartbeat, if any, then the dash must exit ITSELF within 12 s, its stdout at EOF.
    fn assert_self_reaps(mut self, why: &str) {
        if let Some(heartbeat) = self.heartbeat.take() {
            heartbeat.stop().expect("heartbeat thread joins");
        }
        let n = self
            .exited
            .recv_timeout(std::time::Duration::from_secs(12))
            .expect(why);
        assert_eq!(n, 0, "a self-reaped dash should have its stdout at EOF");
    }

    /// Well past many poll intervals the dash must STILL be up: no watcher reaped it.
    fn assert_never_self_reaps(self, why: &str) {
        let reaped = self.exited.recv_timeout(std::time::Duration::from_secs(2));
        assert!(reaped.is_err(), "{why}");
    }
}

impl Drop for WatchedDash {
    fn drop(&mut self) {
        if let Some(heartbeat) = self.heartbeat.take() {
            let _ = heartbeat.stop();
        }
        // Nothing owns this dash in the test (in production its parent's `ReapedChild` would);
        // on the self-reaped path the process already exited and this just collects it.
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// A machine-global registry the dash and the test share: a temp state home (so no
/// process-global `~/.local/state` write happens), its `XDG_STATE_HOME` value, and its
/// instances dir.
fn shared_registry() -> (tempfile::TempDir, String, std::path::PathBuf) {
    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap().to_string();
    let regdir = rigger::registry::instances_dir(state.path());
    (state, xdg, regdir)
}

/// A foreign project holding NO `.rigger/workflow.yml` (so its scratch root falls to the plain
/// `<root>/.rigger/tmp` default rung - the resolution its own `rigger` would use, per
/// `foreign_instance_scratch_root`), its root, and its implementer's agent-liveness marker path.
fn foreign_project_marker() -> (tempfile::TempDir, String, std::path::PathBuf) {
    let project = tempfile::tempdir().unwrap();
    let root = project.path().to_str().unwrap().to_string();
    let scratch_root = common::default_scratch_root(project.path())
        .to_str()
        .unwrap()
        .to_string();
    let marker =
        rigger::liveness::marker_path(&scratch_root, "run-1", "u2c1/implementer#0").unwrap();
    (project, root, marker)
}

/// Spec 50, criterion 5 end-to-end, through the BUILT binary: a detached `rigger dash --reap-on-idle`
/// (the exact flag the ensure path passes) keeps serving WHILE a registered instance heartbeats, and
/// SELF-REAPS once the registry empties - leaving no orphaned dash on a quiet machine. Nothing in
/// this test ever kills the dash, so its exit is proof of SELF-reap driven by the REGISTRY, not by a
/// `step` process or a `ReapedChild` guard.
///
/// The instance is a real entry under a temp `XDG_STATE_HOME` the dash and the test share; a
/// background thread REFRESHES its heartbeat to simulate a live run, so the registry stays non-empty
/// until the test lets it go idle. The piped stdout is a race-free liveness probe exactly as the
/// guard-reaping test uses: a blocked read means the dash lives; EOF means it exited.
#[test]
fn a_reap_on_idle_singleton_serves_while_an_instance_heartbeats_then_reaps_when_the_registry_empties(
) {
    let (_state, xdg, regdir) = shared_registry();

    // One live instance, kept fresh by a background thread - a live run's registry heartbeat.
    write_live_instance(&regdir, "proj-a", "/home/dev/proj-a");
    let heartbeat =
        Heartbeat::start(move || write_live_instance(&regdir, "proj-a", "/home/dev/proj-a"));

    let dash = WatchedDash::launch(&["--reap-on-idle"], Some(heartbeat), |cmd| {
        cmd.env("XDG_STATE_HOME", &xdg)
            // Poll fast and treat an instance heartbeat older than 2s as idle, so the self-reap is
            // observable within the test rather than on the shipped multi-minute cadence.
            .env("RIGGER_DASH_REAP_POLL_MS", "150")
            .env("RIGGER_DASH_REAP_STALE_SECS", "2")
    });
    assert!(
        dash.serving(),
        "the `rigger dash --reap-on-idle` never served its page"
    );

    // While the instance heartbeats, the singleton must NOT reap - a live run keeps it serving. A
    // read arriving here would mean it reaped a live machine (a premature self-reap): fail LOUD.
    dash.assert_stays_up_for(
        1200,
        "the singleton self-reaped while an instance was still live - premature reap",
    );

    // Let the registry go idle: stop heartbeating. The one entry ages past the 2s window, the
    // watcher's `read_live` prunes it, and with zero live instances the singleton exits ITSELF.
    dash.assert_self_reaps(
        "the singleton did not SELF-REAP within 12s after its registry went idle - a machine-idle \
         dash must not leak",
    );
}

/// Spec 50, criterion 5 - THE headline through the BUILT binary: the singleton SURVIVES one project's
/// run ending while ANOTHER project's run is still live, then reaps once BOTH are idle. Two registered
/// instances heartbeat; when project A's heartbeat stops (its entry ages out and `read_live` prunes
/// it) the dash must KEEP serving because B is still live; only when B's heartbeat also stops does the
/// registry empty and the singleton self-reap. This is the exact multi-instance lifecycle the
/// machine-level singleton exists for - a per-run dash keyed on one run's liveness would wrongly die
/// when A ended, which is the regression this test locks out.
#[test]
fn a_reap_on_idle_singleton_survives_one_run_ending_while_another_project_is_live() {
    use std::io::Read;
    use std::process::Stdio;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::{mpsc, Arc};
    use std::time::Duration;

    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap().to_string();
    let regdir = rigger::registry::instances_dir(state.path());

    // TWO live instances (two projects), each refreshed by its own independently-stoppable thread.
    write_live_instance(&regdir, "proj-a", "/home/dev/proj-a");
    write_live_instance(&regdir, "proj-b", "/home/dev/proj-b");
    let stop_a = Arc::new(AtomicBool::new(false));
    let stop_b = Arc::new(AtomicBool::new(false));
    let spawn_heartbeat = |project: &'static str, root: &'static str, stop: Arc<AtomicBool>| {
        let dir = regdir.clone();
        std::thread::spawn(move || {
            while !stop.load(Ordering::Relaxed) {
                write_live_instance(&dir, project, root);
                std::thread::sleep(Duration::from_millis(150));
            }
        })
    };
    let hb_a = spawn_heartbeat("proj-a", "/home/dev/proj-a", stop_a.clone());
    let hb_b = spawn_heartbeat("proj-b", "/home/dev/proj-b", stop_b.clone());

    let port = free_loopback_port();
    let mut child = common::rigger_courier()
        .args(["dash", "--port", &port.to_string(), "--reap-on-idle"])
        .env("XDG_STATE_HOME", &xdg)
        .env("RIGGER_DASH_REAP_POLL_MS", "150")
        .env("RIGGER_DASH_REAP_STALE_SECS", "2")
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash --reap-on-idle`");
    let mut out = child.stdout.take().expect("dash stdout is piped");

    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        let mut buf = [0u8; 1];
        let n = out.read(&mut buf).unwrap_or(0);
        let _ = tx.send(n);
    });

    let stop_all = |a: &Arc<AtomicBool>, b: &Arc<AtomicBool>| {
        a.store(true, Ordering::Relaxed);
        b.store(true, Ordering::Relaxed);
    };

    if !matches!(http_get(&format!("http://127.0.0.1:{port}/")), Some(body) if body.contains("rigger dash"))
    {
        stop_all(&stop_a, &stop_b);
        let _ = hb_a.join();
        let _ = hb_b.join();
        let _ = child.kill();
        let _ = child.wait();
        panic!("the singleton never served its page");
    }

    // Project A's run ENDS: stop refreshing A. Its entry ages past the 2s window and is pruned, but B
    // keeps heartbeating - so at least one instance stays live and the singleton must KEEP serving.
    // Wait well past the window (and several polls) with B alive: a read here is the exact wrong
    // behavior - a machine-level dash dying because ONE of several runs ended.
    stop_a.store(true, Ordering::Relaxed);
    hb_a.join().expect("A heartbeat thread joins");
    if rx.recv_timeout(Duration::from_millis(3500)).is_ok() {
        stop_b.store(true, Ordering::Relaxed);
        let _ = hb_b.join();
        let _ = child.kill();
        let _ = child.wait();
        panic!(
            "the singleton reaped when project A's run ended while project B was still live - it \
             must survive one run ending as long as another instance heartbeats"
        );
    }
    // It is still genuinely serving B's machine (not merely a blocked-but-dead pipe).
    assert!(
        matches!(http_get(&format!("http://127.0.0.1:{port}/")), Some(body) if body.contains("rigger dash")),
        "the singleton must still serve while project B is live"
    );

    // Now project B ends too: with the registry empty, the singleton self-reaps.
    stop_b.store(true, Ordering::Relaxed);
    hb_b.join().expect("B heartbeat thread joins");
    let reaped = rx.recv_timeout(Duration::from_secs(12));
    let _ = child.kill();
    let _ = child.wait();
    let n = reaped.expect(
        "the singleton did not SELF-REAP within 12s after BOTH runs ended - a quiet machine's dash \
         must not leak",
    );
    assert_eq!(n, 0, "a self-reaped dash should have its stdout at EOF");
}

/// Spec 50, criterion 5 - the STARTUP-RACE guard through the BUILT binary: a singleton the ensure
/// path just started reads an EMPTY registry until its ensuring run writes its entry, and must NOT
/// reap on those first empty polls (the `ever_seen_live` latch, the analogue of spec 39's
/// `run_started`). The dash boots against an empty registry and must keep serving across many poll
/// intervals; only after an instance registers and then goes idle does it reap - proving the guard
/// delays the reap to first-sight, not that the watcher is simply absent (the no-flag test below
/// proves absence separately).
#[test]
fn a_reap_on_idle_singleton_does_not_reap_before_any_instance_has_registered() {
    // An EMPTY registry at boot: no instance has registered yet (the ensure-then-register gap).
    let (_state, xdg, regdir) = shared_registry();

    let mut dash = WatchedDash::launch(&["--reap-on-idle"], None, |cmd| {
        cmd.env("XDG_STATE_HOME", &xdg)
            // A tiny window so that WITHOUT the guard the empty registry would reap almost
            // immediately - making the ABSENCE of an early reap a strong signal the
            // `ever_seen_live` latch holds.
            .env("RIGGER_DASH_REAP_POLL_MS", "100")
            .env("RIGGER_DASH_REAP_STALE_SECS", "1")
    });
    assert!(
        dash.serving(),
        "the singleton never served its page against an empty registry"
    );

    // Across MANY windows with a registry that has never held a live instance, the singleton must
    // NOT reap: it has never seen a live instance, so the safe direction is to keep serving. A read
    // here is a premature reap the `ever_seen_live` guard exists to prevent.
    dash.assert_stays_up_for(
        2500,
        "the singleton self-reaped before ANY instance registered - the startup-race guard must \
         hold the reap until a live instance has been seen",
    );

    // Now an instance registers and heartbeats: the dash keeps serving, and after it goes idle the
    // singleton self-reaps - proving the watcher was running all along and the guard, not its
    // absence, delayed the reap.
    dash.heartbeat = Some(Heartbeat::start(move || {
        write_live_instance(&regdir, "proj-a", "/home/dev/proj-a")
    }));
    // Let a few polls observe the live instance (flip `ever_seen_live`), still serving.
    dash.assert_stays_up_for(800, "the singleton reaped while a fresh instance was live");

    dash.assert_self_reaps(
        "the singleton did not SELF-REAP within 12s after its one instance went idle - once a live \
         instance has been seen, a return to an empty registry must reap",
    );
}

/// Write (or refresh) a liveness marker file at `path`, creating its parent directory as needed.
/// Rewriting an existing file refreshes its mtime - the direct-filesystem analogue of a spawn's
/// own heartbeat touch (spec 10), used here to simulate a live agent without spawning a real
/// worker process. Stands in for the raw `touch` a real agent performs; the marker's CONTENT is
/// never read by anything, only its mtime.
fn touch_marker(path: &std::path::Path) {
    std::fs::create_dir_all(path.parent().unwrap()).expect("create marker parent dir");
    std::fs::write(path, b"").expect("write liveness marker");
}

/// A `--reap-on-idle` singleton whose registry holds ONE never-refreshed entry (it ages out
/// on its own past the fast test window) while an in-flight agent's liveness marker under a
/// hermetic `RIGGER_TMPDIR` stays fresh - launched, with `git_less_cwd`, from a cwd with NO
/// `.git` anywhere above it (what a git-excluding whole-tree copy launches `rigger dash` from),
/// so the only way it can find that scratch root is by honoring `RIGGER_TMPDIR` even with an
/// empty repo. Well past the registry's 2s window the singleton must NOT reap - the idle
/// judgment must see the agent, not just the registry - and once the marker goes idle too,
/// with BOTH signals quiet, it reaps exactly as spec 50 criterion 5 always has.
fn assert_a_fresh_agent_marker_outlives_an_aged_out_registry(git_less_cwd: bool) {
    let (_state, xdg, regdir) = shared_registry();
    let (_scratch, scratch_root) = common::fixtures::temp_root();
    let marker_path =
        rigger::liveness::marker_path(&scratch_root, "run-1", "u1c1/implementer#0").unwrap();
    let cwd = tempfile::tempdir().unwrap();

    write_live_instance(&regdir, "proj-a", "/home/dev/proj-a");
    let heartbeat = Heartbeat::of_marker(marker_path);

    let dash = WatchedDash::launch(&["--reap-on-idle"], Some(heartbeat), |cmd| {
        if git_less_cwd {
            cmd.current_dir(cwd.path());
        }
        // Fast poll/stale envs: the registry entry above ages out within ~2s, and (were the
        // agent-liveness signal absent) the singleton would reap almost immediately after - a
        // strong signal if it wrongly does.
        cmd.env("XDG_STATE_HOME", &xdg)
            .env("RIGGER_TMPDIR", &scratch_root)
            .env("RIGGER_DASH_REAP_POLL_MS", "150")
            .env("RIGGER_DASH_REAP_STALE_SECS", "2")
    });
    assert!(
        dash.serving(),
        "the `rigger dash --reap-on-idle` never served its page"
    );

    dash.assert_stays_up_for(
        3500,
        "the singleton self-reaped while the registry was empty but a fresh in-flight agent \
         liveness marker was still present under RIGGER_TMPDIR - the idle judgment must see the \
         agent, not just the registry, and a repo-less cwd must not blind it",
    );
    // Still genuinely serving (not merely a blocked-but-dead pipe).
    assert!(
        dash.serving(),
        "the singleton must still serve while the agent liveness marker is fresh"
    );

    dash.assert_self_reaps(
        "the singleton did not SELF-REAP within 12s after BOTH the registry and the agent \
         liveness marker went idle - a genuinely quiet machine's dash must not leak",
    );
}

rigger::test_cases! {
    /// Spec 62, criterion 5 (SINGLETON SURVIVES LIVE WORK, OWNS the idle judgment) end to end,
    /// through the BUILT binary: a `rigger dash --reap-on-idle` must NOT self-reap while a fresh
    /// in-flight AGENT liveness marker is present, even once the machine-global instance REGISTRY has
    /// genuinely aged out and gone empty - the exact gap the registry-only decision (spec 50 criterion
    /// 5, proven by the sibling tests above) left open: an agent mid-build with no recent courier call
    /// keeps its own liveness marker fresh (spec 10's heartbeat) without necessarily refreshing the
    /// registry on the same cadence. Only once BOTH the registry AND the agent liveness marker have
    /// gone quiet does the singleton reap - proving this criterion's own OWNED idle judgment, not
    /// just the registry-only judgment the sibling tests already lock in.
    ///
    /// The registry instance is written ONCE (never re-heartbeated), so it ages out on its own past
    /// the fast test window - the "aged-out registry" the Done-when text names. A background thread
    /// keeps a SEPARATE liveness marker fresh under a temp scratch root (`RIGGER_TMPDIR`), standing in
    /// for a real spawn's own heartbeat touch, until the test lets it go idle too.
    a_reap_on_idle_singleton_survives_a_fresh_agent_liveness_marker_after_the_registry_ages_out:
        assert_a_fresh_agent_marker_outlives_an_aged_out_registry(false);
    /// Spec 62, criterion 5 - the SAME survives-live-work guarantee as the test above, but launched
    /// from a directory with NO git repository above it at all. `cmd_dash`'s own scratch-root
    /// resolution derives `git_repo()` first and, before this fix, treated an EMPTY `git_repo()` as a
    /// hard "no scratch root, ever": it skipped `worktree::scratch_root_from_env` (and therefore
    /// `RIGGER_TMPDIR`) entirely, rather than letting that resolver's own env-override-first
    /// precedence handle a repo-less cwd - which it already does correctly on its own
    /// (`scratch_root_path`'s first match arm answers `RIGGER_TMPDIR` regardless of `repo`). A
    /// `rigger` invocation with no git repository above its cwd is not exotic: it is exactly what a
    /// whole-tree copy that excludes `.git` produces - including this project's OWN
    /// `cargo mutants --in-diff` scratch-tree build (spec 78's mutation-efficacy step every
    /// implementer runs), which is how this gap was actually found: a mutation baseline run failed
    /// this criterion's own sibling test above ONLY when run from that git-less copy, never from a
    /// real git worktree. A git-less launch silently blinding the self-reap watcher to its OWN
    /// launching project's agent-liveness marker is a real, reachable production gap, not a
    /// test-only corner.
    a_reap_on_idle_singleton_survives_a_fresh_agent_liveness_marker_with_no_git_repo_at_launch:
        assert_a_fresh_agent_marker_outlives_an_aged_out_registry(true);
}

/// A `--reap-on-idle` singleton whose LAUNCHING project's own scratch root is hermetic and
/// left EMPTY (its own agent-liveness signal reads false throughout, and the test stays off
/// the real repo's own live `agent-live` markers), while a SECOND, foreign registered project's
/// own agent liveness marker stays fresh under ITS OWN scratch root. The foreign registry entry
/// is written ONCE and never refreshed: fresh (it ages out past the fast test window), or with
/// `already_stale` at the unix epoch - hopelessly stale before the dash even spawns, so
/// `read_live` would prune it unseen on the very first poll, with a THIRD project supplying the
/// `ever_seen_live` startup latch by one fresh write that decays. Well past the 2s window every
/// registry is empty, but the singleton must NOT reap - `known_roots` must have learned the
/// foreign root (from `read_all`, which returns a stale entry too) and the idle judgment must
/// see every registered project's agent liveness; once that marker goes idle too, it reaps.
fn assert_a_foreign_projects_fresh_agent_marker_holds_the_reap(already_stale: bool) {
    let (_state, xdg, regdir) = shared_registry();
    let (_own_scratch, own_scratch_root) = common::fixtures::temp_root();
    let (_other_project, other_root, other_marker_path) = foreign_project_marker();

    let latch_project = tempfile::tempdir().unwrap();
    if already_stale {
        let latch_root = latch_project.path().to_str().unwrap().to_string();
        write_live_instance(&regdir, "proj-latch", &latch_root);
        write_stale_instance(&regdir, "proj-b", &other_root);
    } else {
        write_live_instance(&regdir, "proj-b", &other_root);
    }
    let heartbeat = Heartbeat::of_marker(other_marker_path);

    let dash = WatchedDash::launch(&["--reap-on-idle"], Some(heartbeat), |cmd| {
        cmd.env("XDG_STATE_HOME", &xdg)
            .env("RIGGER_TMPDIR", &own_scratch_root)
            .env("RIGGER_DASH_REAP_POLL_MS", "150")
            .env("RIGGER_DASH_REAP_STALE_SECS", "2")
    });
    assert!(
        dash.serving(),
        "the `rigger dash --reap-on-idle` never served its page"
    );

    dash.assert_stays_up_for(
        3500,
        "the singleton self-reaped while a DIFFERENT registered project's own agent liveness \
         marker was still fresh - the idle judgment must see every registered project's agent \
         liveness, even one whose registry entry was ALREADY stale on the watcher's first poll",
    );
    // Still genuinely serving (not merely a blocked-but-dead pipe).
    assert!(
        dash.serving(),
        "the singleton must still serve while the OTHER project's agent liveness marker is fresh"
    );

    dash.assert_self_reaps(
        "the singleton did not SELF-REAP within 12s after the second project's agent liveness \
         marker went idle too - a genuinely quiet machine's dash must not leak",
    );
}

rigger::test_cases! {
    /// Spec 62, criterion 5 round 2 (adjudication `adj-u62c5-verdict-reject-cross-project-blindness`,
    /// finding `adv-u62c5-agent-liveness-scoped-to-launching-project-only`): the idle judgment must
    /// see a fresh agent-liveness marker on ANY registered project, not only the one whose CWD
    /// happened to launch the machine-wide singleton. This is the CROSS-project sibling of
    /// `a_reap_on_idle_singleton_survives_a_fresh_agent_liveness_marker_after_the_registry_ages_out`
    /// above (same-project): here the fresh marker belongs to a SECOND, entirely different project
    /// (its own root, its own derived scratch path - never `RIGGER_TMPDIR`, which this test reserves
    /// for isolating the LAUNCHING project's own scratch root from the real repo this test binary
    /// runs inside) whose OWN registry entry is written ONCE and never refreshed, so it ages out on
    /// its own past the fast test window - reproducing the adversary's empirical repro (two
    /// registered projects, both registries aged out, one project's own agent-liveness marker still
    /// fresh) as a permanent regression test.
    a_reap_on_idle_singleton_survives_a_second_registered_projects_fresh_agent_liveness_marker:
        assert_a_foreign_projects_fresh_agent_marker_holds_the_reap(false);
    /// Spec 62, criterion 5 round 2 (sdet finding
    /// `sdet-u62c5r2-known-roots-read-all-vs-read-live-untested-at-call-site`, upheld and strengthened
    /// by `adv-u62c5r2-uphold-known-roots-read-all-untested-strengthened-with-repro`): the property
    /// that justifies `registry::read_all` existing as its own function at all. Unlike the sibling
    /// cross-project test above - whose foreign registry entry starts FRESH and only ages out DURING
    /// the test, so both `read_all` and `read_live` would return it on the watcher's very first poll,
    /// leaving the call site's choice between them unobserved - here the foreign project's registry
    /// entry is written with a heartbeat already at the unix epoch: hopelessly stale BEFORE the dash
    /// is even spawned. Were `watch_and_self_reap_on_idle`'s `known_roots` grown from `read_live`'s
    /// pruned result instead of `read_all`'s, this entry would never appear in `live` on ANY poll -
    /// its root would never be learned, `foreign_instance_scratch_root` would never be checked for it,
    /// and the singleton would reap right out from under its own genuinely fresh agent-liveness
    /// marker.
    ///
    /// A THIRD, separate project (`proj-latch`) supplies the `ever_seen_live` startup latch exactly as
    /// the very first sibling test above does for its own project: written once, fresh, and never
    /// refreshed, so it is briefly live on the watcher's earliest polls and then ages out on its own -
    /// isolating the assertion to the SECOND project's agent-liveness signal alone once its registry
    /// entry, too, has gone quiet (`live_instances` reaches zero from BOTH projects, so only
    /// `agent_live` can still be keeping the singleton alive).
    a_reap_on_idle_singleton_survives_a_foreign_agent_liveness_marker_whose_own_registry_entry_was_already_stale_before_the_watchers_first_poll:
        assert_a_foreign_projects_fresh_agent_marker_holds_the_reap(true);
}

/// Spec 62, criterion 5 round 4 (`adv-u62c5r4-known-roots-prune-race-with-instances-provider`):
/// the ACTUAL race the test above cannot see, because it never calls `GET /api/instances` at all.
/// Here an `/api/instances` poll - the most reachable of the three non-watcher registry readers
/// (any open browser tab on the dash landing page) - is fired IMMEDIATELY once the dash is
/// confirmed serving, deliberately racing the self-reap watcher's own first tick (a generous poll
/// interval makes the landing GET win deterministically). Before the fix, that poll's `read_live`
/// would delete the foreign project's hopelessly-stale-from-the-start registry entry from disk
/// before the watcher's OWN `read_all` had ever captured its root into `known_roots` - permanently
/// blinding the singleton to that project's still-fresh agent liveness marker and letting it reap
/// out from under a genuinely live agent. After the fix (`registry::read_live_no_prune`), the
/// landing poll filters the entry out of ITS OWN response without ever deleting it, so the entry
/// survives on disk for the watcher's next `read_all` tick to capture, and the singleton keeps
/// serving for as long as the foreign agent marker stays fresh.
#[test]
fn a_landing_poll_racing_the_watchers_first_tick_does_not_erase_a_foreign_projects_only_route_into_known_roots(
) {
    let (_state, xdg, regdir) = shared_registry();

    // The LAUNCHING project's own scratch root: hermetic and left EMPTY (no marker ever written
    // there), isolating the assertion to the foreign project's marker alone.
    let (_own_scratch, own_scratch_root) = common::fixtures::temp_root();

    // A THIRD project supplies the `ever_seen_live` startup latch (see the test above for why this
    // one-time-write-then-decay shape isolates the assertion to the SECOND project's marker alone).
    let latch_project = tempfile::tempdir().unwrap();
    let latch_root = latch_project.path().to_str().unwrap().to_string();
    write_live_instance(&regdir, "proj-latch", &latch_root);

    // The SECOND, foreign project: hopelessly stale from the moment it is written (heartbeat at the
    // unix epoch), so the very FIRST reader to touch it - this test's own early `/api/instances`
    // poll, below - sees it as stale, exactly the moment the pre-fix `read_live` would have pruned
    // it.
    let (_other_project, other_root, other_marker_path) = foreign_project_marker();
    let other_inst = rigger::registry::Instance {
        project: "proj-b".to_string(),
        root: other_root.clone(),
        store: rigger::registry::StoreIdentity::Local {
            path: format!("{other_root}/.rigger/events.db"),
        },
        heartbeat_ms: 0,
        writer: rigger::registry::Writer::Driver,
    };
    rigger::registry::write(&regdir, &other_inst).expect("write the stale foreign entry");
    let other_entry_path = regdir.join(format!("{}.json", other_inst.id()));

    // The second project's own agent liveness marker starts fresh and is kept fresh by a
    // background thread for the WHOLE test - the live-agent-under-an-already-stale-registry-entry
    // signal this test exists to prove survives the earlier landing-poll race too.
    let heartbeat = Heartbeat::of_marker(other_marker_path);

    // A generous poll interval: the racing `/api/instances` GET below must land well before the
    // watcher's own FIRST tick (`thread::sleep(poll)` then its `read_all`/`read_live` pair), so the
    // race this test exists to win is decided deterministically in the landing poll's favor.
    let dash = WatchedDash::launch(&["--reap-on-idle"], Some(heartbeat), |cmd| {
        cmd.env("XDG_STATE_HOME", &xdg)
            .env("RIGGER_TMPDIR", &own_scratch_root)
            .env("RIGGER_DASH_REAP_POLL_MS", "900")
            .env("RIGGER_DASH_REAP_STALE_SECS", "2")
    });

    // THE RACE: hit `/api/instances` the instant the dash is confirmed serving - long before the
    // watcher's own first `poll` tick (900ms) can fire.
    let landing = http_get_path(dash.port, "/api/instances");
    assert!(
        landing
            .as_deref()
            .is_some_and(|l| l.contains("HTTP/1.1 200")),
        "the dash never served /api/instances: {landing:?}"
    );

    // THE FIX ITSELF: that early landing poll must not have deleted the foreign entry's file - had
    // it, the watcher's own `read_all` tick (still to come) would never learn `proj-b`'s root.
    assert!(
        other_entry_path.exists(),
        "an `/api/instances` poll racing the watcher's first tick deleted the foreign project's \
         registry entry ({other_entry_path:?}) - permanently erasing its only route into \
         `known_roots`"
    );

    // Well past several poll intervals: `proj-latch` has aged out (having satisfied `ever_seen_live`
    // on its early live polls, then dropping `live_instances` back to zero) and `proj-b`'s entry was
    // stale from the start, so registry liveness alone reaches zero. With the marker thread still
    // refreshing `proj-b`'s own agent-liveness marker, the singleton must NOT reap - proving
    // `known_roots` DID learn `proj-b`'s root from the watcher's own `read_all` despite the earlier
    // landing-poll race.
    dash.assert_stays_up_for(
        3500,
        "the singleton self-reaped even though a registered project's own agent liveness \
         marker was still fresh - the earlier `/api/instances` race must not have blinded \
         `known_roots` to that project's root",
    );
    assert!(
        dash.serving(),
        "the singleton must still be genuinely serving, not merely a blocked-but-dead pipe"
    );

    // Now let the foreign project's agent liveness marker go idle too: every signal quiet -> reap.
    dash.assert_self_reaps(
        "the singleton did not SELF-REAP within 12s after the foreign project's agent liveness \
         marker went idle too - a genuinely quiet machine's dash must not leak",
    );
}

/// Spec 50, criterion 5 - the flag GATE through the BUILT binary: a `rigger dash` WITHOUT
/// `--reap-on-idle` starts NO watcher, so it never self-reaps even on a quiet machine with an EMPTY
/// registry. The guard-bound `rigger run` dash relies on this: its `ReapedChild`
/// owns its lifecycle, and a stray watcher exiting out from under it would race that teardown.
#[test]
fn a_dash_without_reap_on_idle_never_self_reaps_on_a_quiet_machine() {
    // An empty registry - the exact machine-idle state that drives the FLAGGED singleton to reap. An
    // unflagged dash must ignore it entirely and keep serving.
    let (_state, xdg, _regdir) = shared_registry();

    // NOTE: no `--reap-on-idle`. A fast poll and a tiny window are set so that IF a watcher ran at
    // all it would reap almost immediately - making the ABSENCE of a reap a strong signal the flag
    // genuinely gates the watcher off.
    let dash = WatchedDash::launch(&[], None, |cmd| {
        cmd.env("XDG_STATE_HOME", &xdg)
            .env("RIGGER_DASH_REAP_POLL_MS", "100")
            .env("RIGGER_DASH_REAP_STALE_SECS", "1")
    });
    assert!(
        dash.serving(),
        "the `rigger dash` (no --reap-on-idle) never served its page"
    );

    // Well past many poll intervals, the unflagged dash must STILL be up: no watcher was ever
    // started, so an empty registry does not make it exit. A read here is a self-reap the flag was
    // supposed to gate off.
    dash.assert_never_self_reaps(
        "a `rigger dash` WITHOUT --reap-on-idle self-reaped on a quiet machine - the flag must gate \
         the watcher so the guard-bound run dash never exits out from under its ReapedChild",
    );
}

/// Spec 50, criterion 5 - the HOMELESS-ENVIRONMENT guard through the BUILT binary: a
/// `rigger dash --reap-on-idle` in an environment with NO resolvable state home (neither
/// `XDG_STATE_HOME` nor `HOME`) has no machine-global instance registry to poll, so the
/// `reap_on_idle.then(registry::default_dir).flatten()` seam yields `None`, starts NO watcher, and
/// the singleton simply SERVES - it never self-reaps. This is the distinct boundary the `.flatten()`
/// guard adds, and it is the one input none of the criterion tests drive: the flag-gate test proves
/// flag-ABSENT, while every serve/reap/survive test runs with a redirected `XDG_STATE_HOME` (a
/// resolvable home), so only THIS test covers flag-PRESENT-but-HOMELESS. A regression that dropped
/// the `.flatten()` (unwrapping the `None` dir) or fell back to a bogus registry dir would either
/// crash the dash or reap it against an empty registry - both caught here, because the tiny poll and
/// 1s window would drive a real watcher to reap almost immediately, so the ABSENCE of a reap is a
/// strong signal the homeless seam gated the watcher off rather than merely a long window.
#[test]
fn a_reap_on_idle_singleton_in_a_homeless_environment_serves_without_a_watcher() {
    // A real repo the dash can serve, created by THIS test (which HAS a home); only the DASH
    // subprocess is made homeless below, so `registry::default_dir` resolves to `None` inside it
    // while the served project is a normal, well-formed run root.
    let proj = temp_git_project_with_commit();
    let root = proj.path();

    // `--reap-on-idle` IS set, but BOTH state-home variables are removed, so the dash's
    // `state_home()` - and thus `default_dir()` - returns `None`: no registry, no watcher. The fast
    // poll and 1s window mean that IF a watcher had started against ANY (necessarily empty) registry
    // it would self-reap within ~1s, so the ABSENCE of a reap is a strong signal the homeless seam
    // gated the watcher off, not that the window was simply too long.
    let dash = WatchedDash::launch(&["--reap-on-idle"], None, |cmd| {
        cmd.current_dir(root)
            .env_remove("XDG_STATE_HOME")
            .env_remove("HOME")
            .env("RIGGER_DASH_REAP_POLL_MS", "100")
            .env("RIGGER_DASH_REAP_STALE_SECS", "1")
    });

    // It genuinely SERVES its read-only page: this proves the homeless startup did not crash (a
    // crash would EOF stdout and masquerade as a reap below).
    assert!(
        dash.serving(),
        "the homeless `rigger dash --reap-on-idle` never served its page"
    );

    // Well past many poll intervals and the 1s window, the dash must STILL be up: with no state home
    // resolvable, `.flatten()` yielded `None` and no watcher was ever started. A read here is a
    // self-reap the homeless guard exists to prevent (an unwrapped `None`, or a bogus-dir fallback
    // reaping against an empty registry), and it fails LOUD.
    dash.assert_never_self_reaps(
        "a `rigger dash --reap-on-idle` in a homeless environment (no XDG_STATE_HOME, no HOME) \
         self-reaped - with no resolvable state home there is no registry to poll, so the \
         `.flatten()` seam must start NO watcher and the singleton must simply serve",
    );
}

/// Spec 50, criterion 5 (spec 62, criterion 5) - the PUBLIC contract of the new decision function
/// at the CRATE BOUNDARY. `dash::should_reap_singleton` is the exported domain core the
/// singleton's watcher polls; the dash.rs unit test proves it white-box (inside the module), and
/// the integration tests above drive it end-to-end through the built binary. This pins its
/// contract at the PUBLIC `rigger::dash` boundary an EXTERNAL caller sees - that the function is
/// exported and its truth table holds - independent of any watcher wiring: reap IFF a live
/// instance has EVER been seen, none remains, AND no agent liveness signal is fresh, so a positive
/// live count never reaps, a not-yet-seen (startup) empty registry keeps serving, and a fresh
/// agent liveness signal keeps serving even once the registry itself has gone quiet.
#[test]
fn should_reap_singleton_public_contract_holds_at_the_crate_boundary() {
    use rigger::dash::should_reap_singleton;

    // Startup guard: no live instance has EVER been seen yet, so keep serving regardless of the
    // current count - a just-ensured singleton must not reap before its ensuring run registers.
    assert!(
        !should_reap_singleton(0, false, false),
        "a never-seen empty registry must keep serving (the startup-race guard)"
    );
    assert!(
        !should_reap_singleton(1, false, false),
        "a positive live count never reaps, whatever the seen flag"
    );

    // A live instance keeps the singleton serving once one has been seen (this project's run or any
    // other's - a positive count means at least one run needs the dash).
    assert!(
        !should_reap_singleton(1, true, false),
        "one live instance keeps the singleton serving"
    );
    assert!(
        !should_reap_singleton(5, true, false),
        "several live instances keep the singleton serving"
    );

    // Machine idle: at least one live instance was seen and none remains live, and no agent
    // liveness signal is fresh -> reap.
    assert!(
        should_reap_singleton(0, true, false),
        "seen-then-empty with no agent signal is a genuinely quiet machine: the singleton reaps"
    );

    // Spec 62 criterion 5's own addition: a fresh agent liveness signal withholds the reap even
    // once the registry has gone quiet - the idle judgment sees the agent, not just the registry.
    assert!(
        !should_reap_singleton(0, true, true),
        "a fresh agent liveness signal keeps the singleton serving even with an aged-out registry"
    );
}

/// Spec 62, criterion 5 - the PUBLIC contract of [`rigger::liveness::any_marker_fresh`] at the
/// CRATE BOUNDARY, mirroring `should_reap_singleton_public_contract_holds_at_the_crate_boundary`
/// above for its sibling new pub fn in this same unit. `crates/rigger-driver/src/liveness.rs`'s own module tests prove
/// the function white-box (inside the module, including its recursive walk and unreadable-entry
/// degrade); `a_reap_on_idle_singleton_survives_a_fresh_agent_liveness_marker_after_the_registry_ages_out`
/// proves it end to end through the real watcher inside the built binary. Neither calls the
/// function directly from OUTSIDE the module the way an external caller does - this test does,
/// pinning that `rigger::liveness::any_marker_fresh` is exported and its truth table holds at the
/// public `rigger::liveness` boundary, independent of any watcher wiring: false for an empty or
/// never-populated scratch root, true for a marker touched within `max_age`, and false once that
/// same marker has aged past it - the exact three-way contract `should_reap_singleton` is wired to
/// consume as its `agent_live` input.
#[test]
fn any_marker_fresh_public_contract_holds_at_the_crate_boundary() {
    use rigger::liveness::{any_marker_fresh, marker_path};
    use std::time::{Duration, SystemTime};

    let bound = Duration::from_secs(900);
    let now = SystemTime::now();

    // A repo-less caller: the same empty-scratch-root degrade every other liveness reader gives,
    // proven here at the public fn itself rather than only via its private helper.
    assert!(
        !any_marker_fresh("", now, bound),
        "an empty scratch root must read as no live agent"
    );

    // A real scratch root that has never had a marker directory created under it: nothing to find.
    let scratch = tempfile::tempdir().unwrap();
    let root = scratch.path().to_str().unwrap();
    assert!(
        !any_marker_fresh(root, now, bound),
        "a scratch root with no agent-live directory must read as no live agent"
    );

    // A marker just written under the SAME nested `<root>/agent-live/<run>/<spawn>` shape
    // `marker_path` builds (the one other public fn this module already exports) is fresh.
    let path = marker_path(root, "run-1", "u1c1/implementer#0").unwrap();
    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
    std::fs::write(&path, b"").unwrap();
    assert!(
        any_marker_fresh(root, now, bound),
        "a just-written marker within max_age must read as a live agent"
    );

    // The same marker, judged from far enough past its real mtime to fall outside a tiny bound,
    // reads as no live agent - the contract `should_reap_singleton`'s idle judgment depends on.
    let far_future = now + Duration::from_secs(3600);
    assert!(
        !any_marker_fresh(root, far_future, Duration::from_secs(1)),
        "a marker older than max_age must not read as a live agent signal"
    );
}

/// Spec 103, THE HALTED-SPAWN CHECKPOINT - the PUBLIC contract of
/// [`rigger::liveness::spawn_is_halted`] at the CRATE BOUNDARY, mirroring
/// `any_marker_fresh_public_contract_holds_at_the_crate_boundary` above for this criterion's own
/// new pub fn. `crates/rigger-driver/src/liveness.rs`'s own module tests prove it white-box, inside the module
/// (including the bounded/unbounded-sibling and same-run-scoping edge cases);
/// `tests/halted_spawn_wip_recovery_periphery.rs` proves the cross-module seam - `conductor.rs`'s
/// `RunCtx::halted_spawn_checkpoint_permitted` calling into it - end to end through the real
/// compiled binary. Neither calls the function directly from OUTSIDE the module the way an
/// external caller does - this test does, pinning that `rigger::liveness::spawn_is_halted` is
/// exported and its three-part truth table (recorded request, no real result, no live sibling)
/// holds at the public `rigger::liveness` boundary, built entirely from the crate's own public
/// `spawn`/`spawn_store`/`eventstore` API - never a crate-internal privilege this external test
/// does not have.
#[test]
fn spawn_is_halted_public_contract_holds_at_the_crate_boundary() {
    use rigger::conductor::STREAM;
    use rigger::eventstore::sqlite::Store;
    use rigger::eventstore::{Direction, EventStore};
    use rigger::liveness::{marker_path, spawn_is_halted};
    use rigger::spawn::{SpawnResult, ROLE_IMPLEMENTER};
    use rigger::spawn_store::{park_in_run, record_result};
    use std::time::SystemTime;

    const RUN_ID: &str = "run-1";
    let scratch = tempfile::tempdir().unwrap();
    let root = scratch.path().to_str().unwrap();
    let store = Store::open(":memory:").unwrap();
    let read = |store: &Store| store.read_stream(STREAM, 0, Direction::Forward).unwrap();

    // A spawn id nobody ever requested: nothing has halted, so the checkpoint must not fire.
    assert!(
        !spawn_is_halted(
            &read(&store),
            root,
            RUN_ID,
            "u",
            "u/implementer#0",
            SystemTime::now()
        )
        .unwrap(),
        "an id with no recorded SpawnRequested must never read as halted"
    );

    // Requested, no result, no marker at all - the classic silent halt.
    let mut named = common::spawn_request("u", "u", ROLE_IMPLEMENTER, 0, "task");
    named.max_wall_clock = Some(300);
    park_in_run(&store, &named, "", "").unwrap();
    assert!(
        spawn_is_halted(
            &read(&store),
            root,
            RUN_ID,
            "u",
            &named.id,
            SystemTime::now()
        )
        .unwrap(),
        "a requested spawn with no result and no live marker must read as halted"
    );

    // The SAME spawn, once it carries a real (non-fault) result: no longer a halt, however
    // dirty the tree it left behind - the exact "reviewer edits above an approved tip" shape
    // spec 103's own problem statement names.
    record_result(&store, &SpawnResult::ok(&named.id, "done")).unwrap();
    assert!(
        !spawn_is_halted(
            &read(&store),
            root,
            RUN_ID,
            "u",
            &named.id,
            SystemTime::now()
        )
        .unwrap(),
        "a spawn that already carries a real result must never read as halted"
    );

    // A DIFFERENT, still-resultless spawn of the same unit, with a SIBLING spawn's own
    // liveness marker fresh right now: the unit has live work in flight, so this one must not
    // read as halted either, even though it individually looks silent.
    let mut other = common::spawn_request("v", "v", ROLE_IMPLEMENTER, 0, "task");
    other.max_wall_clock = Some(300);
    park_in_run(&store, &other, "", "").unwrap();
    let mut sibling = common::spawn_request("v", "v", ROLE_IMPLEMENTER, 1, "task");
    sibling.max_wall_clock = Some(300);
    park_in_run(&store, &sibling, "", "").unwrap();
    let marker = marker_path(root, RUN_ID, &sibling.id).expect("a real spawn id always encodes");
    std::fs::create_dir_all(marker.parent().unwrap()).unwrap();
    std::fs::write(&marker, b"heartbeat").unwrap();
    assert!(
        !spawn_is_halted(
            &read(&store),
            root,
            RUN_ID,
            "v",
            &other.id,
            SystemTime::now()
        )
        .unwrap(),
        "a live sibling spawn of the same unit must suppress the checkpoint for a resultless \
         named spawn"
    );
}

/// Spec 62, criterion 5 round 2 - the PUBLIC contract of [`rigger::registry::read_all`] at the
/// CRATE BOUNDARY, mirroring `any_marker_fresh_public_contract_holds_at_the_crate_boundary` above
/// for this round's new pub fn. `src/registry.rs`'s own module tests prove it white-box (inside
/// the module: a stale entry survives and is never deleted, every root comes back regardless of
/// freshness, an absent directory is an empty registry not an error);
/// `a_reap_on_idle_singleton_survives_a_second_registered_projects_fresh_agent_liveness_marker`
/// proves it end to end through the real watcher inside the built binary. Neither calls the
/// function directly from OUTSIDE the module the way an external caller does - this test does,
/// pinning that `rigger::registry::read_all` is exported and holds the ONE contract
/// `foreign_instance_scratch_root`'s caller depends on that `read_live` does NOT give it: a STALE
/// entry (long past any idle window) comes back too, and comes back UNCHANGED on disk - unlike
/// `read_live`, which would both drop it from the returned set and delete its file.
#[test]
fn read_all_public_contract_holds_at_the_crate_boundary() {
    use rigger::registry::{self, Instance, StoreIdentity};

    let state = tempfile::tempdir().unwrap();
    let regdir = registry::instances_dir(state.path());

    // No `write` has ever touched this directory: an absent registry is empty, not an error.
    assert!(
        registry::read_all(&regdir).is_empty(),
        "an absent instances directory must read as an empty registry, not an error"
    );

    // A hopelessly stale entry - `read_live` would prune this outright (and delete its file).
    let stale = Instance {
        project: "proj-stale".to_string(),
        root: "/stale/root".to_string(),
        store: StoreIdentity::Local {
            path: "/stale/root/.rigger/events.db".to_string(),
        },
        heartbeat_ms: 0,
        writer: rigger::registry::Writer::Driver,
    };
    let stale_path = registry::write(&regdir, &stale).unwrap();

    assert_eq!(
        registry::read_all(&regdir),
        vec![stale.clone()],
        "read_all returns a stale entry verbatim, with no freshness filter"
    );
    assert!(
        stale_path.exists(),
        "read_all must never delete an entry, stale or not - unlike read_live's prune side effect"
    );

    // A second, live entry: read_all returns BOTH, the fresh and the hopelessly stale alike.
    let live = Instance {
        project: "proj-live".to_string(),
        root: "/live/root".to_string(),
        store: StoreIdentity::Local {
            path: "/live/root/.rigger/events.db".to_string(),
        },
        heartbeat_ms: registry::now_ms(),
        writer: rigger::registry::Writer::Driver,
    };
    registry::write(&regdir, &live).unwrap();

    let mut roots: Vec<String> = registry::read_all(&regdir)
        .into_iter()
        .map(|i| i.root)
        .collect();
    roots.sort();
    assert_eq!(
        roots,
        vec!["/live/root".to_string(), "/stale/root".to_string()],
        "read_all returns every registered root regardless of heartbeat freshness"
    );
}

/// Spec 50, criterion 1 end-to-end, through the BUILT binary: `rigger dash` binds a FIXED
/// address and is a SINGLETON. The first invocation binds the (here ephemeral, standing in for
/// the fixed default) address and serves it; a SECOND invocation on that SAME address while the
/// first is still serving does NOT bind a second port and does NOT enter a serve loop - it
/// recognizes the already-serving dash (by the `X-Rigger-Dash` header it probes), reports the
/// EXISTING address, and exits 0. The `dash.rs` unit tests prove `bind_singleton`'s branch
/// decisions in-process; only driving the real binary proves the wiring across two separate
/// `rigger dash` processes: the header recognition over the real socket and the clean exit-0
/// report instead of an `Address already in use` failure.
///
/// The first dash is a real, long-lived process; this test REAPS it before its assertions so a
/// failed assertion never leaks a dashboard.
#[test]
fn dash_is_a_fixed_address_singleton_a_second_invocation_reports_and_exits_clean() {
    use std::io::Read;
    use std::process::Stdio;
    use std::time::{Duration, Instant};

    // A repo-less/empty-store dir is enough: `rigger dash` serves an absent store as an empty
    // run. An ephemeral port stands in for the fixed default so the test never fights a real dash.
    let proj = temp_project();
    let root = proj.path();
    let port = free_loopback_port();
    let url = format!("http://127.0.0.1:{port}/");

    // FIRST dash: bind the address and wait until it genuinely serves its page.
    let mut first = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(root)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn the first `rigger dash`");

    if !matches!(http_get(&url), Some(body) if body.contains("rigger dash")) {
        let _ = first.kill();
        let _ = first.wait();
        panic!("the first `rigger dash` never served its page at {url}");
    }

    // SECOND invocation on the SAME address: it must NOT enter a serve loop (so it exits on its
    // own) and must NOT bind a second port. It reports the existing address and exits 0. Poll
    // `try_wait` on a bounded deadline so a regression that DID enter the serve loop fails LOUD
    // (a hang caught by the deadline) rather than hanging the whole suite.
    let mut second = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(root)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("failed to spawn the second `rigger dash`");

    let deadline = Instant::now() + Duration::from_secs(15);
    let exited = loop {
        match second.try_wait() {
            Ok(Some(status)) => break Some(status),
            Ok(None) if Instant::now() < deadline => std::thread::sleep(Duration::from_millis(50)),
            Ok(None) => break None,
            Err(_) => break None,
        }
    };

    // Collect the second invocation's output (its pipes are at EOF once it has exited).
    let mut out = String::new();
    if let Some(mut so) = second.stdout.take() {
        let _ = so.read_to_string(&mut out);
    }
    let mut err = String::new();
    if let Some(mut se) = second.stderr.take() {
        let _ = se.read_to_string(&mut err);
    }

    // Reap the first (still the ONLY serving process) and, if the second hung, kill it too -
    // BEFORE any assertion, so a failure never leaks a dashboard.
    let _ = first.kill();
    let _ = first.wait();
    if exited.is_none() {
        let _ = second.kill();
        let _ = second.wait();
        panic!(
            "the second `rigger dash` never exited within the deadline - a singleton invocation \
             must recognize the serving dash and NOT enter a serve loop"
        );
    }
    let status = exited.unwrap();

    assert!(
        status.success(),
        "the second `rigger dash` must exit 0 (the singleton is the point), not fail on a port \
         conflict; stdout: {out:?} stderr: {err:?}"
    );
    assert!(
        out.contains(&format!("127.0.0.1:{port}")),
        "the second `rigger dash` must report the EXISTING address ({url}) it found serving; \
         stdout: {out:?} stderr: {err:?}"
    );
}

/// Spec 50, criterion 3 end-to-end, through the BUILT binary: the dash's LANDING view lists every
/// registered instance, and selecting one ATTACHES the run + knowledge-graph views to THAT
/// instance's stores, read-only, through per-request store opens - including an instance with no
/// active run (its graph still serves; its run view degrades to an empty state, never an error).
///
/// Two independent projects register into ONE shared machine-global registry (this criterion
/// CONSUMES the registry criterion 2 owns, so the test writes the entries directly through the
/// registry API rather than driving a run): instance A has an ACTIVE run (a distinctive unit
/// `u-alpha`) and a graph node (`src/alpha.rs`); instance B has NO active run - only a graph node
/// (`src/beta.rs`) folded with an empty run stream. A third, NEUTRAL project is the dash's own cwd,
/// so its default (no-selector) state is empty - proving that what `?instance=` serves comes from
/// the SELECTED instance's stores, not the dash's own project. The dash is a real, long-lived
/// process the test REAPS before its assertions so a failure never leaks a dashboard.
#[test]
fn dash_landing_lists_instances_and_attach_serves_each_instance_store() {
    use rigger::registry;
    use std::process::Stdio;

    // One shared registry both instances register into and the dash discovers.
    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap();
    let regdir = registry::instances_dir(state.path());

    // Instance A: an ACTIVE run (RunStarted + a distinctive unit) plus a knowledge-graph node.
    let a = temp_git_project_with_commit();
    let a_root = a.path();
    seed_run_events(
        a_root,
        &[
            ("RunStarted", r#"{"run_id":"run-a","specs":["s"]}"#),
            (
                "UnitStarted",
                r#"{"id":"u-alpha","spec_criterion":"alpha work"}"#,
            ),
        ],
    );
    // `rigger emit` appends the decision AND folds it into A's graph.db (src/alpha.rs node + edge).
    let (_o, e, ok) = run_rigger(
        a_root,
        &[
            "emit",
            "DecisionMade",
            r#"{"id":"d-alpha","summary":"alpha decision","governs":["src/alpha.rs"]}"#,
        ],
    );
    assert!(ok, "seeding instance A's graph must succeed; stderr: {e}");

    // Instance B: NO active run - a graph node folded over an empty run stream (no RunStarted). Its
    // run view must degrade to empty; its graph must still serve.
    let b = temp_git_project_with_commit();
    let b_root = b.path();
    seed_store(b_root);
    // B governs a file under a DISTINCT top-level dir (`docs/`) so its clustered graph overview is
    // told apart from A's (`src/`) - the whole-graph overview folds nodes by module directory.
    let (_o, e, ok) = run_rigger(
        b_root,
        &[
            "emit",
            "DecisionMade",
            r#"{"id":"d-beta","summary":"beta decision","governs":["docs/beta.md"]}"#,
        ],
    );
    assert!(ok, "seeding instance B's graph must succeed; stderr: {e}");

    // Register both instances directly (criterion 3 consumes the registry; it does not own writes).
    let entry = |root: &Path| registry::Instance {
        project: run_stream_identity(root),
        root: root.to_string_lossy().into_owned(),
        store: registry::StoreIdentity::Local {
            path: root
                .join(".rigger")
                .join("events.db")
                .to_string_lossy()
                .into_owned(),
        },
        heartbeat_ms: registry::now_ms(),
        writer: rigger::registry::Writer::Driver,
    };
    let a_inst = entry(a_root);
    let b_inst = entry(b_root);
    registry::write(&regdir, &a_inst).unwrap();
    registry::write(&regdir, &b_inst).unwrap();
    let a_id = a_inst.id();
    let b_id = b_inst.id();

    // The dash runs in a NEUTRAL project so its own default state is empty - the contrast that
    // proves attach reads the SELECTED store, not the dash's cwd.
    let neutral = temp_project();
    let port = free_loopback_port();
    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(neutral.path())
        .env("XDG_STATE_HOME", xdg)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash`");

    // Drive every read, then REAP the dash before asserting so a failure never leaks a process.
    let landing = http_get_path(port, "/api/instances");
    let default_state = http_get_path(port, "/api/state");
    let a_state = http_get_path(port, &format!("/api/state?instance={a_id}"));
    let b_state = http_get_path(port, &format!("/api/state?instance={b_id}"));
    // Seeded (not the bare overview): spec 63 c3 (FILES-LENS PURITY) excludes any non-code-entity
    // node - including the decision and its governed artifact this fixture seeds - from the DEFAULT
    // overview's clusters entirely, so a bare `/api/graph?instance=` can no longer discriminate A's
    // content from B's. Seeding the decision itself is lens-independent (spec 30's seeded
    // neighborhood is a plain depth-bounded walk, untouched by criterion 3), so it reaches exactly
    // this instance's own decision + its governed artifact and still proves per-instance attach.
    let a_graph = http_get_path(
        port,
        &format!("/api/graph?instance={a_id}&seed=d-alpha&depth=1"),
    );
    let b_graph = http_get_path(
        port,
        &format!("/api/graph?instance={b_id}&seed=d-beta&depth=1"),
    );
    let _ = dash.kill();
    let _ = dash.wait();

    let landing = landing.expect("the dash never served /api/instances");
    let default_state = default_state.expect("the dash never served /api/state");
    let a_state = a_state.expect("the dash never served A's attached state");
    let b_state = b_state.expect("the dash never served B's attached state");
    let a_graph = a_graph.expect("the dash never served A's attached graph");
    let b_graph = b_graph.expect("the dash never served B's attached graph");

    // Clause 1 - the LANDING lists BOTH registered instances, each with its selectable id.
    assert!(
        landing.contains("HTTP/1.1 200"),
        "the landing endpoint answers 200: {landing}"
    );
    for (project, id) in [
        (run_stream_identity(a_root), &a_id),
        (run_stream_identity(b_root), &b_id),
    ] {
        assert!(
            landing.contains(&project) && landing.contains(id.as_str()),
            "the landing must list instance {project} with its attach id {id}; got: {landing}"
        );
    }

    // The dash's OWN default (no selector) state is empty - it has neither A's nor B's content.
    assert!(
        default_state.contains("HTTP/1.1 200") && !default_state.contains("u-alpha"),
        "the neutral-cwd dash's default state carries no attached instance's run: {default_state}"
    );

    // Clause 2 - selecting A serves A's RUN (its unit) and A's GRAPH (its decision's own governed
    // node, `src/alpha.rs`), read-only.
    assert!(
        a_state.contains("HTTP/1.1 200") && a_state.contains("u-alpha"),
        "attaching to A must serve A's own run (unit u-alpha): {a_state}"
    );
    assert!(
        a_graph.contains("HTTP/1.1 200") && a_graph.contains("\"id\":\"src/alpha.rs\""),
        "attaching to A must serve A's own knowledge graph (reaching its governed src/alpha.rs \
         node): {a_graph}"
    );
    // And attach is genuinely per-instance: A's views carry NONE of B's content.
    assert!(
        !a_state.contains("d-beta") && !a_graph.contains("\"id\":\"docs/beta.md\""),
        "A's attached views must not bleed B's content: state={a_state} graph={a_graph}"
    );

    // Clause 3 - an instance with NO active run: its graph still serves (reaching its own governed
    // `docs/beta.md`), and its run view degrades to an EMPTY state (no u-alpha, no error), never a
    // 500.
    assert!(
        b_graph.contains("HTTP/1.1 200") && b_graph.contains("\"id\":\"docs/beta.md\""),
        "attaching to B (no active run) must still serve its knowledge graph: {b_graph}"
    );
    assert!(
        !b_graph.contains("\"id\":\"src/alpha.rs\""),
        "B's attached graph must be B's own, not A's governed src/alpha.rs node: {b_graph}"
    );
    assert!(
        b_state.contains("HTTP/1.1 200")
            && !b_state.contains("HTTP/1.1 500")
            && !b_state.contains("u-alpha"),
        "attaching to B must degrade its empty run to an empty state, never an error: {b_state}"
    );
    // The empty-run view is genuinely empty (no units), proving the empty-state degrade: the
    // `run.units` array serializes empty (`"units":[]`) when no `UnitStarted` was folded.
    let b_body = b_state.split("\r\n\r\n").nth(1).unwrap_or("");
    assert!(
        b_body.contains("\"units\":[]"),
        "B has no active run, so its attached run view has no units: {b_body}"
    );
}

/// Spec 50, criterion 3, the ATTACH RESOLVER's SAFETY branch through the BUILT binary: an
/// UNKNOWN or since-gone `?instance=<id>` selector must degrade to an EMPTY state - NEVER the
/// dash's OWN local run, and never a 500. This is the boundary the happy-path landing test cannot
/// reach: its neutral-cwd dash has no local run, so an unknown selector returning empty is
/// indistinguishable from returning the (already empty) local project. Here the dash HAS a
/// distinctive local run AND a registered live instance also has one, so an unknown selector that
/// returns empty is provably neither - it did not silently fall back to the local project (the
/// bug this guards: a since-gone selection quietly showing the operator's own run under a stale
/// bookmark) and did not attach to some other instance.
///
/// Three-way contrast, all through per-request store opens on ONE long-lived dash process (reaped
/// before the assertions so a failure never leaks a dashboard): with no selector the dash serves
/// its OWN local run (`u-ownrun`, backward compatible); `?instance=<live id>` serves that
/// instance's run (`u-gamma`) and NOT the local run; and `?instance=<bogus>` serves an EMPTY run
/// (a 200 with `"units":[]`, never a 500) that is neither the local run nor the instance's.
#[test]
fn dash_attach_unknown_or_since_gone_instance_serves_empty_not_the_local_run() {
    use rigger::registry;
    use std::process::Stdio;

    // One sandboxed registry both the dash and the registered instance share. Sandboxing
    // `XDG_STATE_HOME` is mandatory: without it the dash reads/writes the operator's REAL
    // machine-global registry, and the test pollutes production state.
    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap();
    let regdir = registry::instances_dir(state.path());

    // The dash's OWN project, with a distinctive LOCAL run so the no-selector default is non-empty
    // - the contrast that makes "unknown selector did NOT show the local run" meaningful.
    let own = temp_git_project_with_commit();
    let own_root = own.path();
    seed_run_events(
        own_root,
        &[
            ("RunStarted", r#"{"run_id":"run-own","specs":["s"]}"#),
            (
                "UnitStarted",
                r#"{"id":"u-ownrun","spec_criterion":"the dash's own local run"}"#,
            ),
        ],
    );

    // A registered LIVE instance with its OWN distinctive run, so a KNOWN selector genuinely
    // attaches away from the local project (sanity that the resolver's live arm still works).
    let gamma = temp_git_project_with_commit();
    let gamma_root = gamma.path();
    seed_run_events(
        gamma_root,
        &[
            ("RunStarted", r#"{"run_id":"run-gamma","specs":["s"]}"#),
            (
                "UnitStarted",
                r#"{"id":"u-gamma","spec_criterion":"the registered instance's run"}"#,
            ),
        ],
    );
    let gamma_inst = registry::Instance {
        project: run_stream_identity(gamma_root),
        root: gamma_root.to_string_lossy().into_owned(),
        store: registry::StoreIdentity::Local {
            path: gamma_root
                .join(".rigger")
                .join("events.db")
                .to_string_lossy()
                .into_owned(),
        },
        heartbeat_ms: registry::now_ms(),
        writer: rigger::registry::Writer::Driver,
    };
    registry::write(&regdir, &gamma_inst).unwrap();
    let gamma_id = gamma_inst.id();

    // The dash serves its OWN project (cwd = own_root); the registry it discovers is the sandbox.
    let port = free_loopback_port();
    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(own_root)
        .env("XDG_STATE_HOME", xdg)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash`");

    let default_state = http_get_path(port, "/api/state");
    let gamma_state = http_get_path(port, &format!("/api/state?instance={gamma_id}"));
    // A selector that never named a registry entry - the since-gone / stale-bookmark case.
    let bogus_state = http_get_path(port, "/api/state?instance=this-id-was-never-registered");
    let _ = dash.kill();
    let _ = dash.wait();

    let default_state = default_state.expect("the dash never served /api/state");
    let gamma_state = gamma_state.expect("the dash never served the attached state");
    let bogus_state = bogus_state.expect("the dash never served the unknown-selector state");

    // No selector -> the dash's OWN local run (backward compatible).
    assert!(
        default_state.contains("HTTP/1.1 200") && default_state.contains("u-ownrun"),
        "with no selector the dash serves its own local run: {default_state}"
    );

    // A KNOWN selector attaches to THAT instance's run, and away from the local project.
    assert!(
        gamma_state.contains("HTTP/1.1 200")
            && gamma_state.contains("u-gamma")
            && !gamma_state.contains("u-ownrun"),
        "a known selector serves the instance's run, not the dash's local one: {gamma_state}"
    );

    // The SAFETY boundary: an unknown / since-gone selector degrades to an EMPTY run - it is
    // NEITHER the dash's local run NOR the registered instance's, and it is a 200 with no units,
    // never a 500 and never a silent fall-back to the local project.
    assert!(
        bogus_state.contains("HTTP/1.1 200") && !bogus_state.contains("HTTP/1.1 500"),
        "an unknown selector degrades to an empty state, never an error: {bogus_state}"
    );
    assert!(
        !bogus_state.contains("u-ownrun"),
        "an unknown selector must NOT silently show the dash's own local run: {bogus_state}"
    );
    assert!(
        !bogus_state.contains("u-gamma"),
        "an unknown selector must not leak an unrelated instance's run: {bogus_state}"
    );
    let bogus_body = bogus_state.split("\r\n\r\n").nth(1).unwrap_or("");
    assert!(
        bogus_body.contains("\"units\":[]"),
        "the unknown-selector run view is genuinely empty (no units): {bogus_body}"
    );
}

/// Spec 50, criterion 3, the STALE-FILTER reaching the periphery AND the landing's WIRE CONTRACT,
/// through the BUILT binary - spec 62 criterion 5 round 4
/// (`adv-u62c5r4-known-roots-prune-race-with-instances-provider`): `registry::read_live_no_prune`
/// FILTERS OUT any entry whose heartbeat has gone stale past the idle window WITHOUT deleting it,
/// and BOTH the `/api/instances` landing provider and the attach resolver consume it - so a stale
/// (dead) instance must not appear in the landing, and selecting a stale id must degrade to empty,
/// while its registry FILE must survive on disk for the self-reap watcher's own `read_all` tick to
/// still find (deletion is reserved exclusively to that watcher's own `read_live` tick, never to
/// an unsynchronized per-request reader like this landing poll). The happy-path test registers only
/// fresh entries, so neither the filter nor the exact serialized field names the page's JS reads
/// are exercised here.
///
/// A LIVE instance (fresh heartbeat) and a STALE one (heartbeat well past `DEFAULT_IDLE_MS`) are
/// registered into one sandboxed registry. On the built dash, `/api/instances` lists the LIVE
/// instance and NOT the stale one (filtered out, but its file left on disk) and carries every one
/// of the six `InstanceView` wire keys the landing page reads; and `?instance=<stale id>` degrades
/// to an empty run (the stale entry was filtered out before resolve, never deleted).
#[test]
fn dash_landing_filters_stale_instances_without_pruning_and_pins_the_wire_contract() {
    use rigger::registry;
    use std::process::Stdio;

    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap();
    let regdir = registry::instances_dir(state.path());

    let now = registry::now_ms();
    let live_root = temp_git_project_with_commit();
    let stale_root = temp_git_project_with_commit();
    let mk = |root: &Path, hb: u64| registry::Instance {
        project: run_stream_identity(root),
        root: root.to_string_lossy().into_owned(),
        store: registry::StoreIdentity::Local {
            path: root
                .join(".rigger")
                .join("events.db")
                .to_string_lossy()
                .into_owned(),
        },
        heartbeat_ms: hb,
        writer: rigger::registry::Writer::Driver,
    };
    // Live: heartbeat now. Stale: a full idle window plus a minute in the past, so `is_stale`
    // is unambiguously true regardless of the small drift between this stamp and the dash's read.
    let live_inst = mk(live_root.path(), now);
    let stale_inst = mk(stale_root.path(), now - registry::DEFAULT_IDLE_MS - 60_000);
    registry::write(&regdir, &live_inst).unwrap();
    registry::write(&regdir, &stale_inst).unwrap();
    let live_project = run_stream_identity(live_root.path());
    let stale_project = run_stream_identity(stale_root.path());
    let live_id = live_inst.id();
    let stale_id = stale_inst.id();

    let neutral = temp_project();
    let port = free_loopback_port();
    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(neutral.path())
        .env("XDG_STATE_HOME", xdg)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash`");

    let landing = http_get_path(port, "/api/instances");
    let stale_state = http_get_path(port, &format!("/api/state?instance={stale_id}"));
    let _ = dash.kill();
    let _ = dash.wait();

    let landing = landing.expect("the dash never served /api/instances");
    let stale_state = stale_state.expect("the dash never served the stale-selector state");

    assert!(
        landing.contains("HTTP/1.1 200"),
        "the landing endpoint answers 200: {landing}"
    );
    // The LIVE instance is listed with its attach id; the STALE one is filtered out, absent from
    // both the landing's project labels and its selectable ids.
    assert!(
        landing.contains(&live_project) && landing.contains(live_id.as_str()),
        "the landing lists the live instance {live_project} with its attach id: {landing}"
    );
    assert!(
        !landing.contains(&stale_project) && !landing.contains(stale_id.as_str()),
        "a stale instance is filtered from the landing, never shown as attachable: {landing}"
    );
    // THE ROUND-4 FIX ITSELF: the stale instance's registry FILE must still be on disk after this
    // `/api/instances` poll - `read_live_no_prune` filters it out of the response without ever
    // deleting it. A per-request landing poll deleting a foreign project's entry is exactly the
    // race `adv-u62c5r4-known-roots-prune-race-with-instances-provider` found: it could win against
    // the self-reap watcher's own `read_all` tick and permanently erase the only place that
    // project's root is ever learned from.
    let stale_entry_path = regdir.join(format!("{stale_id}.json"));
    assert!(
        stale_entry_path.exists(),
        "a `/api/instances` poll must never delete a stale registry entry's file from disk - \
         deletion is reserved to the self-reap watcher's own tick: {stale_entry_path:?}"
    );

    // The WIRE CONTRACT: the landing body carries every field name the page's JS reads to label
    // and select a row. A rename would silently break the picker; pin all six here.
    let landing_body = landing.split("\r\n\r\n").nth(1).unwrap_or("");
    for key in [
        "\"instances\"",
        "\"id\"",
        "\"project\"",
        "\"root\"",
        "\"kind\"",
        "\"store\"",
        "\"age_secs\"",
    ] {
        assert!(
            landing_body.contains(key),
            "the landing wire contract must carry {key}: {landing_body}"
        );
    }

    // Selecting the stale id resolves against a registry read that filters it out (never deletes
    // it), so it degrades to an empty run (a 200 with no units), never the stale instance's
    // content and never a 500.
    assert!(
        stale_state.contains("HTTP/1.1 200") && !stale_state.contains("HTTP/1.1 500"),
        "a stale selector degrades to an empty state, never an error: {stale_state}"
    );
    let stale_body = stale_state.split("\r\n\r\n").nth(1).unwrap_or("");
    assert!(
        stale_body.contains("\"units\":[]"),
        "the stale-selector run view is genuinely empty (no units): {stale_body}"
    );
}

/// Spec 50, criterion 3, the READ-ONLY GLOBAL CONSTRAINT through the BUILT binary: attaching to a
/// SHARED instance whose own `.rigger` no longer resolves a server (a SQLITE DEGRADE) must NOT
/// create a store file under that instance's project. A dash attach is a read-only projection, and
/// `Store::open` CREATES `events.db` AND its schema - so the Shared arm must guard existence exactly
/// like the Local arm rather than open-creating a phantom store under a foreign root
/// (adv-u50c3-shared-attach-creates-phantom-store). This is the CREATION angle - the testable, and
/// gating, sibling of the env-precedence finding: the Shared arm resolves through the ATTACHED
/// instance's own config with NO ambient environment, so the dash process's `KURRENTDB_CONN` can
/// neither redirect a foreign read nor (its write-path sibling) open-create a store here.
///
/// The instance's `.rigger` exists (as it does for any real instance) but carries no store config
/// and no `events.db`, so its own resolution degrades to the sqlite default; the dash runs with
/// `KURRENTDB_CONN` REMOVED so the pre-fix Shared arm's `env_conn()` rung is also empty and it
/// reaches the exact `Store::open` that wrote the phantom file. After one attach GET, the file must
/// still be absent.
#[test]
fn dash_attach_to_shared_instance_never_creates_a_store_under_its_root() {
    use rigger::registry;
    use std::process::Stdio;

    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap();
    let regdir = registry::instances_dir(state.path());

    // A SHARED-registered instance whose `.rigger` exists (the registry/graph live there for any
    // real instance) but carries NO store config (`store.conn`/`workflow.yml`) and NO `events.db`,
    // so its OWN store resolution degrades to the sqlite default.
    let shared_root = temp_git_project_with_commit();
    let rigger_dir = shared_root.path().join(".rigger");
    std::fs::create_dir_all(&rigger_dir).unwrap();
    let events_db = rigger_dir.join("events.db");
    assert!(
        !events_db.exists(),
        "precondition: the shared instance starts with no events.db"
    );

    let inst = registry::Instance {
        project: run_stream_identity(shared_root.path()),
        root: shared_root.path().to_string_lossy().into_owned(),
        store: registry::StoreIdentity::Shared {
            endpoint: "kurrentdb://localhost:2113".to_string(),
        },
        heartbeat_ms: registry::now_ms(),
        writer: rigger::registry::Writer::Driver,
    };
    registry::write(&regdir, &inst).unwrap();
    let id = inst.id();

    let neutral = temp_project();
    let port = free_loopback_port();
    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(neutral.path())
        .env("XDG_STATE_HOME", xdg)
        // No ambient server address: the Shared arm degrades to sqlite (rung 5) and MUST hit the
        // existence guard - never resolve the dash's own `KURRENTDB_CONN` for a foreign instance.
        .env_remove("KURRENTDB_CONN")
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash`");

    let attached = http_get_path(port, &format!("/api/state?instance={id}"));
    let _ = dash.kill();
    let _ = dash.wait();

    let attached = attached.expect("the dash never served the shared-attached state");
    // The attach degrades to an EMPTY run - a 200, never a 500 - because the store is absent.
    assert!(
        attached.contains("HTTP/1.1 200") && !attached.contains("HTTP/1.1 500"),
        "attaching to a store-less shared instance degrades to an empty state, never an error: {attached}"
    );
    let body = attached.split("\r\n\r\n").nth(1).unwrap_or("");
    assert!(
        body.contains("\"units\":[]"),
        "the shared-attach run view is genuinely empty (no units): {body}"
    );
    // THE CONSTRAINT: a read-only attach created NO store file under the instance's root. The
    // pre-fix Shared arm called `Store::open` on the sqlite degrade, writing this phantom events.db.
    assert!(
        !events_db.exists(),
        "a read-only dash attach must never create a store under a foreign project, but {} was created",
        events_db.display()
    );
}

/// Spec 50, criterion 3, the ENV-PRECEDENCE branch of the Shared attach arm through the BUILT
/// binary (adv-u50c3-uphold-sdet-env-precedence): the dash process's OWN `KURRENTDB_CONN`
/// addresses a DIFFERENT project's store, so when it attaches to a registered SHARED instance the
/// ATTACHED instance's own `.rigger` config - never the dash's ambient environment - is
/// authoritative for the read. The Shared arm proves this by resolving through
/// `store_selection_at(None, ..)`: passing `None` for env instead of `env_conn()`, so the dash's
/// `KURRENTDB_CONN` can NOT win the precedence and redirect the foreign read to the wrong store.
///
/// The sibling no-phantom-store test cannot reach THIS boundary: it REMOVES `KURRENTDB_CONN`, so a
/// regression that swapped `None` back to `env_conn()` would stay green there (an empty env resolves
/// to the same sqlite degrade). Here the env is SET and the instance's own store is POPULATED, so
/// the two behaviors DIVERGE observably: the correct `None` path reads the instance's own sqlite
/// (its distinctive run shows through), while an `env_conn()` regression would resolve the dash's
/// `KURRENTDB_CONN` server, fail to reach it, and degrade to an EMPTY run - the instance's own run
/// would vanish. Asserting the instance's own unit shows through is therefore RED exactly on the
/// env-redirect regression and GREEN on the shipped env-agnostic read.
#[test]
fn dash_attach_to_shared_instance_reads_its_own_store_not_the_dash_process_kurrentdb_conn() {
    use rigger::registry;
    use std::process::Stdio;

    let state = tempfile::tempdir().unwrap();
    let xdg = state.path().to_str().unwrap();
    let regdir = registry::instances_dir(state.path());

    // A SHARED-registered instance whose `.rigger` carries NO store config (so its OWN resolution
    // degrades to the sqlite default) but DOES have a POPULATED `events.db` - a distinctive run
    // (unit `u-envprec`) seeded into its own local sqlite exactly as the compiled binary reads it
    // back. This is the Shared-arm Sqlite DEGRADE with real content to read.
    let shared_root = temp_git_project_with_commit();
    seed_run_events(
        shared_root.path(),
        &[
            ("RunStarted", r#"{"run_id":"run-envprec","specs":["s"]}"#),
            (
                "UnitStarted",
                r#"{"id":"u-envprec","spec_criterion":"env precedence work"}"#,
            ),
        ],
    );

    let inst = registry::Instance {
        project: run_stream_identity(shared_root.path()),
        root: shared_root.path().to_string_lossy().into_owned(),
        store: registry::StoreIdentity::Shared {
            endpoint: "kurrentdb://localhost:2113".to_string(),
        },
        heartbeat_ms: registry::now_ms(),
        writer: rigger::registry::Writer::Driver,
    };
    registry::write(&regdir, &inst).unwrap();
    let id = inst.id();

    // The dash process's OWN ambient server address - a well-formed but UNREACHABLE endpoint (a
    // free loopback port nothing listens on, so a connection is refused fast). If the Shared arm
    // wrongly resolved THIS `env_conn()` for the foreign instance it would select the server, fail
    // to reach it, and the attached run would come back empty. The shipped arm ignores it.
    let dead_port = free_loopback_port();
    let dead_conn = format!("kurrentdb://127.0.0.1:{dead_port}");

    let neutral = temp_project();
    let port = free_loopback_port();
    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(neutral.path())
        .env("XDG_STATE_HOME", xdg)
        // The dash process HOLDS a `KURRENTDB_CONN`, pointed at a store that is NOT this instance's.
        // The attach must ignore it and read the instance's OWN sqlite (rungs 3-5 at the instance's
        // `.rigger`), never let the dash env (rung 2) redirect the foreign read.
        .env("KURRENTDB_CONN", &dead_conn)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash`");

    let attached = http_get_path(port, &format!("/api/state?instance={id}"));
    let _ = dash.kill();
    let _ = dash.wait();

    let attached = attached.expect("the dash never served the shared-attached state");
    // A 200 (never a 500): the read is best-effort and the instance's own sqlite is present.
    assert!(
        attached.contains("HTTP/1.1 200") && !attached.contains("HTTP/1.1 500"),
        "attaching to the shared instance answers 200 from its own store: {attached}"
    );
    // THE CONSTRAINT: the attach served the ATTACHED INSTANCE's OWN run (unit `u-envprec`), proving
    // the read went through the instance's `.rigger` and the dash process's `KURRENTDB_CONN` did NOT
    // redirect it. A regression to `env_conn()` would resolve the dead server and serve an empty run.
    assert!(
        attached.contains("u-envprec"),
        "the shared attach must read the instance's OWN store (its run unit u-envprec), never the \
         dash process's KURRENTDB_CONN: {attached}"
    );
}

/// Spec 50, criterion 1, the CONFLICT branch through the BUILT binary: when the dash's requested
/// address is held by an UNRELATED (non-dash) process, `rigger dash --port <held>` must FAIL
/// LOUD - it surfaces the address-in-use conflict and exits NON-ZERO, the deliberate opposite of
/// the retired free-port search. It must NEVER drift to another port and NEVER mistake the holder
/// for a serving singleton (no "already serving" defer): only a genuine rigger dash, recognized
/// by its `X-Rigger-Dash` header, earns the clean exit-0 defer the sibling singleton test covers.
/// This is the negative half of the fixed-address policy - the address in, or a loud conflict,
/// never a silent drift - which the singleton (success) test cannot reach. Bounded so a
/// regression that DID drift-and-serve fails LOUD (a caught hang) instead of wedging the suite.
#[test]
fn dash_on_a_port_held_by_a_non_dash_process_fails_loud_and_never_drifts() {
    use std::io::Read;
    use std::process::Stdio;
    use std::time::{Duration, Instant};

    let proj = temp_project();
    let root = proj.path();

    // Hold the port with a plain listener that is NOT a dash and answers no probe - any unrelated
    // process squatting the address. Keeping the bound listener in scope holds the port for the
    // whole `rigger dash` run; the singleton probe connects into its backlog, reads nothing, and
    // times out - so the holder is correctly NOT recognized as a dash.
    let holder = reserved_loopback_listener();
    let port = holder.local_addr().unwrap().port();

    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(root)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("failed to spawn `rigger dash` against a held port");

    // The conflict path exits immediately; poll `try_wait` on a bounded deadline so a regression
    // that drifted to a free port and entered the serve loop is caught LOUD (as a hang past the
    // deadline) rather than blocking the whole suite forever.
    let deadline = Instant::now() + Duration::from_secs(15);
    let exited = loop {
        match dash.try_wait() {
            Ok(Some(status)) => break Some(status),
            Ok(None) if Instant::now() < deadline => std::thread::sleep(Duration::from_millis(50)),
            Ok(None) => break None,
            Err(_) => break None,
        }
    };

    let mut out = String::new();
    if let Some(mut so) = dash.stdout.take() {
        let _ = so.read_to_string(&mut out);
    }
    let mut err = String::new();
    if let Some(mut se) = dash.stderr.take() {
        let _ = se.read_to_string(&mut err);
    }

    if exited.is_none() {
        let _ = dash.kill();
        let _ = dash.wait();
        panic!(
            "`rigger dash` never exited on a conflicting port - a non-dash holder must be a LOUD \
             conflict, never a drift-and-serve; stdout: {out:?} stderr: {err:?}"
        );
    }
    let status = exited.unwrap();

    assert!(
        !status.success(),
        "`rigger dash` on a port held by a non-dash process must FAIL (non-zero), never drift or \
         defer; stdout: {out:?} stderr: {err:?}"
    );
    assert!(
        err.to_lowercase().contains("in use"),
        "the conflict must surface as an address-in-use error on stderr; stdout: {out:?} \
         stderr: {err:?}"
    );
    assert!(
        !out.contains("serving on") && !out.contains("already serving"),
        "a non-dash holder must NOT be reported as a serving/already-serving dash (no false \
         singleton defer, no drift to another port); stdout: {out:?} stderr: {err:?}"
    );

    drop(holder);
}

/// Spec 50, criterion 1, the SINGLETON under CONCURRENCY: with one genuine `rigger dash` already
/// serving the fixed address, MANY claimants racing that SAME address at once must EACH defer
/// cleanly - `bind_singleton` returns `AlreadyServing` for every one of them, never a second
/// `Bound` and never a spurious conflict error. The unit and CLI tests each serialize a SINGLE
/// claimant behind a fully-served winner; only racing N claimants simultaneously proves the
/// singleton holds under the real contention it exists to resolve (a manual `rigger dash` while
/// the step path is also ensuring one, or two runs starting together). Driving the public
/// `bind_singleton` API from the integration crate against a real serving process is the
/// outside-in view the in-crate single-threaded unit tests are structurally blind to.
#[test]
fn many_claimants_racing_a_live_serving_singleton_all_defer_cleanly() {
    use rigger::dash::{bind_singleton, SingletonBind};
    use std::net::SocketAddr;
    use std::process::Stdio;
    use std::sync::{Arc, Barrier};

    let proj = temp_project();
    let root = proj.path();
    let port = free_loopback_port();
    let addr = SocketAddr::from(([127, 0, 0, 1], port));
    let url = format!("http://127.0.0.1:{port}/");

    // The WINNER: a real, serving `rigger dash` process holding the address.
    let mut winner = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(root)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn the serving `rigger dash`");

    if !matches!(http_get(&url), Some(body) if body.contains("rigger dash")) {
        let _ = winner.kill();
        let _ = winner.wait();
        panic!("the serving `rigger dash` never came up at {url}");
    }

    // N claimants race the SAME address concurrently; a start barrier maximizes the overlap so
    // they genuinely contend rather than run one-after-another.
    let n = 8usize;
    let barrier = Arc::new(Barrier::new(n));
    let mut handles = Vec::with_capacity(n);
    for _ in 0..n {
        let b = barrier.clone();
        handles.push(std::thread::spawn(move || {
            b.wait();
            bind_singleton(addr)
        }));
    }
    let results: Vec<_> = handles.into_iter().map(|h| h.join().unwrap()).collect();

    // Reap the winner (the only serving process) BEFORE asserting so a failure never leaks a dash.
    let _ = winner.kill();
    let _ = winner.wait();

    for (i, r) in results.iter().enumerate() {
        match r {
            Ok(SingletonBind::AlreadyServing(reported)) => assert_eq!(
                *reported, addr,
                "claimant {i} must defer to the fixed address the singleton serves, not a drifted one"
            ),
            other => panic!(
                "claimant {i} racing a live serving singleton must defer (AlreadyServing), never \
                 bind a second port or error; got {other:?}"
            ),
        }
    }
}

/// Race `CLAIMANTS` claimants for one loopback port from `next_port` at once, until a round in
/// which one of them binds it; returns that round's port and every claimant's result.
///
/// The port is probed free, released, and only then raced for, so another process on the machine
/// can bind it in between. A round in which no claimant binds and each found the port held (the
/// raw conflict, or a dash already serving it) is that theft: it says nothing about the singleton,
/// so the race re-runs on a fresh port, a bounded number of times, and fails loudly past the
/// bound. Every result of a round is collected before any is dropped, so a winner holds the
/// address for its whole round.
fn race_for_a_port_nobody_else_holds(
    mut next_port: impl FnMut() -> u16,
) -> (u16, Vec<std::io::Result<rigger::dash::SingletonBind>>) {
    use rigger::dash::{bind_singleton, SingletonBind};
    use std::net::SocketAddr;
    use std::sync::{Arc, Barrier};

    const CLAIMANTS: usize = 8;
    const ROUNDS: usize = 5;
    for _ in 0..ROUNDS {
        let port = next_port();
        let addr = SocketAddr::from(([127, 0, 0, 1], port));
        let barrier = Arc::new(Barrier::new(CLAIMANTS));
        let handles: Vec<_> = (0..CLAIMANTS)
            .map(|_| {
                let b = barrier.clone();
                std::thread::spawn(move || {
                    b.wait();
                    bind_singleton(addr)
                })
            })
            .collect();
        let results: Vec<_> = handles.into_iter().map(|h| h.join().unwrap()).collect();
        let taken_before_the_race = results.iter().all(|r| match r {
            Ok(SingletonBind::Bound(_)) => false,
            Ok(SingletonBind::AlreadyServing(_)) => true,
            Err(e) => e.kind() == std::io::ErrorKind::AddrInUse,
        });
        if !taken_before_the_race {
            return (port, results);
        }
    }
    panic!(
        "another process took each of {ROUNDS} freshly probed loopback ports before the \
         claimants reached it - no round could race for a free port"
    );
}

/// Spec 50, criterion 1, the ATOMIC single-winner guarantee: when MANY claimants race the SAME
/// (initially free) address at once, EXACTLY ONE binds it and NO OTHER ever becomes a second
/// `Bound` - the singleton is atomic, not a check-then-bind two racers could both pass. Because
/// `bind_singleton` never searches upward, a loser never drifts to a different port; it either
/// recognizes an already-serving dash or surfaces the conflict, but it is NEVER a second holder
/// of the address. This is the cold-race complement to the live-serving defer test, and the
/// concurrency dimension the serialized unit tests cannot reach.
#[test]
fn a_concurrent_cold_race_yields_exactly_one_binder_never_two() {
    use rigger::dash::SingletonBind;

    let (port, results) = race_for_a_port_nobody_else_holds(free_loopback_port);
    let mut bound = 0usize;
    for r in &results {
        match r {
            Ok(SingletonBind::Bound(listener)) => {
                bound += 1;
                assert_eq!(
                    listener.local_addr().unwrap().port(),
                    port,
                    "the single winner must bind the EXACT raced address, never a drifted one"
                );
            }
            // A loser: it either recognized a serving dash or saw the raw conflict. Both are valid
            // loser outcomes; the one thing forbidden - a second `Bound`, or a `Bound` on a
            // drifted port - is caught by the count below and the port assertion above.
            Ok(SingletonBind::AlreadyServing(_)) | Err(_) => {}
        }
    }
    assert_eq!(
        bound, 1,
        "a concurrent race for one free address must produce EXACTLY ONE binder (the singleton is \
         atomic); got {bound}. results: {results:?}"
    );
}

/// A race whose port another process took after it was probed free is not judged: the race
/// re-runs on a fresh port, so a stolen port can never read as a broken singleton.
#[test]
fn a_cold_race_for_a_port_taken_after_its_probe_re_races_on_a_fresh_port() {
    use rigger::dash::SingletonBind;

    let thief = reserved_loopback_listener();
    let stolen = thief.local_addr().unwrap().port();
    let mut ports = vec![free_loopback_port(), stolen];
    let (port, results) = race_for_a_port_nobody_else_holds(|| ports.pop().unwrap());
    assert_ne!(
        port, stolen,
        "the stolen port's round must not be the one judged"
    );
    let bound = results
        .iter()
        .filter(|r| matches!(r, Ok(SingletonBind::Bound(_))))
        .count();
    assert_eq!(bound, 1, "the fresh port's round is judged: {results:?}");
}

/// Spec 50, criterion 1, the RECOGNITION CONTRACT through the BUILT binary: every `rigger dash`
/// response carries the `X-Rigger-Dash` header whose NAME is the public `dash::DASH_HEADER`
/// constant the singleton probe looks for. That header IS the mechanism by which a second
/// invocation's `dash_serving_on` probe recognizes an already-serving dash and defers cleanly -
/// the sibling singleton test proves the deferral only by CONSEQUENCE. Asserting the header
/// DIRECTLY on a real response localizes a regression: a dropped or renamed header would
/// otherwise surface only as a confusing "the second invocation refused to defer" failure
/// elsewhere. The header rides the root page every dash already serves, so the dash stays
/// read-only and gains no endpoint. The dash is a real, long-lived process; it is reaped BEFORE
/// the assertion so a failed assertion never leaks a dashboard.
#[test]
fn every_dash_response_carries_the_rigger_dash_recognition_header() {
    use std::io::{Read, Write};
    use std::process::Stdio;
    use std::time::{Duration, Instant};

    let proj = temp_project();
    let root = proj.path();
    let port = free_loopback_port();
    let url = format!("http://127.0.0.1:{port}/");

    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(root)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("failed to spawn `rigger dash`");

    // Wait until the dash genuinely serves its page (the body helper polls the startup window).
    if !matches!(http_get(&url), Some(body) if body.contains("rigger dash")) {
        let _ = dash.kill();
        let _ = dash.wait();
        panic!("`rigger dash` never served its page at {url}");
    }

    // A raw GET that keeps the RESPONSE HEAD (`http_get` strips it): read the status line +
    // headers so the recognition header can be asserted directly.
    let hostport = format!("127.0.0.1:{port}");
    let head = {
        let deadline = Instant::now() + Duration::from_secs(15);
        let mut stream = loop {
            match std::net::TcpStream::connect(&hostport) {
                Ok(s) => break s,
                Err(_) if Instant::now() < deadline => {
                    std::thread::sleep(Duration::from_millis(50))
                }
                Err(_) => {
                    let _ = dash.kill();
                    let _ = dash.wait();
                    panic!("could not connect to the serving dash at {url}");
                }
            }
        };
        let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
        if stream
            .write_all(b"GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n")
            .is_err()
        {
            let _ = dash.kill();
            let _ = dash.wait();
            panic!("could not write the probe request to the serving dash at {url}");
        }
        let mut resp = String::new();
        let _ = stream.read_to_string(&mut resp);
        // Keep only the head (status line + headers) up to the blank end-of-headers line.
        let end = resp.find("\r\n\r\n").unwrap_or(resp.len());
        resp[..end].to_string()
    };

    // Reap the dash (the ONLY serving process) BEFORE asserting so a failure never leaks it.
    let _ = dash.kill();
    let _ = dash.wait();

    // The recognition contract: a header line whose NAME (case-insensitively) is the public
    // `DASH_HEADER` constant. Line-anchored - the same discipline `dash_serving_on` uses - so the
    // marker cannot be satisfied by the same text appearing inside another header's value.
    let needle = format!("{}:", rigger::dash::DASH_HEADER).to_ascii_lowercase();
    let carries = head
        .lines()
        .any(|line| line.to_ascii_lowercase().starts_with(&needle));
    assert!(
        carries,
        "every dash response must carry the `{}` recognition header the singleton probe looks \
         for; response head was:\n{head}",
        rigger::dash::DASH_HEADER
    );
}

/// Spec 50, criterion 1, the singleton probe's BOUNDEDNESS end-to-end through the BUILT binary:
/// when the fixed address is squatted by a HOSTILE holder that ACCEPTS the probe connection and
/// then DRIBBLES bytes forever - one byte slower than any per-read timeout, NEVER a newline -
/// `rigger dash` must still terminate on a HARD bound and surface the address-in-use conflict,
/// never hang. The `dash.rs` unit test proves `dash_serving_on` itself is bounded in-process;
/// only driving the whole binary proves the FULL `cmd_dash -> bind_singleton -> dash_serving_on`
/// chain stays bounded in the shipped path - the outside-in view the single-process unit test is
/// structurally blind to. It guards exactly the boundary the whole-head-read bound hardens: a
/// regression to a per-read-only timeout would reset forever on the dribble and spin, so this
/// test's bounded `try_wait` deadline turns that regression into a LOUD caught hang, never a
/// silent wedge. The sibling non-dash-holder test drives a SILENT holder (bounded by the read
/// timeout); this drives an ACTIVE dribbler (bounded only by the overall head-read deadline).
#[test]
fn the_dash_singleton_probe_stays_bounded_against_a_dribbling_holder() {
    use std::io::{Read, Write};
    use std::process::Stdio;
    use std::time::{Duration, Instant};

    let proj = temp_project();
    let root = proj.path();

    // Bind the port and hold it for the whole run, so `rigger dash`'s bind is a genuine conflict.
    let holder = reserved_loopback_listener();
    let port = holder.local_addr().unwrap().port();

    // A worker that ACCEPTS the one singleton-probe connection (bounded so it never blocks
    // forever) and then dribbles a single byte every 120ms with NO newline - defeating any
    // per-read-only timeout so ONLY a bound on the TOTAL head-read can stop the probe. It never
    // sends the recognition header, so it must be treated as a conflict, never a serving dash.
    let dribbler = std::thread::spawn(move || {
        holder
            .set_nonblocking(true)
            .expect("make the holder non-blocking");
        let accept_deadline = Instant::now() + Duration::from_secs(20);
        let sock = loop {
            match holder.accept() {
                Ok((s, _)) => break Some(s),
                Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                    if Instant::now() >= accept_deadline {
                        break None;
                    }
                    std::thread::sleep(Duration::from_millis(20));
                }
                Err(_) => break None,
            }
        };
        if let Some(mut s) = sock {
            let _ = s.set_nonblocking(false);
            // Drain whatever the probe wrote (best-effort) so a full receive buffer never stalls
            // it, then dribble until the probe gives up (its bounded read returns and it drops the
            // stream, so the next write fails).
            let _ = s.set_read_timeout(Some(Duration::from_millis(50)));
            let mut scratch = [0u8; 256];
            let _ = s.read(&mut scratch);
            while s.write_all(b"X").is_ok() && s.flush().is_ok() {
                std::thread::sleep(Duration::from_millis(120));
            }
        }
        // `holder` drops here, releasing the port - only after the probe has already concluded.
    });

    let mut dash = common::rigger_courier()
        .args(["dash", "--port", &port.to_string()])
        .current_dir(root)
        .env_remove("RIGGER_NO_DASH")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("failed to spawn `rigger dash` against a dribbling holder");

    // A bounded probe exits in ~1s; poll `try_wait` on a deadline comfortably above that so a
    // regression to an UNBOUNDED head-read (spinning on the dribble) is caught LOUD as a hang.
    let deadline = Instant::now() + Duration::from_secs(20);
    let exited = loop {
        match dash.try_wait() {
            Ok(Some(status)) => break Some(status),
            Ok(None) if Instant::now() < deadline => std::thread::sleep(Duration::from_millis(50)),
            Ok(None) => break None,
            Err(_) => break None,
        }
    };

    let mut out = String::new();
    if let Some(mut so) = dash.stdout.take() {
        let _ = so.read_to_string(&mut out);
    }
    let mut err = String::new();
    if let Some(mut se) = dash.stderr.take() {
        let _ = se.read_to_string(&mut err);
    }

    // Reap a hung dash (if any) BEFORE asserting, then let the dribbler wind down.
    if exited.is_none() {
        let _ = dash.kill();
        let _ = dash.wait();
    }
    let _ = dribbler.join();

    let status = exited.unwrap_or_else(|| {
        panic!(
            "`rigger dash` never exited within the deadline against a dribbling holder - the \
             singleton probe's head-read must be time-bounded, never spin on a slow byte dribble; \
             stdout: {out:?} stderr: {err:?}"
        )
    });
    assert!(
        !status.success(),
        "a dribbling non-dash holder must be a genuine conflict (non-zero exit), never a serving \
         singleton to defer to; stdout: {out:?} stderr: {err:?}"
    );
    assert!(
        err.to_lowercase().contains("in use"),
        "the conflict must surface as an address-in-use error on stderr; stdout: {out:?} \
         stderr: {err:?}"
    );
    assert!(
        !out.contains("already serving"),
        "a dribbling non-dash holder must NOT be mistaken for an already-serving dash (no false \
         singleton defer); stdout: {out:?} stderr: {err:?}"
    );
}

/// Spec 50, criterion 1, the public `dash_serving_on` two-sided CONTRACT, driven by name from the
/// integration crate (as the sibling tests drive `bind_singleton`): it returns TRUE for a REAL
/// serving `rigger dash` (recognized by its `X-Rigger-Dash` header) and FALSE for an unrelated
/// process that merely holds the port and never answers. This is the precise input/output edge of
/// the probe that the singleton short-circuit hinges on (a real dash defers, a non-dash
/// conflicts), stated directly rather than only by consequence of the CLI behavior tests. The real
/// dash is reaped BEFORE the assertion so a failure never leaks a dashboard.
#[test]
fn dash_serving_on_recognizes_a_real_dash_and_rejects_a_non_dash_holder() {
    use rigger::dash::dash_serving_on;

    // Case 1 - a REAL serving `rigger dash`: `dash_serving_on` must recognize it (TRUE).
    let proj = temp_project();
    let root = proj.path();
    let dash_port = free_loopback_port();
    let mut dash = serving_dash(root, dash_port);
    let recognized_real = dash_serving_on(dash_port);

    // Case 2 - a NON-dash holder that never answers the probe: `dash_serving_on` must reject it
    // (FALSE), bounded by its own read timeouts (the silent-holder half of the boundedness the
    // dribble test drives). Keeping the listener in scope holds the port for the whole probe.
    let non_dash = reserved_loopback_listener();
    let non_dash_port = non_dash.local_addr().unwrap().port();
    let recognized_non_dash = dash_serving_on(non_dash_port);

    // Reap the serving dash BEFORE asserting so a failure never leaks a dashboard.
    let _ = dash.kill();
    let _ = dash.wait();
    drop(non_dash);

    assert!(
        recognized_real,
        "dash_serving_on must recognize a REAL serving `rigger dash` by its `{}` header",
        rigger::dash::DASH_HEADER
    );
    assert!(
        !recognized_non_dash,
        "dash_serving_on must NOT recognize a non-dash holder that never sends the recognition \
         header - only a genuine dash earns the singleton defer"
    );
}

/// The content script checks the whole spec diff when handed a base and only the branch's own
/// changes without one. Run with `$RIGGER_RUN_BASE` on a check-in branch cut from the run branch
/// after an operator commit landed there directly, each check fails on that commit's em dash or
/// process-ending shell-out, though the check-in branch's own commit is clean. Run with no base on
/// the very same tree - a unit's shape - it keeps the run branch as its base, judges only the
/// branch's own clean commit and passes.
#[test]
fn the_content_script_checks_the_whole_spec_from_a_base_and_only_the_branch_without_one() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    // The repository's gate scripts sit in the run's base commit, as in every unit worktree.
    let dir = temp_git_project_with_commit();
    let repo = dir.path();
    let scripts: Vec<(String, String)> = std::fs::read_dir(root.join(".rigger/gates"))
        .unwrap()
        .map(|entry| {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_str().unwrap().to_string();
            (
                format!(".rigger/gates/{name}"),
                std::fs::read_to_string(&path).unwrap(),
            )
        })
        .collect();
    let files: Vec<(&str, &str)> = scripts
        .iter()
        .map(|(rel, text)| (rel.as_str(), text.as_str()))
        .collect();
    let base = common::git::commit_files(repo, &files, "the run's base");
    git_ok(repo, &["checkout", "-q", "-b", "rigger-run"]);
    // Assembled at runtime, so this file's own source carries neither shape.
    let utility = ["ki", "ll"].concat();
    let landed = format!(
        "// a dash \u{2014} here\npub fn stop() {{ let _ = std::process::Command::new(\"{utility}\"); }}\n"
    );
    common::git::commit_files(repo, &[("src/lib.rs", &landed)], "an operator commit");
    git_ok(repo, &["checkout", "-q", "-b", "rigger/u/checkin"]);
    common::git::commit_files(
        repo,
        &[("README.md", "clean\n")],
        "the check-in's own commit",
    );

    let run_gate = |run: &str| {
        let out = Command::new("sh")
            .arg("-c")
            .arg(run)
            .current_dir(repo)
            .env("RIGGER_RUN_BASE", &base)
            .output()
            .expect("sh must spawn");
        let text = format!(
            "{}{}",
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        );
        (out.status.success(), text)
    };
    for check in ["style", "no-os-kill"] {
        let (passed, out) = run_gate(&format!(
            "sh .rigger/gates/content.sh {check} \"$RIGGER_RUN_BASE\""
        ));
        assert!(
            !passed && out.contains("gate FAILED"),
            "`{check}` handed the run base must find the operator commit's shape in the whole \
             spec diff: {out}"
        );
        let (passed, out) = run_gate(&format!("sh .rigger/gates/content.sh {check}"));
        assert!(
            passed,
            "`{check}` with no base must judge only the branch's own clean commit: {out}"
        );
    }
}

/// Round-9 escalation-remedy reject (adj-u69c1r9-verdict-reject upholding
/// adv-u69c1-mismatched-marker-suppression-borrows-wrong-files-mtime): the mismatched-marker
/// arm above always sourced `dash_breadcrumb_written_at` from the MARKER's mtime, even in this
/// exact branch where the marker's port does NOT match the url's own port and the
/// classification is driven entirely by the url (the sibling test above proves the url's port
/// is what gets probed and reported, never the marker's). That contradicts the function's own
/// doc comment, which requires the mtime gathered to be "of WHICHEVER file actually backed the
/// classification... so the two can never point at different files" (src/main.rs, the comment
/// above the `(recorded, marker)` match). Sourcing the wrong file's mtime lets a STALE marker
/// that predates this run's own `RunStarted` wrongly suppress a FRESH, currently-dead url that
/// this run's own dash-launching invocation wrote AFTER `RunStarted` - exactly the multi-process
/// shape `main.rs`'s own doc comment on `ensure_run_dashboard` describes ("two concurrent
/// harnesses each get their own [port]"), not a contrived edge case: both breadcrumb files are
/// project-level singletons never removed once their dash exits, so an old marker outliving a
/// fresh url write is ordinary.
///
/// This seeds exactly that shape: a stale marker written BEFORE `RunStarted` (so the
/// pre-existing `breadcrumb_predates_this_run` fallback would suppress if it read the marker's
/// mtime, the identical ordering
/// `watch_once_reports_no_dash_anomaly_for_a_fresh_run_that_inherits_an_earlier_runs_dead_marker`
/// above proves suppresses for the marker-only arm), then a DIFFERENT, later invocation writes a
/// fresh `dash.url` naming a different, currently-dead port AFTER `RunStarted`. No
/// `.rigger/dash.attempt` is written at all, so the round-8 same-run short-circuit
/// (`dash_attempted_this_run`) is not what makes this report - only the timestamp fallback is in
/// play, and it must read the URL's own mtime (fresh, postdating `RunStarted`), not the stale
/// marker's, to reach the correct "report it" answer.
#[test]
fn watch_once_reports_a_mismatched_dead_url_when_only_the_stale_marker_predates_run_started() {
    use rigger::dash::DashMarker;

    let proj = temp_store_project();
    let root = proj.path();

    // The stale marker, written FIRST, before this run's own RunStarted - the same
    // predates-this-run shape the inherited-marker sibling test proves suppresses when it is
    // the file backing the classification. Here it must NOT back the classification, since the
    // url's own port is what gets probed below.
    let marker_port = free_loopback_port();
    let marker_pid = u32::MAX;
    DashMarker {
        port: marker_port,
        pid: marker_pid,
    }
    .write(&root.join(".rigger/dash.marker"))
    .expect("seed the stale, pre-run dash marker");

    // The same filesystem-mtime safety margin every sibling test in this file uses, so this
    // run's own RunStarted lands unambiguously AFTER the marker write.
    std::thread::sleep(std::time::Duration::from_millis(50));

    seed_run_events(
        root,
        &[
            ("RunStarted", r#"{"run":"r1","criteria":["spec 69"]}"#),
            ("UnitStarted", r#"{"id":"u1","agent":"worker"}"#),
        ],
    );

    // Another margin so the fresh url write below lands unambiguously AFTER RunStarted too -
    // it must read as this run's OWN breadcrumb, not an inherited one.
    std::thread::sleep(std::time::Duration::from_millis(50));

    // A DIFFERENT dash-launching invocation than the one that wrote the marker: a fresh
    // dash.url, written after RunStarted, naming a different, currently-dead port. No
    // dash.marker rewrite here - the marker on disk stays the stale one from before RunStarted,
    // and its port differs from this url's, so this is the mismatched-marker arm.
    let url_port = free_loopback_port();
    assert_ne!(
        url_port, marker_port,
        "the ledger must never repeat a port within one test"
    );
    std::fs::write(
        root.join(".rigger/dash.url"),
        format!("http://127.0.0.1:{url_port}/"),
    )
    .expect("seed the fresh dash.url");

    // No .rigger/dash.attempt at all: the round-8 same-run short-circuit must play no part in
    // this report - only the timestamp fallback, correctly sourced from the url's own mtime.
    assert!(!root.join(".rigger/dash.attempt").exists());

    let (out, err, ok) = run_rigger(root, &["watch", "--once"]);
    assert!(
        ok,
        "rigger watch --once must exit 0 for a mismatched marker/url pair; stderr:\n{err}"
    );
    assert!(
        out.contains("dash liveness") && out.contains(&format!("port {url_port}")),
        "a fresh dash.url written AFTER this run's own RunStarted must be reported as a dead \
         dash even though the on-disk marker is stale and mismatched - the mtime backing the \
         predates-this-run comparison must come from the url that actually decided the \
         classification, not the marker that did not; got:\n{out}"
    );
    assert!(
        !out.contains(&marker_pid.to_string()),
        "the stale, mismatched marker's pid must never be named as this url's; got:\n{out}"
    );
}

/// Round 5 (adj-u62c1r4-verdict-reject-sentinel-pid-leaks-to-status,
/// sdet-u62c1r4-unattributed-pid-sentinel-renders-as-a-fabricated-dead-pid): the MATCHING-port
/// counterpart of the mismatched-marker sibling above, over the sentinel pid instead of a real
/// one. `.rigger/dash.marker` and `.rigger/dash.url` name the SAME port (so `pid_if_port_matches`
